insert into public.lesson_bodies(lesson_id, body) values ('0da28f09-cd72-7827-8df5-f332a748a6dc','[{"h":"Hayot haqidagi fan","ic":"🌍","p":["Atrofga qarang: daraxt, mushuk, o''zingiz, hatto ko''zga ko''rinmas bakteriyalar ham tirik.","Ularning hammasini o''rganadigan fan – **biologiya**.","Bios – hayot, logos – fan."],"q":"Sizningcha, tirik narsa bilan jonsiz narsaning eng katta farqi nima?","a":"Tirik narsa oziqlanadi, o''sadi, ko''payadi, tashqi ta''sirga javob beradi. Tosh bularni qilmaydi. (Buni keyingi mavzuda batafsil ko''ramiz.)"},{"h":"Nega bitta fan emas, o''nta?","ic":"🧩","p":["Tirik tabiat juda katta. Kitobni boblarga bo''lganimiz kabi, biologiya ham bo''limlarga bo''lingan.","Hamma bo''limning nomi o''rganadigan narsasini aytib turadi.","Masalan: *zoo* – hayvon, *bota* – o''t-o''simlik, *sito* – hujayra."]},{"h":"Eng muhim bo''limlar","ic":"📚","p":["**Botanika** – o''simliklar. **Zoologiya** – hayvonlar. **Mikologiya** – zamburug''lar.","**Mikrobiologiya** – mikroblar. **Sitologiya** – hujayra.","**Anatomiya** – ichki tuzilish. **Fiziologiya** – ishlash jarayonlari.","**Sistematika** – guruhlash. **Genetika** – irsiyat. **Ekologiya** – muhit bilan aloqa."],"q":"Quyon yaproqni qanday hazm qiladi? Bu savolga qaysi bo''lim javob beradi?","a":"Fiziologiya – chunki bu organizmdagi jarayon (hazm qilish)."},{"h":"Anatomiya va fiziologiya – farqi nimada?","ic":"🫀","p":["Anatomiya savoli: yurak qanday tuzilgan? Nechta xonasi bor?","Fiziologiya savoli: yurak qanday ishlaydi? Qonni qanday haydaydi?","Tuzilish – anatomiya, ish – fiziologiya. Soatning ichiga qarash va soat qanday yurishini kuzatishga o''xshaydi."]},{"h":"Dehqon va chorvador uchun","ic":"🌾","p":["Paxta qachon va qancha suv talab qilishini bilgan dehqon hosilni oshiradi.","Qo''yni to''g''ri boqishni bilgan chorvador kam yo''qotadi.","Bilim – bu pul, mehnat va vaqtni tejash."],"q":"Dehqon o''simlikning qaysi xususiyatlarini bilishi kerak?","a":"Qanday tuproq, qancha suv, yorug''lik va issiqlik kerakligini, qaysi kasallik va zararkunandalar xavf solishini."},{"h":"Tabiat dorixonasi","ic":"🌿","p":["Dorivor o''simliklar ko''p kasallikka shifo beradi.","Hatto ilon, asalari, qoraqurt zahri ham **juda oz va to''g''ri miqdorda** dori bo''ladi.","Shuning uchun dorivor o''simlikni zaharlisidan ajrata bilish hayotiy muhim."],"q":"Nima uchun zahar bir holda o''ldiradi, boshqa holda davolaydi?","a":"Hammasi miqdorga bog''liq. Mutaxassis aniq miqdorni hisoblaydi; o''zboshimchalik bilan ishlatish xavfli."},{"h":"Sog''lom bo''lish – biologiya ham","ic":"🥗","p":["Farobiy: kasalliklar ko''pincha noto''g''ri ovqatlanishdan.","Meva-sabzavotda vitamin va mineral moddalar bor, tanamizga ular kerak.","Tanani bilish – o''z sog''ligimizni asrash uchun birinchi qadam."]},{"h":"Inson va tabiat","ic":"🌳","p":["Biz suv ichamiz, ekin sug''oramiz, daraxt kesamiz, dori sepamiz – ya''ni tabiatga doim ta''sir qilamiz.","Biologiyani bilsak, zararni kamaytiramiz va boyliklarni tugatib qo''ymaymiz."],"q":"Bitta daraxt kesilsa nimalar o''zgaradi? Kamida uchta oqibatni ayting.","a":"Soya va kislorod kamayadi, qushlar uyasiz qoladi, tuproq yuvilib ketishi mumkin."},{"h":"O''zbek olimlari","ic":"🔬","p":["**To''raqulov** – tuzga yod qo''shib buqoqni davolagan.","**Musayev** – g''o''za kolleksiyasini yaratgan genetik.","**Mavloniy** – mikrobiologiya; **Azimov** – hayvon parazitlari; **Rahimova** – cho''l o''simliklari; **Pratov** – botanika.","Siz ham ularning o''rnini egallashingiz mumkin."],"q":"Siz olim bo''lsangiz, qaysi sohani tanlardingiz va nima uchun?","a":"Bu savolning to''g''ri javobi yo''q – eng muhimi, sababini aniq tushuntirish. Bunday fikrlash biologning asosiy ko''nikmasi."}]');
