insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b84927fc-96dc-95fd-467b-ae27c9fd6824','b2926941-cd70-bfb0-d0b5-594f74ea00ad',4,'1-§. Biologiya – hayot haqidagi fan','Ona-bola o''rtasida belgilar qanday o''tishini o''rganadigan fan qaysi?','Genetika','["Ekologiya","Botanika","Sitologiya"]','Genetika – irsiyat va o''zgaruvchanlik haqidagi fan.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4e1c94df-369a-7fc7-349e-621357743c67','b2926941-cd70-bfb0-d0b5-594f74ea00ad',5,'1-§. Biologiya – hayot haqidagi fan','Quyidagilardan qaysi biri ekologiyaga tegishli savol?','Quyonlar soni kamayganda tulkilarga nima bo''ladi?','["Quyonning yuragi nechta xonali?","Quyon hujayrasida nimalar bor?","Quyon qaysi guruhga kiradi?"]','Ekologiya organizmlarning bir-biri bilan aloqasini o''rganadi.');
