insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b08d078a-c0fb-3ad4-6872-966367ae6465','b2926941-cd70-bfb0-d0b5-594f74ea00ad',8,'1-§. Biologiya – hayot haqidagi fan','Ilon zahridan odamlar nima maqsadda foydalanadi?','Oz va to''g''ri miqdorda dori sifatida','["Ovqat sifatida","Kiyim bo''yash uchun","Suvni tozalash uchun"]','Mutaxassislar zahar miqdorini aniq hisoblab, kasallik davolashda ishlatadi.');
