insert into public.lesson_bodies(lesson_id, body) values ('c8b6e438-fb18-cbaf-8971-7c6e19d1e349','[{"h":"Tosh tirikmi?","ic":"🪨","p":["Tosh turibdi, o''zgarmaydi, hech narsa yemaydi.","Mushuk esa yeydi, o''sadi, o''ynaydi.","Demak, farq bor. Keling, o''sha farqni aniq belgilarga ajratamiz."],"q":"Olov ham «o''sadi» va «yeydi» (o''tinni). Nima uchun u tirik emas?","a":"Olov ko''paymaydi, nafas olmaydi, hujayradan iborat emas va o''zini tiklay olmaydi. Faqat bitta belgi yetmaydi, hamma belgilar birga bo''lishi kerak."},{"h":"1. Moddalar almashinuvi","ic":"🔄","p":["Tanamiz doim ichida «qurilish» va «buzish» ishi bilan band.","**Qurilish** (assimilyatsiya): oziqdan o''zimizga kerakli narsa yasaymiz – energiya sarflanadi.","**Buzish** (dissimilyatsiya): oziqni parchalaymiz – energiya hosil bo''ladi."],"q":"Ovqat hazm bo''lishi – qurilishmi yoki buzish?","a":"Buzish (dissimilyatsiya): murakkab oziq mayda qismlarga parchalanadi va energiya ajraladi."},{"h":"2. Oziqlanish: o''zi pishiruvchi va tayyorni yeyuvchi","ic":"🍃","p":["**Avtotrof** – oziqni o''zi yasaydi (yashil o''simlik quyosh nuridan).","**Geterotrof** – tayyor oziq qidiradi (hayvon, zamburug'', ko''p bakteriyalar).","Avto – o''zi, getero – boshqa."],"q":"Bo''ri quyonni yeydi, quyon o''tni yeydi. Kim avtotrof?","a":"Faqat o''t (o''simlik). Quyon ham, bo''ri ham geterotrof."},{"h":"3–4. Nafas va ayirish","ic":"💨","p":["Nafas: kislorod kiradi, karbonat angidrid chiqadi.","Quruqlikdagilar havo kislorodi bilan, suvdagilar suvda erigan kislorod bilan nafas oladi.","Ayirish – tanani «chiqindidan tozalash»: karbonat angidrid, mochevina, ortiqcha tuzlar."],"q":"Baliq suvdan chiqarib qo''yilsa nega halok bo''ladi?","a":"U suvda erigan kislorod bilan nafas oladi. Quruqlikda bu kislorodni ola olmaydi."},{"h":"5–6. Ta''sirlanish va harakat","ic":"⚡","p":["Tipratikanga tegsangiz – yumaloq bo''ladi. Mimoza bargi – yumiladi. Bu ta''sirlanish.","Hayvonlar faol harakatlanadi: yuguradi, uchadi, suzadi.","O''simlik passiv harakatlanadi: barg yorug''likka burilishi, kungaboqarning quyoshga qarashi."],"q":"Nima uchun hayvonlarga faol harakat kerak, o''simlikka esa unchalik emas?","a":"Hayvon oziqni izlashi va dushmandan qochishi kerak. O''simlik oziqni o''zi yasaydi va joyida turib quyosh va suvni oladi."},{"h":"7. Ko''payish","ic":"🐣","p":["**Jinssiz** – bitta organizm ishtirok etadi (bo''linish, kurtaklanish, spora).","**Jinsiy** – ikkita organizm; irsiy xususiyatlar aralashadi. Ishtirok etuvchi hujayralar – gametalar.","Ko''payish turni yo''qolishdan saqlaydi."]},{"h":"8. O''sish va rivojlanish","ic":"🌱","p":["**O''sish** – kattalashish (miqdor).","**Rivojlanish** – o''zgarish (sifat): barg yozish, gullash, meva tugish.","Ikkalasi doim birga ketadi, lekin bir xil narsa emas."],"q":"Kuchukcha katta itga aylanishi o''sishmi yoki rivojlanishmi?","a":"Ikkalasi: kattalashadi (o''sish), tishlari almashadi, tana nisbatlari o''zgaradi (rivojlanish)."},{"h":"Xulosa: tirik bo''lish uchun nima kerak?","ic":"✅","p":["Moddalar almashinuvi, oziqlanish, nafas, ayirish, ta''sirlanish, harakat, ko''payish, o''sish-rivojlanish.","Faqat bittasi bor narsa tirik emas, **hammasi** birga bo''lishi kerak."],"q":"Robot yuradi, «ovqat» sifatida batareya oladi. Uni tirik deyish mumkinmi?","a":"Yo''q: u ko''paymaydi, o''smaydi, nafas olmaydi, moddalar almashinuvi yo''q. Faqat ba''zi belgilarga o''xshaydi."}]');
