insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('30c57a62-555d-9b87-6f3b-ff8340b4eba1','b35629e2-b77b-88fe-f54a-b40f0e44f999',1,'2-§. Tirik organizmlarning xususiyatlari','Qaysi organizm avtotrof?','Yashil o''simlik','["Zamburug''","Quyon","Bo''ri"]','Yashil o''simlik oziqni quyosh nuridan o''zi hosil qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('d51ab467-fbb1-48a1-ba41-75fac7f15ae6','b35629e2-b77b-88fe-f54a-b40f0e44f999',2,'2-§. Tirik organizmlarning xususiyatlari','Assimilyatsiya jarayonida nima sodir bo''ladi?','Yangi moddalar hosil bo''ladi, energiya sarflanadi','["Moddalar parchalanib energiya ajraladi","Zararli moddalar chiqariladi","Gametalar qo''shiladi"]','Assimilyatsiya – sintez, qurilish jarayoni.');
