insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('d1a5fb76-c2e5-4a21-6f50-1c5b92c4ffe6','b35629e2-b77b-88fe-f54a-b40f0e44f999',5,'2-§. Tirik organizmlarning xususiyatlari','Jinsiy ko''payishda nima ro''y beradi?','Ikki organizm ishtirok etadi va irsiy axborot almashinadi','["Bitta organizm ikkiga bo''linadi","Kurtak hosil bo''ladi","Faqat spora tarqaladi"]','Jinsiy ko''payishda gametalar qo''shiladi.');
