insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('29b332e3-eda3-88fe-f334-7398e0550aa0','b35629e2-b77b-88fe-f54a-b40f0e44f999',9,'2-§. Tirik organizmlarning xususiyatlari','Quyidagilardan qaysi biri geterotrof?','Zamburug''','["Olma daraxti","Lola","Bug''doy"]','Zamburug''lar tayyor organik moddalar bilan oziqlanadi.');
