insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('47ad09ff-7ed1-e73f-4f7a-bfd91a9b99cf','cfca990c-7260-78a3-24cb-72e7769f1367',0,'1–2-§ takrorlash','Hayvonning ovqatni hazm qilish jarayonini qaysi fan o''rganadi va bu tirik organizmning qaysi xususiyatiga tegishli?','Fiziologiya; moddalar almashinuvi','["Anatomiya; ko''payish","Botanika; ta''sirlanish","Sistematika; nafas olish"]','Jarayonni fiziologiya o''rganadi, hazm qilish esa moddalar almashinuvining bir qismi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('fb601ad0-b94a-db7e-0b8b-0665544d7851','cfca990c-7260-78a3-24cb-72e7769f1367',1,'1–2-§ takrorlash','Botanika qaysi organizmlarni o''rganadi va ular qanday oziqlanadi (yashil qismlari bo''yicha)?','O''simliklarni; ko''pchiligi avtotrof','["Hayvonlarni; geterotrof","Zamburug''larni; avtotrof","Bakteriyalarni; hammasi avtotrof"]','Yashil o''simliklar oziqni o''zi hosil qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('75aac1d3-5481-1427-5738-bcfac4e01cdd','cfca990c-7260-78a3-24cb-72e7769f1367',2,'1–2-§ takrorlash','Zoologiya hayvonlarni o''rganadi. Quyonning o''t yeyishi tirik organizmning qaysi xususiyatiga tegishli va u qaysi usulda oziqlanadi?','Oziqlanish; geterotrof','["Ko''payish; avtotrof","Ta''sirlanish; avtotrof","Ayirish; geterotrof"]','Quyon tayyor oziq (o''t) bilan oziqlanadi, ya''ni geterotrof.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('5eea1a19-31cb-13c1-0243-e20421f1d176','cfca990c-7260-78a3-24cb-72e7769f1367',3,'1–2-§ takrorlash','Ekolog cho''ldagi o''simlikning issiqqa javobini o''rganmoqda. Bu qaysi xususiyatga yaqin?','Ta''sirlanish','["Ko''payish","Jinsiy ko''payish","Assimilyatsiya"]','Muhit ta''siriga javob – ta''sirlanish.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('c43bb0d7-cf86-f1b7-26da-8db48c62bec9','cfca990c-7260-78a3-24cb-72e7769f1367',4,'1–2-§ takrorlash','Genetika qaysi tirik xususiyat bilan eng bog''liq?','Ko''payish – irsiy axborot avlodga o''tishi','["Nafas olish","Ayirish","Harakatlanish"]','Irsiyat nasl qoldirish bilan bog''liq.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('27aa4821-afaa-c9df-cb3d-346713aacce3','cfca990c-7260-78a3-24cb-72e7769f1367',5,'1–2-§ takrorlash','Sitologlar hujayra ichida energiya ajralishi jarayonini o''rganmoqda. U qaysi qismga to''g''ri keladi?','Dissimilyatsiya','["Assimilyatsiya","Rivojlanish","Passiv harakat"]','Energiya ajralishi parchalanish (dissimilyatsiya) bilan bog''liq.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('3f801620-a94c-d4ee-7940-0cda921cd1ae','cfca990c-7260-78a3-24cb-72e7769f1367',6,'1–2-§ takrorlash','Nima uchun bitta belgi (masalan, harakat) bilan organizmni tirik deb bo''lmaydi?','Tirik bo''lish uchun barcha belgilar birga bo''lishi kerak','["Chunki harakat faqat o''simlikda bo''ladi","Chunki tirik narsa harakat qilmaydi","Chunki belgilar faqat bakteriyada bor"]','Masalan, bulut ham «harakat» qiladi, lekin tirik emas.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('0208ae2b-1af5-c1b0-966e-afb35668ae54','cfca990c-7260-78a3-24cb-72e7769f1367',7,'1–2-§ takrorlash','Sistematika organizmlarni guruhlaydi. Quyidagi belgilardan qaysi biri guruhlash uchun oqilona asos?','Oziqlanish usuli (avtotrof yoki geterotrof)','["Rangining chiroyligi","Qaysi odamga yoqishi","Nomining uzunligi"]','Guruhlash o''xshash muhim belgilarga asoslanadi.');
