insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('13d9f83c-8c80-fb05-e344-c4a871717b32','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','9bd4daec-af8f-dca6-b580-baaa79e1f431','{"uz":"Slayd: Biologiyaning o''rganish usullari","ru":"Slayd: Biologiyaning o''rganish usullari","en":"Slayd: Biologiyaning o''rganish usullari"}','slides',null,'',10,10);
insert into public.lesson_bodies(lesson_id, body) values ('13d9f83c-8c80-fb05-e344-c4a871717b32','[{"h":"Savol tug''ilganda...","ic":"🤔","p":["Qush uyasini qanday qurishi qiziq. Qanday aniqlaymiz?","Tabiatda nimadir noma''lum bo''lsa, olim uni to''rt yo''ldan biri bilan tekshiradi.","Bu yo''llar – o''rganish usullari."]},{"h":"1-usul: Kuzatish","ic":"👀","p":["Tabiatga aralashmaymiz, faqat ko''ramiz, eshitamiz va yozib boramiz.","Eng qadimgi usul.","Hozir videokamera va kuzatuv chipi ham yordam beradi."],"q":"Nima uchun yovvoyi qushni kuzatganda uyasiga tegmaslik kerak?","a":"Tegsak, qush bezovta bo''ladi va xulq-atvori tabiiy bo''lmay qoladi – ma''lumot noto''g''ri chiqadi."},{"h":"2-usul: Taqqoslash","ic":"⚖️","p":["Ikkita narsani yonma-yon qo''yamiz: nimasi o''xshash, nimasi farq?","Oq va qo''ng''ir ayiq: ikkalasi ham tirik, nafas oladi (o''xshash), ammo yashash joyi va rangi boshqa (farq)."],"q":"Mushuk va it nimasi bilan o''xshash va nimasi bilan farq qiladi?","a":"O''xshash: sut emizuvchi, junli, 4 oyoqli. Farq: oziqlanishi, ovozi, xulqi, tirnoqlari."},{"h":"3-usul: Tarixiy usul","ic":"🦴","p":["Qadimgi jonzotlar qoldiqlarini hozirgilar bilan solishtiramiz.","Ot qadimda tulkidek yirtqich bo''lgan. Zamonlar o''tib oyoqlari uzaydi, tuyoq paydo bo''ldi, o''tni yeydigan bo''ldi.","Shunday qilib, organizmlar qanchalik o''zgarganini bilamiz."],"q":"Otning uzun oyoqlari unga qanday foyda beradi?","a":"Tez chopib dushmandan qochadi va ozuqa uchun uzoq masofani tez bosib o''tadi."},{"h":"4-usul: Tajriba","ic":"🧪","p":["Biz sharoitni **o''zimiz** yaratamiz va natijani kuzatamiz.","Oq gulni bo''yoqli suvga solamiz. 2 soatdan keyin guli rangi o''zgaradi.","Xulosa: o''simlik suvni poyasi orqali tortadi."],"q":"Tajribada nega bitta guldan emas, bir nechta guldan foydalangan yaxshi?","a":"Natija tasodif emasligiga ishonch hosil qilish uchun. Takrorlangan natija ishonchliroq."},{"h":"Redi tajribasi","ic":"🍖","p":["3 ta idish, hammasida go''sht: **ochiq**, **zich yopiq**, **doka bilan yopiq**.","Faqat ochiq idishda qurt va pashsha chiqdi.","Doka havoni o''tkazadi, lekin pashshani to''sadi."],"q":"Bu tajribadan qanday xulosa chiqadi? Qaysi usullar ishlatilgan?","a":"Qurtlar go''shtdan o''zi paydo bo''lmaydi, pashsha tuxum qo''ygani uchun chiqadi. Tajriba va kuzatish usullari ishlatilgan."},{"h":"Lupa va mikroskop","ic":"🔍","p":["Lupa 2–20 marta kattalashtiradi. Tarvuz mag''zini lupada ko''rsak, yumaloq hujayralar sezila boshlaydi.","Mikroskop undan ham kuchli.","**Kattalashtirish = okulyar × obyektiv.** 10 × 20 = 200 marta."],"q":"Okulyar 10, obyektiv 40 bo''lsa, mikroskop necha marta kattalashtiradi?","a":"10 × 40 = 400 marta."},{"h":"Mikroskopda ishlash tartibi","ic":"🔬","p":["1. Mikroskopni stol chetidan 3–4 sm ichkariga qo''ying.","2. Ko''zguni yorug''likka qarating.","3. Preparatni stolchaga qo''yib, qisqich bilan qotiring.","4. Avval **kichik obyektivda**, keyin kattasida qarang.","5. Makrovintda tasvirni toping, mikrovintda tiniqlashtiring.","6. Ishdan keyin artib, joyiga qo''ying."],"q":"Nega avval kichik obyektivda qaraladi?","a":"Maydon kengroq, preparatni topish oson va obyektiv preparatga tegib, oynani sindirib qo''ymaydi."}]');
