insert into public.lesson_bodies(lesson_id, body) values ('f5ef6687-9ba2-e204-cbb7-74367e4347d5','[["tf","Kuzatish usuli","Tabiiy holatga ta''sir qilmagan holda ma''lumot to''plash",true],["tf","Taqqoslash usuli","Qadimgi organizmlarni hozirgilari bilan solishtirish",false],["tf","Tarixiy usul","Qadimgi organizmlarni hozirgilari bilan solishtirish",true],["tf","Tajriba usuli","Organizm uchun maxsus sharoit yaratib, o''zgarishini o''rganish",true],["tf","Lupa","Juda murakkab, 2000 marta kattalashtiradigan asbob",false],["tf","Mikroskopning kattalashtirishi","Okulyar va obyektiv ko''rsatkichlarining ko''paytmasi",true],["type","Eng qadimgi o''rganish usuli","kuzatish",["kuzatish","kuzatish usuli"]],["type","Redi tajribasida qaysi hasharot paydo bo''ldi? (bir so''z)","pashsha",["pashsha"]],["type","Eng sodda kattalashtiruvchi asbob","lupa",["lupa"]],["type","Mikroskopda tasvirni topish uchun burab ko''tariladigan/tushiriladigan vint","makrovint",["makrovint"]],["type","Okulyar 10, obyektiv 20 bo''lsa necha marta kattalashadi? (raqam)","200",["200"]],["tf","Redi tajribasi","Qurtlar go''shtdan o''z-o''zidan paydo bo''ladi, deb isbotladi",false]]');
