insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('223b76a8-63f9-768c-fc5c-a4ae000e490f','205b7c1f-8b72-e523-b19e-a16df887afe8',0,'3-§. Biologiyaning o''rganish usullari','Tabiiy holatga ta''sir qilmay, sezgi organlari orqali ma''lumot to''plash qaysi usul?','Kuzatish','["Tajriba","Taqqoslash","Tarixiy usul"]','Kuzatishda tabiatga aralashilmaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a1a30f8c-cf8e-6eac-0be6-403a84782d60','205b7c1f-8b72-e523-b19e-a16df887afe8',1,'3-§. Biologiyaning o''rganish usullari','Oq va qo''ng''ir ayiqning o''xshash va farqli tomonlarini aniqlash qaysi usulda amalga oshadi?','Taqqoslash','["Kuzatish","Tarixiy usul","Tajriba"]','Ikki organizm o''zaro solishtiriladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('c1ffb8ab-f0d9-d66b-bace-9f3684f86e23','205b7c1f-8b72-e523-b19e-a16df887afe8',2,'3-§. Biologiyaning o''rganish usullari','Otlarning qadimgi ajdodlari haqida ma''lumot olish uchun qaysi usul kerak?','Tarixiy usul','["Kuzatish","Tajriba","Taqqoslash"]','Tarixiy usulda qadimgi va hozirgi organizmlar solishtiriladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('49adf5db-04a7-65b7-32ad-c267bc6dc790','205b7c1f-8b72-e523-b19e-a16df887afe8',3,'3-§. Biologiyaning o''rganish usullari','Oq gulning bo''yoqli suvda rangi o''zgarishini tekshirish qaysi usulga kiradi?','Tajriba','["Kuzatish","Tarixiy usul","Taqqoslash"]','Sharoit maxsus yaratiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b6888245-6874-5dc2-34ae-7ffcb0d072d5','205b7c1f-8b72-e523-b19e-a16df887afe8',4,'3-§. Biologiyaning o''rganish usullari','Redi tajribasida nega faqat ochiq idishda qurt paydo bo''ldi?','Pashsha faqat ochiq idishga tuxum qo''ya oldi','["Faqat ochiq idishdagi go''sht yangi edi","Yopiq idishda go''sht yo''q edi","Qurtlar havosiz tug''ilmaydi"]','Pashsha yopiq va doka bilan to''silgan idishga tuxum qo''ya olmadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('75f486e4-fd65-b826-3e60-b1b62dbf99c9','205b7c1f-8b72-e523-b19e-a16df887afe8',5,'3-§. Biologiyaning o''rganish usullari','Redi tajribasidagi doka bilan yopilgan idish nimani isbotlashga yordam berdi?','Havo kirsa ham, pashsha kirmasa qurt chiqmaydi','["Qurt faqat havosiz joyda chiqadi","Doka go''shtni buzadi","Pashsha dokani yeydi"]','Havo kirgan bo''lsa ham, pashsha kirmaganligi sababli qurt chiqmadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e8df2f5c-4cb3-1f4d-aa20-304a328ede56','205b7c1f-8b72-e523-b19e-a16df887afe8',6,'3-§. Biologiyaning o''rganish usullari','Qo''l lupasi buyumni necha marta kattalashtiradi?','2–20 marta','["100–200 marta","1000 marta","2000 marta"]','Lupa – eng sodda asbob.');
