insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('2c424b73-8cc8-2163-c686-4cb3d39ffc85','205b7c1f-8b72-e523-b19e-a16df887afe8',8,'3-§. Biologiyaning o''rganish usullari','Mikroskopda preparat dastlab qaysi obyektivda ko''riladi?','Kichik obyektivda','["Katta obyektivda","Ikkalasida bir vaqtda","Obyektivsiz"]','Kichik obyektivda qaralib, keyin kattasiga o''tiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('31ca2bf1-ba29-08ce-6c1c-f00af349cc60','205b7c1f-8b72-e523-b19e-a16df887afe8',9,'3-§. Biologiyaning o''rganish usullari','Tasvirni tiniqlashtirish uchun mikroskopning qaysi qismidan foydalaniladi?','Mikrovint','["Ko''zgu","Qisqich","Shtativ"]','Mikrovint tasvirni tiniqlashtiradi.');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('6e71a2f4-fe22-5924-8007-da697ba9f526','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','9bd4daec-af8f-dca6-b580-baaa79e1f431','{"uz":"Mavzu testi: Biologiyaning o''rganish usullari","ru":"Mavzu testi: Biologiyaning o''rganish usullari","en":"Mavzu testi: Biologiyaning o''rganish usullari"}','test','205b7c1f-8b72-e523-b19e-a16df887afe8','',25,12);
