insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('67812b68-0d63-6f35-8676-7fb2c0aad93f','bad1d1cc-b14f-a006-788e-bffb4a8b870d',0,'2–3-§ takrorlash','Zoolog suvsarning uyasi oldida kuzatuv olib bormoqda va uni boshqa hayvon bilan solishtirmoqda. U qaysi usullardan foydalanyapti?','Kuzatish va taqqoslash','["Tajriba va tarixiy usul","Faqat tajriba","Faqat tarixiy usul"]','Kuzatish – ma''lumot yig''ish, taqqoslash – solishtirish.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('7a01fc43-6cb9-eda2-d956-813c788b3b81','bad1d1cc-b14f-a006-788e-bffb4a8b870d',1,'2–3-§ takrorlash','Botanik oq gulni bo''yoq eritmasiga solib, 2 soatdan keyin rangini kuzatdi. Bu qaysi usul va qaysi xususiyatni tekshirish uchun?','Tajriba; o''simlikning suv tortishi','["Kuzatish; ko''payish","Tarixiy usul; harakat","Taqqoslash; nafas olish"]','Sharoit yaratib, o''simlikning moddalar tashishini ko''ramiz.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('144e54ab-4694-e3f5-f08d-9b837627c212','bad1d1cc-b14f-a006-788e-bffb4a8b870d',2,'2–3-§ takrorlash','Mikologiya zamburug''larni o''rganadi. Zamburug'' sporasini ko''rish uchun qaysi asbob kerak?','Mikroskop','["Faqat lupa","Pinset","Skalpel"]','Spora juda kichik, mikroskop kerak.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a25421eb-5f3e-9676-6920-db0244d6fe81','bad1d1cc-b14f-a006-788e-bffb4a8b870d',3,'2–3-§ takrorlash','Paleontolog qadimgi hayvon suyagini hozirgi hayvon suyagi bilan solishtirdi. U qaysi ikki usulni qo''lladi?','Tarixiy va taqqoslash','["Tajriba va kuzatish","Faqat kuzatish","Faqat tajriba"]','Qadimgi bilan hozirgini solishtirish – tarixiy usul, solishtirishning o''zi – taqqoslash.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e3183823-4818-f1f1-44b4-e6d1ef3eaec9','bad1d1cc-b14f-a006-788e-bffb4a8b870d',4,'2–3-§ takrorlash','Redi tajribasida pashsha go''shtga tuxum qo''ydi, tuxumdan qurt chiqdi. Bu tirik organizmning qaysi xususiyatiga misol?','Ko''payish (pashsha tuxum qo''ygan)','["Nafas olish","Ayirish","Ta''sirlanish"]','Pashsha ko''payib tuxum qo''yadi, undan qurt chiqadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('36b40117-2aa2-58c9-6523-454703517b3e','bad1d1cc-b14f-a006-788e-bffb4a8b870d',5,'2–3-§ takrorlash','Hayvonlarning qanday oziqlanishini mikroskopda ko''rib bo''lmaydi, uni qaysi usul bilan o''rganish qulay?','Kuzatish','["Faqat mikroskop","Faqat tarixiy usul","Hech qaysi usul"]','Odatda yirik hayvonlarning oziqlanishi kuzatish bilan o''rganiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9024a370-15a7-c991-6007-d6841eb67bf9','bad1d1cc-b14f-a006-788e-bffb4a8b870d',6,'2–3-§ takrorlash','Fiziologiya jarayonlarni o''rganadi. Quyidagilardan qaysi biri o''rganishda ko''proq tajriba usulini talab qiladi?','Issiqlikda o''simlik transpiratsiyasi qanday o''zgarishi','["Qadimgi otning tuzilishi","Qushlarning ko''chib o''tishi","Ayiqning rangi"]','Sharoit o''zgartirilib, natija o''lchanadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('420e7187-351d-5d6a-1323-88d5258ce047','bad1d1cc-b14f-a006-788e-bffb4a8b870d',7,'2–3-§ takrorlash','Olim nima uchun tajribani bir necha marta takrorlaydi?','Natija tasodif emasligini tekshirish uchun','["Vaqtni o''tkazish uchun","Idishlarni ko''paytirish uchun","Kuzatish usulini almashtirish uchun"]','Takrorlangan natija ishonchli bo''ladi.');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('e7983088-91c0-ea10-114b-026bb2737004','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','9bd4daec-af8f-dca6-b580-baaa79e1f431','{"uz":"Takrorlash testi: 2-§ va 3-§","ru":"Takrorlash testi: 2-§ va 3-§","en":"Takrorlash testi: 2-§ va 3-§"}','test','bad1d1cc-b14f-a006-788e-bffb4a8b870d','',25,13);
