insert into public.lesson_bodies(lesson_id, body) values ('2956cf46-9806-2eb8-bab4-4ca4fa1bae47','[{"h":"Eng kichik g''isht","ic":"🧱","p":["Uy g''ishtdan quriladi. Tirik organizm esa **hujayradan**.","Hujayra – tiriklikning eng kichik birligi.","Ko''pchilik hujayra ko''zga ko''rinmaydi, mikroskop kerak."],"q":"Hujayra juda kichik bo''lsa, nega organizm katta bo''lishi mumkin?","a":"Chunki organizmda milliardlab hujayra bor, ular birgalikda ishlaydi."},{"h":"Shakl – vazifaga qarab","ic":"🔴","p":["**Eritrotsit** – ikki tomoni botiq, kislorod tashiydi.","**Leykotsit** – soxta oyoqlari bor, mikrobni ushlaydi.","**Barg og''izchasi** – loviyasimon, suv bug''latadi.","**Nerv hujayrasi** – uzun o''simtalari bor, signal o''tkazadi."],"q":"Nerv hujayrasi nega uzun o''simtalarga ega?","a":"Signalni uzoq masofaga tez yetkazish uchun, xuddi sim kabi."},{"h":"Ikki oila: prokariot va eukariot","ic":"👪","p":["**Prokariot** – yadrosi alohida shakllanmagan (bakteriyalar, ko''k-yashil suvo''tlar).","**Eukariot** – yadrosi aniq shakllangan (zamburug'', o''simlik, hayvon).","Pro – oldin, eu – chin. Yadro «chin» bo''lsa – eukariot."],"q":"Odam qaysi guruhga kiradi?","a":"Eukariotlar: odam hujayralarida yadro aniq shakllangan."},{"h":"Hujayrada uchta asosiy qism","ic":"🏠","p":["**Membrana** – devor va darvoza: himoya qiladi, kerakli narsani kiritadi.","**Sitoplazma** – xona: ichida organoidlar «ishlaydi».","**Yadro** – boshqaruv xonasi: irsiy axborotni saqlaydi, ishni boshqaradi."],"q":"Agar yadro yo''qolsa nima bo''ladi?","a":"Hujayra boshqaruvdan mahrum bo''ladi va irsiy axborot saqlanmaydi, hujayra ishdan chiqadi."},{"h":"O''simlik va hayvon hujayrasi","ic":"🌿🐾","p":["**Ikkalasida bor:** membrana, sitoplazma, yadro.","**Faqat o''simlikda:** sellyuloza qobiq, plastidalar, yirik vakuola.","**Faqat hayvonda:** yupqa qobiq, qisqaruvchi va hazm qiluvchi mayda vakuola."],"q":"Nega o''simlikka sellyuloza qobiq kerak, hayvonga esa shart emas?","a":"O''simlik joyida turadi, shuning uchun mustahkam «suyak»siz qolmaydi. Hayvonda tayanch suyak, bo''g''imlar va mushaklar bor."},{"h":"Plastidalar – o''simlik ranglari","ic":"🍅","p":["**Xloroplast** – yashil (barg, yosh poya).","**Xromoplast** – rangli: sariq, qizil (gul, meva).","**Leykoplast** – rangsiz (ildiz, urug'').","Pomidor: yashil → oq → qizil. Plastidalar bir-biriga aylanishi mumkin."],"q":"Kuzda barg nega sarg''ayadi?","a":"Yashil xloroplast o''zgarib, sariq xromoplastga aylanadi. Shu sababli rangi o''zgaradi."},{"h":"Vakuola va meva ta''mi","ic":"🍋","p":["O''simlik vakuolasi hujayra shirasi bilan to''la (70–95% suv).","Organik kislota ko''p – **nordon** (limon).","Uglevod ko''p – **shirin** (uzum).","Hayvonda vakuola mayda va kattalasha olmaydi."],"q":"Olma pishgan sayin nega shirinlashadi?","a":"Vakuolada kislota kamayib, uglevodlar ko''payadi."},{"h":"Hujayradan organizmgacha","ic":"🌳","p":["**Hujayra** → **to''qima** (bir xil ishni bajaruvchi hujayralar) → **organ** (ildiz, barg) → **organizm**.","Zarang daraxti – organizm; barg – organ; barg to''qimalari – qoplovchi, o''tkazuvchi, asosiy."],"q":"Yurak – hujayra, to''qima, organ yoki organizm?","a":"Organ (mushak to''qimasi va boshqa to''qimalardan tuzilgan)."},{"h":"Piyoz po''sti tajribasi","ic":"🧅","p":["Piyozni to''rtga bo''lamiz, yupqa po''stini suv tomchisiga qo''yamiz, yod tomizamiz, qoplag''ich oyna bilan yopamiz.","Mikroskopda: zich silindrsimon hujayralar, sitoplazma, vakuola, yadro va sellyuloza qobiq ko''rinadi.","Yod yadro va sitoplazmani bo''yab ko''rsatadi."],"q":"Hujayra qobig''idagi teshikchalar nima uchun kerak?","a":"Suv va mineral moddalar bir hujayradan ikkinchisiga shu teshikchalar orqali o''tadi."}]');
