insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4e60c661-9a18-eaf5-2465-e9f815dea5f2','5737ba52-b216-5999-5712-e62e5b356d0e',3,'4-§. Hujayra – tiriklikning asosi','Quyidagilardan qaysi biri eukariot?','Zamburug''','["Bakteriya","Ko''k-yashil suvo''ti","Hech biri"]','Zamburug'', o''simlik va hayvonlar eukariot.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('786defc8-e570-d16b-216f-5dd7e0f66acc','5737ba52-b216-5999-5712-e62e5b356d0e',4,'4-§. Hujayra – tiriklikning asosi','Hujayraning irsiy axborotni saqlovchi va moddalar almashinuvini boshqaruvchi qismi qaysi?','Yadro','["Membrana","Sitoplazma","Vakuola"]','Yadro – hujayraning eng muhim qismi.');
