insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('131ebf57-0c70-d911-5b09-e308d8ad3c94','5737ba52-b216-5999-5712-e62e5b356d0e',7,'4-§. Hujayra – tiriklikning asosi','Meva nordon bo''lishi nimaga bog''liq?','Vakuolada organik kislotalar ko''pligiga','["Vakuolada uglevod ko''pligiga","Yadro kattaligiga","Sellyuloza qobiq qalinligiga"]','Kislota ko''p – nordon, uglevod ko''p – shirin.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('02e73a86-deb7-fbd8-e02f-67ac88832ca8','5737ba52-b216-5999-5712-e62e5b356d0e',8,'4-§. Hujayra – tiriklikning asosi','Hayvon hujayrasidagi qisqaruvchi vakuola qanday ish qiladi?','Ortiqcha suyuqlikni chiqarib yuboradi','["Oziqni hazm qiladi","Irsiy axborot saqlaydi","Yorug''likni yutadi"]','Hazm qiluvchi vakuola esa oziq moddalarni parchalaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('da7b4911-3a55-77d7-0935-a1dd3069d2fd','5737ba52-b216-5999-5712-e62e5b356d0e',9,'4-§. Hujayra – tiriklikning asosi','Bir xil vazifani bajaruvchi hujayralar yig''indisi nima deyiladi?','To''qima','["Organ","Organizm","Organoid"]','To''qimalar organni, organlar organizmni hosil qiladi.');
