insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('6a9c4408-01e9-9c83-c7d2-7f4f4530afa3','47af85c9-91a9-a884-a98a-a2bc4d30ab29',11,'1-§ Biologiya – hayot haqidagi fan','Genetika qanday savolga javob beradi?','Belgilar avlodlarga qanday o''tadi?','["Hujayra necha qismdan iborat?","Barg nega yashil?","Ilon qanday harakatlanadi?"]','Genetika – irsiyat va o''zgaruvchanlik.');
