insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b7eb0479-d2a0-c6ba-c8fb-a2b9c87a0f1c','47af85c9-91a9-a884-a98a-a2bc4d30ab29',14,'2-§ Tirik organizmlarning xususiyatlari','Nima uchun tirik organizmlarni bitta belgisiga qarab emas, belgilar majmuasiga qarab aniqlaymiz?','Chunki jonsiz narsalarda ham ayrim tirik belgilar o''xshab ko''rinishi mumkin','["Chunki belgilar juda ko''p","Chunki tirik narsada faqat bitta belgi bo''ladi","Chunki jonsiz narsa umuman o''zgarmaydi"]','Masalan, olov ham «yeydi», lekin tirik emas.');
