insert into public.lesson_bodies(lesson_id, body) values ('81699217-0f4d-7b93-7353-87a6c2bfbc91','## Tirik dunyo qanday guruhlarga bo''linadi?
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('992a8aa8-7842-ff1f-8b26-ef3f8a5b53c2','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','5f74a9b5-4631-ad80-4944-d4ed6bc7cbc7','{"uz":"Slayd: Tirik organizmlar haqida umumiy ma''lumot","ru":"Slayd: Tirik organizmlar haqida umumiy ma''lumot","en":"Slayd: Tirik organizmlar haqida umumiy ma''lumot"}','slides',null,'',10,21);
insert into public.lesson_bodies(lesson_id, body) values ('992a8aa8-7842-ff1f-8b26-ef3f8a5b53c2','[{"h":"Tirik dunyoni tartibga solamiz","ic":"🗂️","p":["Dunyoda millionlab tirik tur bor.","Kutubxonada kitoblar mavzusiga qarab javonlarga terilgani kabi, olimlar tirik organizmlarni **to''rt katta guruhga** ajratgan.","Bakteriyalar, zamburug''lar, o''simliklar, hayvonlar."],"q":"Nima uchun guruhlarga bo''lish kerak?","a":"Bunda har bir organizmni topish, o''rganish va bir-biri bilan solishtirish oson bo''ladi."},{"h":"Bakteriyalar: ko''zga ko''rinmas qo''shnilarimiz","ic":"🦠","p":["Prokariot, ya''ni yadrosi shakllanmagan.","Asosan geterotrof.","Atrofimizda doim bor, lekin faqat mikroskopda ko''rinadi."]},{"h":"Zamburug''lar: o''simlik ham, hayvon ham emas","ic":"🍄","p":["Eukariot, erkin harakat qilmaydi, geterotrof.","Tuproqqa ingichka ipchalar – **gifalar** bilan birikadi.","Achitqidan tortib qo''ziqorinlargacha."],"q":"Zamburug'' o''simlikka o''xshaydi, nega o''simlik emas?","a":"Chunki u yashil emas, fotosintez qilmaydi, tayyor oziq bilan oziqlanadi (geterotrof)."},{"h":"O''simliklar: yashil «fabrika»","ic":"🌿","p":["Flora – o''simlik dunyosi.","Xlorofill yordamida **fotosintez**: karbonat angidrid → kislorod va organik modda.","Erkin harakat qilmaydi, avtotrof."],"q":"O''simliklar bo''lmasa, havo kislorodiga nima bo''ladi?","a":"Kislorod kamayib ketadi, chunki uni asosan o''simliklar ajratadi."},{"h":"Hayvonlar: harakatchan sezgirlar","ic":"🦊","p":["Fauna – hayvonot dunyosi.","Erkin harakatlanadi, geterotrof.","Nerv sistemasi va sezgi organlari bor: ko''radi, eshitadi, ta''m biladi va javob qaytaradi."],"q":"Hayvonga nega nerv sistemasi kerak?","a":"Tashqaridan ma''lumot (xavf, oziq) olib, tez va to''g''ri javob berish uchun."},{"h":"Viruslar – oraliq mavjudot","ic":"🧬","p":["Hujayrasiz!","Hujayradan tashqarida tirik belgilarni ko''rsatmaydi.","Hujayraga kirsa – ko''payadi, hujayrani nobud qiladi.","Bu jonsiz va jonli tabiat orasidagi chegara."],"q":"Virus nega mustaqil yashay olmaydi?","a":"Uning o''z moddalar almashinuvi yo''q, ko''payish uchun hujayra oziqiga muhtoj."},{"h":"Virus kimni tanlaydi?","ic":"🎯","p":["Gepatit – jigar hujayralari.","Gripp va koronavirus – nafas yo''llari.","Gerpes – lab epiteliysi.","Bakteriyada – bakteriofag; o''simlikda – tamaki mozaikasi; hayvonda – quturish."],"q":"Gripp bo''lganda nima qilish kerak?","a":"Ko''p suyuqlik ichish, dam olish va shifokorga murojaat qilish."}]');
