insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('2b3da347-6e16-d18b-9e48-a646fa0bd924','91b8c9ac-0421-a810-6517-27d3ac56d9c0',0,'4–5-§ takrorlash','4-mavzuda prokariotlar va eukariotlar haqida o''rgandik. To''rt dunyodan qaysi biri prokariotlardan iborat va ularda yadro qanday?','Bakteriyalar; yadrosi shakllanmagan','["Zamburug''lar; yadrosi shakllangan","Hayvonlar; yadrosi yo''q","O''simliklar; yadrosi shakllanmagan"]','Bakteriyalar – prokariot.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('35adf734-eec6-23d7-e673-f40116075923','91b8c9ac-0421-a810-6517-27d3ac56d9c0',1,'4–5-§ takrorlash','O''simlik hujayrasidagi qaysi organoid fotosintez bilan eng bog''liq?','Xloroplast','["Leykoplast","Qisqaruvchi vakuola","Hazm qiluvchi vakuola"]','Xloroplastda xlorofill bor.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('66f7891a-094e-dba6-24d0-e8599735159b','91b8c9ac-0421-a810-6517-27d3ac56d9c0',2,'4–5-§ takrorlash','Zamburug'' hujayrasi qaysi toifaga kiradi va u o''simlik hujayrasidan qaysi tomoni bilan farq qiladi?','Eukariot; fotosintez qilmaydi, geterotrof','["Prokariot; yadrosi yo''q","Eukariot; avtotrof","Prokariot; fotosintez qiladi"]','Zamburug''lar eukariot, ammo geterotrof.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('32b7c98b-e59c-7847-52e3-5d41378c09e4','91b8c9ac-0421-a810-6517-27d3ac56d9c0',3,'4–5-§ takrorlash','Virus hujayra ichiga kirgach nima qiladi?','Hujayra moddalari hisobiga ko''payib, hujayrani nobud qiladi','["Hujayraga xloroplast beradi","Hujayrani kattalashtiradi","Yadrosini kuchaytiradi"]','Virus hujayra oziqi bilan ko''payadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('2a0d12ea-29b4-76d1-81d4-b3ef5a170245','91b8c9ac-0421-a810-6517-27d3ac56d9c0',4,'4–5-§ takrorlash','Nima uchun viruslarni «hujayrasiz» hayot shakli deyiladi, hujayra esa «tiriklikning eng kichik birligi» hisoblanadi?','Virus hujayra darajasidan ham sodda, mustaqil yashay olmaydi','["Virus hujayradan kattaroq","Virus yadrosi aniq shakllangan","Virus fotosintez qiladi"]','Virus hujayrasiz, shuning uchun tirik va jonsiz o''rtasida.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('cd2347a7-97b6-5d6d-c3ef-304e2c658366','91b8c9ac-0421-a810-6517-27d3ac56d9c0',5,'4–5-§ takrorlash','Nerv hujayrasi signal o''tkazadi. Hayvonlarda bu qaysi tirik xususiyatni ta''minlaydi?','Ta''sirlanish','["Fotosintez","Sporalar bilan ko''payish","Passiv harakat"]','Nerv sistemasi tashqi ta''sirga javobni ta''minlaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('ccd2744c-1306-223f-d569-9237c593daef','91b8c9ac-0421-a810-6517-27d3ac56d9c0',6,'4–5-§ takrorlash','Biologiyadagi qaysi fan bakteriya, zamburug'' va viruslarning aksariyatini mikroskopda o''rganadi?','Mikrobiologiya (zamburug''larda mikologiya)','["Botanika","Zoologiya","Anatomiya"]','Mikrob – kichik jonzot.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('cbd05195-64ab-d19a-9d00-c330ed311177','91b8c9ac-0421-a810-6517-27d3ac56d9c0',7,'4–5-§ takrorlash','Flora va fauna – tabiatning ikki qismi. Ularning asosiy farqi qaysi?','Flora avtotrof, fauna geterotrof va harakatchan','["Flora harakatchan","Fauna fotosintez qiladi","Ikkalasi bir xil oziqlanadi"]','O''simliklar avtotrof, hayvonlar geterotrof.');
