insert into public.lesson_bodies(lesson_id, body) values ('9b89222f-6451-1b2c-8cab-946dd76528fc','[{"h":"Ko''rinmas dunyo","ic":"🔬","p":["Qo''limizdagi bir tomchi suvda minglab bakteriya bo''lishi mumkin.","Ular juda kichik, shuning uchun faqat mikroskopda ko''rinadi.","Ularni **mikrobiologiya** o''rganadi."]},{"h":"Bakteriya qanday tuzilgan?","ic":"⚪","p":["Yadrosi yo''q – **prokariot**.","Shakli: **kokk** (shar), **batsilla** (tayoqcha), **vibrion/spirilla** (buralgan).","Tuzilishi sodda, lekin juda chidamli."],"q":"Kokk, batsilla, spirilla – bu nomlar nimani bildiradi?","a":"Bakteriyalarning tashqi shaklini: shar, tayoqcha va buralgan shakl."},{"h":"Bakteriya qanchalik tez ko''payadi?","ic":"⏱️","p":["Qulay sharoitda har **20–30 daqiqada** ikkiga bo''linadi.","Bitta bakteriya bir necha soatda millionlab bo''lishi mumkin.","Shuning uchun sut tez achiydi, jarohat tez yallig''lanadi."],"q":"Nima uchun go''sht muzlatkichda uzoq saqlanadi?","a":"Sovuqda bakteriyalar juda sekin ko''payadi yoki to''xtaydi."},{"h":"Superqahramon: spora","ic":"🛡️","p":["Sharoit yomonlashsa, bakteriya qalin qobiqqa o''raladi – **spora** hosil bo''ladi.","Spora +140 °C dan –253 °C gacha bardosh beradi.","Yillar o''tib, qulay sharoit kelsa – yana hayotga qaytadi."],"q":"Nega konserva idishlari yuqori haroratda sterilizatsiya qilinadi?","a":"Sporalarni ham yo''q qilish uchun, aks holda ular o''sib mahsulotni buzadi."},{"h":"Qatiq – bakteriyalar mahsuli","ic":"🥛","p":["Sutga tomizg''i (achituvchi bakteriyalar) solinadi.","Ular sut shakarini **sut kislotaga** aylantiradi, sut qatiqqa aylanadi.","Tuzlamada ham shunday: sut kislota sabzavotni chirishdan saqlaydi."],"q":"Qatiq uchun sut nega iliq bo''lishi kerak?","a":"Iliq harorat bakteriyalar uchun qulay: sovuqda sekin, juda issiqda o''ladi."},{"h":"Yer yuzining sanitarlari","ic":"🧹","p":["Chirituvchi bakteriyalar o''lik qoldiqlarni parchalaydi.","Agar ular bo''lmasa, yer yuzi o''lik barg va hayvonlar bilan to''lib ketardi.","Ammo ular ba''zan oziq-ovqatni ham buzadi."],"q":"Chirish – foydalimi yoki zararlimi?","a":"Tabiatda foydali (tozalaydi, tuproqni boyitadi), oziq-ovqatda zararli (mahsulotni buzadi)."},{"h":"Tugunak bakteriyalar: ideal hamkorlik","ic":"🤝","p":["Dukkakdoshlar (beda, no''xat) ildizida yashaydi.","Havodagi azotni o''zlashtirib, o''simlikka beradi.","O''simlik esa ularni oziq bilan ta''minlaydi.","Ikkalasiga ham foyda – bu **simbioz**."],"q":"Dehqonlar nega dalaga beda ekadi?","a":"Beda ildizidagi tugunak bakteriyalar tuproqni azotga boyitadi, keyingi ekin yaxshi hosil beradi."},{"h":"Parazit bakteriyalar va kasalliklar","ic":"🤒","p":["Sil, vabo, o''lat, ichburug'', qoqshol.","Epidemiya – kasallikning yoppasiga tarqalishi.","**Karantin:** odamlar to''planishi taqiqlanadi, bemor idish-tovog''i alohida tutiladi.","Eng oddiy himoya: qo''lni sovunlab yuvish."],"q":"Nega ovqatdan oldin qo''lni sovun bilan yuvish kerak?","a":"Qo''ldagi bakteriyalar ovqat bilan og''izga tushib kasallik keltirishi mumkin."},{"h":"Paster tajribasi","ic":"🧫","p":["Ikki kolba, ikkalasida qaynatilgan go''sht sho''rvasi.","Ochiq kolba: sho''rva 3 kunda aynidi.","«S» shaklidagi naychali kolba: aynimadi.","Nay shakli havoni o''tkazadi, lekin bakteriyalarni to''xtatadi."],"q":"Sho''rva nima uchun aynidi? Tajriba nimani isbotladi?","a":"Havodagi bakteriyalar tushgani uchun. Demak, mikroblar go''shtni buzadi."}]');
