insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('89a8a5e5-9f80-2919-1969-c4547ab9705f','db3b6a42-6ef6-ca74-509b-cfb4abfe7b78',1,'6-§. Bakteriyalar dunyosi','Tayoqchasimon bakteriyalar qanday ataladi?','Batsilla','["Kokk","Spirilla","Vibrion"]','Kokk – shar, batsilla – tayoqcha.');
