insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('1fbb1283-d56c-5c69-e9e2-fb5f70c761f6','db3b6a42-6ef6-ca74-509b-cfb4abfe7b78',3,'6-§. Bakteriyalar dunyosi','Bakteriya sporasi nima uchun kerak?','Noqulay sharoitda omon qolish uchun','["Oziq hosil qilish uchun","Harakatlanish uchun","Fotosintez uchun"]','Spora qalin qobiqli chidamli shakl.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('0f33abf5-ef48-d46f-615d-db3f073d2943','db3b6a42-6ef6-ca74-509b-cfb4abfe7b78',4,'6-§. Bakteriyalar dunyosi','Qatiq tayyorlashda sut nimaga aylantiriladi?','Sut shakari (uglevod) sut kislotaga aylanadi','["Sut yog''i oqsilga aylanadi","Sut suvga aylanadi","Sut qand-shakarga aylanadi"]','Tomizg''idagi bakteriyalar uglevodni sut kislotaga aylantiradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b2efb3c1-ef8f-0ea3-edd4-c2e7797354e7','db3b6a42-6ef6-ca74-509b-cfb4abfe7b78',5,'6-§. Bakteriyalar dunyosi','Nima uchun chirituvchi bakteriyalar «yer yuzining sanitarlari» deyiladi?','O''lik qoldiqlarni parchalab, yer yuzini tozalaydi','["Kasallik keltiradi","Havoni kislorodga to''ldiradi","Qatiq tayyorlaydi"]','Ular o''lik organizmlarni chiritadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9b4dde2d-0fc6-6d4b-5270-d9748c3deef7','db3b6a42-6ef6-ca74-509b-cfb4abfe7b78',6,'6-§. Bakteriyalar dunyosi','Tugunak bakteriyalar qaysi o''simliklar ildizida yashaydi?','Dukkakdoshlar','["Boshoqdoshlar","Karamdoshlar","Ro''yxatdagi barcha o''simlik"]','Beda, no''xat kabi dukkakdoshlar ildizida.');
