insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('2a8484b0-a0c0-f540-6473-da41da9afd8a','db3b6a42-6ef6-ca74-509b-cfb4abfe7b78',9,'6-§. Bakteriyalar dunyosi','Paster tajribasida «S» shaklidagi nayli kolbada qaynatma nega aynimadi?','Bakteriyalar nayning egilgan qismida ushlanib qoldi','["U kolbada bakteriyalar yo''q edi","Go''sht yangi edi","Nay havoni o''tkazmadi"]','Havo kirdi, ammo bakteriyalar nayda to''xtadi.');
