insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('c314bf14-f775-0e2d-6013-cdaed5504de3','ad1f358e-b4db-d101-df07-ad0408942a22',0,'5–6-§ takrorlash','5-mavzuda bakteriyalarni prokariot deb o''rgandik. Bakteriyaning sporasi va zamburug''ning sporasi o''xshashmi?','Ikkalasi ham noqulay sharoitda yoki ko''payish uchun xizmat qiladi','["Ikkalasi faqat quruqlikda bo''ladi","Faqat bakteriyada bo''ladi","Ikkalasi fotosintez qiladi"]','Ikkalasi tarqalish yoki saqlanish uchun.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('567efead-1bd8-91e5-b719-4f3b912f7433','ad1f358e-b4db-d101-df07-ad0408942a22',1,'5–6-§ takrorlash','Bakteriya hujayrasida yadro yo''q. Bu nimani anglatadi va qaysi dunyoga kiradi?','Prokariot, bakteriyalar dunyosi','["Eukariot, zamburug''lar dunyosi","Prokariot, o''simliklar dunyosi","Eukariot, hayvonot dunyosi"]','Yadrosiz hujayra – prokariot.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('7a5da4e5-8810-5a48-958c-f7a3cf597710','ad1f358e-b4db-d101-df07-ad0408942a22',2,'5–6-§ takrorlash','Hayvonlar hujayrasi eukariot. Bakteriyalardan farqli, ular hujayrasida nima bor?','Aniq shakllangan yadro','["Spora","Koloniya","Tomizg''i"]','Eukariotlarda yadro bor.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('5999f061-5be3-e1ab-5fb1-b20c03d39ca9','ad1f358e-b4db-d101-df07-ad0408942a22',3,'5–6-§ takrorlash','Virus va parazit bakteriya – ikkalasi ham kasallik keltiradi. Ularning asosiy farqi nimada?','Virus hujayrasiz, bakteriya hujayrali','["Virus yadroli","Bakteriya hujayrasiz","Farqi yo''q"]','Virus hujayrasiz shakl, bakteriya prokariot hujayra.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('33307730-dcd3-1ff4-0dfa-d382f16de8fb','ad1f358e-b4db-d101-df07-ad0408942a22',4,'5–6-§ takrorlash','Mikroskopda bakteriya shaklini ko''rish uchun avval Petri idishida ko''paytiriladi. Bu qaysi o''rganish usuliga yaqin?','Tajriba','["Tarixiy usul","Faqat kuzatish","Taqqoslash"]','Sharoit yaratib, organizm o''stiriladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('3881e8ce-b225-e75d-7232-2a62dd042f59','ad1f358e-b4db-d101-df07-ad0408942a22',5,'5–6-§ takrorlash','Fotosintez qiluvchi o''simlik va azot to''plovchi bakteriya hamkorligida nima o''xshash?','Ikkalasi ham bir-biridan foyda oladi','["Ikkalasi parazit","Ikkalasi geterotrof","Ikkalasi sporasiz"]','Simbiozda ikki tomonga foyda.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b2e78b45-985c-d7f6-655e-9ca8da5b00f8','ad1f358e-b4db-d101-df07-ad0408942a22',6,'5–6-§ takrorlash','Moddalar almashinuvi (2-mavzu) bakteriyalarda qanday namoyon bo''ladi? Ularning qaysi turi o''lik qoldiqni parchalab oziqlanadi?','Chirituvchi bakteriyalar','["Tugunak bakteriyalar","Fitonsid hosil qiluvchilar","Kokklar"]','Ular tayyor organik qoldiq bilan oziqlanadi, ya''ni geterotrof.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('5f76436b-f936-ba3c-bd16-7f3aee511814','ad1f358e-b4db-d101-df07-ad0408942a22',7,'5–6-§ takrorlash','Karantin nima uchun e''lon qilinadi?','Epidemiya tarqalishining oldini olish uchun','["Bakteriyalarni ko''paytirish uchun","Sporalarni tarqatish uchun","Oziq-ovqatni buzish uchun"]','Odamlar to''planishi cheklanadi.');
