insert into public.lesson_bodies(lesson_id, body) values ('a147336f-48d9-a387-9630-6e205bd4a57b','[{"h":"Zamburug'' – alohida dunyo","ic":"🍄","p":["Eukariot. Geterotrof. Erkin harakat qilmaydi.","Mikologiya fani o''rganadi.","Ilgari o''simlik deb o''ylashgan, hozir alohida olam."],"q":"Zamburug'' hayvonga ham, o''simlikka ham o''xshaydi. Qaysi jihatdan qaysiga?","a":"Harakat qilmasligi bilan o''simlikka, tayyor oziq bilan oziqlanishi bilan hayvonga o''xshaydi."},{"h":"Yashash uchun nima kerak?","ic":"💧","p":["Ozuqa, iliq harorat, nam.","Yorug''lik shart emas.","Shuning uchun qorong''i va nam joylarda (podval, o''rmon tagi) zamburug'' ko''p."],"q":"Nega yomg''irdan keyin o''rmonda qo''ziqorin ko''payadi?","a":"Nam va iliq muhit zamburug'' uchun eng qulay."},{"h":"Achitqi: non yumshoqligining siri","ic":"🍞","p":["Achitqi – ovalsimon bir hujayrali zamburug''.","Shakarli iliq suvda tez kurtaklanib ko''payadi.","Xamir shishib, g''ovak bo''ladi."],"q":"Xamir nega ko''tarilib oshadi?","a":"Achitqi zamburug''lari ko''payib, gaz ajratadi va xamirni shishiradi."},{"h":"Mog''or: nonga qo''nuvchi mehmon","ic":"🟢","p":["Mog''or sporalari doim havoda uchib yuradi.","Selofan paket – nam va iliq muhit, mog''or rivojlanadi.","Toksinlari zaharlashi mumkin.","Lekin ba''zi mog''orlardan **antibiotik** olinadi."],"q":"Mog''orlagan nonning mog''or qismini kesib, qolganini yeyish to''g''rimi?","a":"Yo''q, zaharli moddalar butun nonga o''tgan bo''lishi mumkin. Mog''orlagan oziqni yemagan ma''qul."},{"h":"Qalpoqchali zamburug''lar","ic":"🍄","p":["Oyoqcha + qalpoqcha.","Yeyiladigan: shampinion, oq qo''ziqorin.","Zaharli: qizil muxomor, sariq soxta qo''ziqorin.","Yeyishdan oldin 5–7 daqiqa qaynatib suvini to''king."],"q":"Tanimagan qo''ziqorinni nima qilish kerak?","a":"Uzmaslik va yemaslik. Faqat yaxshi taniydigan mutaxassisning fikri bilan yeyiladi."},{"h":"Parazit zamburug''lar","ic":"🌾","p":["**Qorakuya** – boshoqda qora kukun, don puch bo''ladi.","**Vilt** – o''tkazuvchi qismni tutib, o''simlik so''liydi.","**Zang** – atirgul bargida zangga o''xshash dog''lar."],"q":"Dehqon nima uchun kasallikni erta payqashi kerak?","a":"Parazit zamburug'' tez tarqalib butun ekinni nobud qiladi."},{"h":"Foyda va zarar","ic":"⚖️","p":["**Foyda:** non, antibiotik, yeyiladigan qo''ziqorin.","**Zarar:** oziq-ovqatni buzadi, o''simlik kasalliklari, zaharli turlar.","Hammasini bilish – insonni himoya qiladi."],"q":"Bitta zamburug'' turi (masalan, mog''or) ham foydali, ham zararli bo''la oladimi?","a":"Ha: oziqni buzadi, ammo ayrim turlaridan antibiotik olinadi."}]');
