insert into public.lesson_bodies(lesson_id, body) values ('3d98dafd-a1c4-2cdf-7ad8-bb3cdcf3ae25','[["tf","Mikologiya","Zamburug''lar haqidagi fan",true],["tf","Achitqi zamburug''i","Ko''p hujayrali, yirik qalpoqchali zamburug''",false],["tf","Mog''or zamburug''i","Oziq-ovqatni buzishi mumkin, ayrimlaridan antibiotik olinadi",true],["tf","Qizil muxomor","Yeyiladigan zamburug''",false],["tf","Shampinion (qo''zidumba)","Yeyiladigan qalpoqchali zamburug''",true],["tf","Qorakuya","Boshoqdoshlarda parazitlik qiluvchi zamburug'' kasallik",true],["tf","Zamburug''lar","Yashashi uchun yorug''lik shart",false],["type","Non yopishda ishlatiladigan bir hujayrali zamburug''","achitqi",["achitqi"]],["type","Zamburug'' tanasidagi ingichka ipchalar","gifa",["gifa","gifalar"]],["type","Bakteriyalarga qarshi dori (mog''ordan olinadi)","antibiotik",["antibiotik"]],["type","O''simlik so''lishiga sabab bo''luvchi kasallik nomi (Vertitsillium)","vilt",["vilt"]],["type","Zamburug''lar qaysi hujayrali turga kiradi? (prokariot yoki ...)","eukariot",["eukariot","eukariotlar"]]]');
