insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('46b9992f-014a-073c-f975-c6d6d984c694','7045b2eb-e818-b05c-719d-19092233ff0d',1,'7-§. Zamburug''lar dunyosi','Zamburug''lar qaysi belgisi bilan hayvonlarga o''xshaydi?','Geterotrof oziqlanishi','["Fotosintez qilishi","Faol harakatlanishi","Nerv sistemasi borligi"]','Zamburug''lar tayyor organik moddalar bilan oziqlanadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('476c354c-2fb5-7cfc-b0ff-cbbbaf88ddec','7045b2eb-e818-b05c-719d-19092233ff0d',2,'7-§. Zamburug''lar dunyosi','Achitqi zamburug''idan qanday maqsadda foydalaniladi?','Non va xamir mahsulotlarini yumshoq qilish uchun','["Dori tayyorlash uchun","Teri oshlash uchun","Tuproqni azotga boyitish uchun"]','Achitqi xamirni ko''taradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('7f1ca5b3-c03f-e99f-552b-8ad8f5976e1b','7045b2eb-e818-b05c-719d-19092233ff0d',3,'7-§. Zamburug''lar dunyosi','Nima uchun nonni selofan paketda uzoq saqlasa mog''orlaydi?','Paket ichida nam va qulay muhit hosil bo''ladi','["Selofan mog''or hosil qiladi","Non o''zi mog''orga aylanadi","Paket havoni butunlay o''tkazadi"]','Mog''or sporalari doim havoda bor.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('02e1a95e-aa4a-5c05-dda2-1ed46cd5ec9a','7045b2eb-e818-b05c-719d-19092233ff0d',4,'7-§. Zamburug''lar dunyosi','Mog''or zamburug''idan nima olinadi?','Antibiotik','["Vitamin","Qatiq","Un"]','Antibiotik bakteriyalarga qarshi dori.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('d0922781-669f-cd78-c8e7-84f9877b64ca','7045b2eb-e818-b05c-719d-19092233ff0d',5,'7-§. Zamburug''lar dunyosi','Quyidagilardan qaysi biri zaharli zamburug''?','Qizil muxomor','["Qo''zidumba","Oq qo''ziqorin","Shampinion"]','Qizil muxomor va sariq soxta qo''ziqorin zaharli.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('3c0397d4-0d46-a4fa-89c5-c1546936337f','7045b2eb-e818-b05c-719d-19092233ff0d',6,'7-§. Zamburug''lar dunyosi','Yeyiladigan qo''ziqorinni taomdan oldin nima qilish kerak?','5–7 daqiqa qaynatib, suvini to''kish','["Xom holda yeyish","Quritmasdan yeyish","Sovuq suvda ivitish"]','Zaharli moddalar qaynatilganda suvga chiqib ketadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e0c7abfe-16f0-2d9c-d8fb-bfc3e56a2f9e','7045b2eb-e818-b05c-719d-19092233ff0d',7,'7-§. Zamburug''lar dunyosi','Qorakuya zamburug''i qayerda parazitlik qiladi?','Boshoqdoshlarning boshog''ida','["Ildizida","Gulida","Mevasida"]','Qora kukun hosil qilib, donni puch qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a76a58c6-17eb-b9dd-d39f-1c22533d2099','7045b2eb-e818-b05c-719d-19092233ff0d',8,'7-§. Zamburug''lar dunyosi','Vilt kasalligini qaysi zamburug'' keltiradi?','Vertitsillium','["Qorakuya","Achitqi","Mog''or"]','O''tkazuvchi qismida parazitlik qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('dd567f5f-a8a5-89aa-46c5-098e99e70dd0','7045b2eb-e818-b05c-719d-19092233ff0d',9,'7-§. Zamburug''lar dunyosi','Zamburug'' yashashi uchun quyidagilardan qaysi biri shart emas?','Yorug''lik','["Ozuqa","Namlik","Harorat"]','Zamburug''lar fotosintez qilmaydi.');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('12205943-b847-dbec-1ee0-8538f481881f','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','8aa06f63-15aa-0d16-5e99-42ce2bc26cf6','{"uz":"Mavzu testi: Zamburug''lar dunyosi","ru":"Mavzu testi: Zamburug''lar dunyosi","en":"Mavzu testi: Zamburug''lar dunyosi"}','test','7045b2eb-e818-b05c-719d-19092233ff0d','',25,33);
insert into public.items(id, folder_id, kind, title, visible, source, created_by) values ('255ae582-cd70-3817-beac-e095b383619c', null, 'test', '{"uz":"6-§ + 7-§ takrorlash testi","ru":"6-§ + 7-§ takrorlash testi","en":"6-§ + 7-§ takrorlash testi"}', false, null, (select author_id from public.courses where id='70bcc0ad-19f0-0387-8586-5bdf7bf4f43e'));
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4f4c4df6-2f0d-de71-d467-3acffb3ff332','255ae582-cd70-3817-beac-e095b383619c',0,'6–7-§ takrorlash','6-mavzuda bakteriyalar prokariot ekanini bildik. 7-mavzuda zamburug''lar eukariot. Ularni birlashtiruvchi umumiy belgi nima?','Ko''pchiligi geterotrof oziqlanadi','["Ikkalasida yadro aniq shakllangan","Ikkalasi fotosintez qiladi","Ikkalasi hayvonot dunyosiga kiradi"]','Bakteriyalar asosan geterotrof, zamburug''lar ham geterotrof.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('72e0d671-44a5-d4e9-ca3c-6c307bee3f2f','255ae582-cd70-3817-beac-e095b383619c',1,'6–7-§ takrorlash','Achitqi bir hujayrali eukariot, bakteriya bir hujayrali prokariot. Ularni mikroskopda ajratishga nima yordam beradi?','Achitqida aniq yadro bor, bakteriyada yo''q','["Bakteriyada xloroplast bor","Achitqida qalin spora bor","Ikkalasida bir xil tuzilish"]','Yadro borligi eukariotni ko''rsatadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('492681d2-3673-16d6-03be-16001f129c3c','255ae582-cd70-3817-beac-e095b383619c',2,'6–7-§ takrorlash','Bakteriyalar ham, zamburug''lar ham sporalar hosil qiladi. Sporaning umumiy vazifasi nima?','Omon qolish va tarqalish','["Fotosintez","Nafas olish","Ayirish"]','Spora – tarqalish va omon qolish shakli.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('8bca35b5-2b81-1e8c-a73a-a71c78ddee47','255ae582-cd70-3817-beac-e095b383619c',3,'6–7-§ takrorlash','Mog''or zamburug''idan antibiotik olinadi. Antibiotik qaysi tirik guruhga qarshi ishlatiladi?','Bakteriyalarga','["O''simliklarga","Hayvonlarga","Zamburug''larga"]','Antibiotik bakteriyalarga qarshi dori.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('2590d9a1-627f-1317-7d09-5d4d1570008a','255ae582-cd70-3817-beac-e095b383619c',4,'6–7-§ takrorlash','Qatiq (6-mavzu) va xamir (7-mavzu): ikkalasi ham qaysi hodisaga misol bo''ladi?','Mikroorganizmlar yordamida mahsulot tayyorlash','["Fotosintez","Parazitlik","Simbioz"]','Qatiqda bakteriya, xamirda achitqi zamburug''i ishlaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b4b1caac-a30f-9172-5bb3-8f387290deb9','255ae582-cd70-3817-beac-e095b383619c',5,'6–7-§ takrorlash','Parazit bakteriya (sil) va parazit zamburug'' (qorakuya)ning farqi nima?','Biri odamda, ikkinchisi o''simlikda kasallik qiladi','["Ikkalasi faqat odamda","Ikkalasi faqat o''simlikda","Ikkalasi hujayrasiz"]','Sil – bakteriya, qorakuya – o''simlik kasalligi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9f1dc990-6a70-dedc-fcc7-a35bbd438c88','255ae582-cd70-3817-beac-e095b383619c',6,'6–7-§ takrorlash','Ikki hamkorlik misoli: tugunak bakteriya – dukkakdosh (simbioz). Parazit zamburug'' – boshoqdosh munosabati nima?','Parazitlik (zarar yetkazadi)','["Simbioz","Ikkalasiga foyda","Raqobat"]','Parazit xo''jayin hisobiga yashaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('86123757-0f1c-120f-2340-66ba978ec854','255ae582-cd70-3817-beac-e095b383619c',7,'6–7-§ takrorlash','Zamburug'' va bakteriya: qaysi biri chirituvchi bo''lib, o''lik qoldiqlarni parchalab tabiatni tozalashda ishtirok etadi?','Ikkalasi ham (chirituvchi bakteriya va ba''zi zamburug''lar)','["Faqat tugunak bakteriya","Faqat parazit zamburug''","Hech biri"]','Ularning ko''pi o''lik qoldiq bilan oziqlanadi.');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('c8bc449c-5b28-4987-ed63-71284d30c28f','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','8aa06f63-15aa-0d16-5e99-42ce2bc26cf6','{"uz":"Takrorlash testi: 6-§ va 7-§","ru":"Takrorlash testi: 6-§ va 7-§","en":"Takrorlash testi: 6-§ va 7-§"}','test','255ae582-cd70-3817-beac-e095b383619c','',25,34);
