insert into public.lesson_bodies(lesson_id, body) values ('f8033d7f-78d0-29cc-3f60-4096e25b50e6','[{"h":"O''simlik – tirik fabrika","ic":"🌳","p":["O''simlik joyida turadi, lekin ichida katta ish ketadi.","Quyosh nuri + karbonat angidrid + suv → **glyukoza** + **kislorod**.","Bu fotosintez. Shu bilan o''simlik o''zini ham, boshqalarni ham boqadi."],"q":"O''simlik ham nafas oladimi?","a":"Ha, doim. Kislorod yutib, karbonat angidrid chiqaradi. Fotosintez esa alohida jarayon: yorug''likda boradi."},{"h":"Ikki guruh organ","ic":"🌸","p":["**Vegetativ** (ovqat va o''sish): ildiz, poya, barg.","**Generativ** (ko''payish): gul, meva, urug''.","Vegetativ – «yashash uchun», generativ – «avlod uchun»."],"q":"Kartoshka tuguni qaysi guruhga yaqin deb o''ylaysiz?","a":"Bu o''zgargan poya, shuning uchun vegetativ organ (u ham ko''paytirishga xizmat qiladi, bu esa vegetativ ko''payish)."},{"h":"O''simliklar nima uchun kerak?","ic":"🌍","p":["Kislorod beradi.","Organik modda yaratadi – **produtsent**.","Ozuqa zanjirining boshlanishi.","Suv bug''latib havoni namlaydi."],"q":"Hayvonlar o''simliklarsiz yashay olarmidi?","a":"Yo''q: oziq ham, kislorod ham o''simliklardan."},{"h":"Odamga qanday foyda?","ic":"🍎","p":["Oziq: olma, o''rik, yong''oq.","Dori: yalpiz, na''matak, shirinmiya.","Yem: beda, sebarga, shuvoq.","Xomashyo: yog''och, paxta, kanop. Manzara: fikus, kaktus."],"q":"Bu ro''yxatda siz ishlatadigan qaysi o''simliklar bor?","a":"Har kim har xil javob beradi. Muhimi, o''simlik har kunimizda ishtirok etishini sezish."},{"h":"Qanday «qutilarga» solamiz?","ic":"🗃️","p":["Tur → turkum → oila → sinf → bo''lim → dunyo.","Eng kichik «quti» – tur. Eng katta – dunyo.","Bu tartibni Linney yaratgan."],"q":"Nega olimlar o''simliklarni guruhlaydi?","a":"500 mingdan ortiq tur bor. Guruhlamasak, tartib ham, o''rganish ham bo''lmaydi."},{"h":"Makkajo''xori «pasporti»","ic":"🌽","p":["Dunyo: O''simlik.","Bo''lim: Yopiq urug''lilar.","Sinf: Bir urug''pallalilar.","Oila: Bug''doydoshlar.","Turkum: Jo''xori. Tur: Makkajo''xori."],"q":"Bug''doy va makkajo''xori qaysi oilada birga?","a":"Bug''doydoshlar oilasida."},{"h":"Tuban va yuksak","ic":"🪜","p":["**Tuban** – tanasi bo''linmagan (tallom): suvo''tlar.","**Yuksak** – ildiz, poya, barg bor.","Yuksaklar: sporali (yo''sin, qirqbo''g''im, qirqquloq) va urug''li (ochiq, yopiq urug''lilar)."]},{"h":"Pristli tajribasi","ic":"🐭","p":["1771-yil. Ikki shisha idish, ikkalasida sichqon.","Biriga o''simlik ham qo''yildi.","O''simliksiz idishda sichqon halok bo''ldi, o''simlikli idishda tirik qoldi."],"q":"Tajribadan nima xulosa qilasiz? Idish yorug'' joyda turishi nima uchun kerak?","a":"O''simlik kislorod chiqaradi. Fotosintez uchun yorug''lik kerak, qorong''ida u yetarli ishlamaydi."}]');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('1fe707a6-6a60-8bf6-3b3e-fc682c4b1f5b','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','30220469-c32a-509a-6679-419a42cc5bc8','{"uz":"Kartochkalar: O''simliklar dunyosi","ru":"Kartochkalar: O''simliklar dunyosi","en":"Kartochkalar: O''simliklar dunyosi"}','cards',null,'',15,37);
insert into public.lesson_bodies(lesson_id, body) values ('1fe707a6-6a60-8bf6-3b3e-fc682c4b1f5b','[["tf","Vegetativ organlar","Ildiz, poya va barg",true],["tf","Generativ organlar","Ildiz, poya va barg",false],["tf","Produtsent","Organik modda hosil qiluvchi organizm",true],["tf","Linney","O''simliklar sistematikasiga asos solgan shved olimi",true],["tf","Eng kichik sistematik birlik","Bo''lim",false],["tf","Tallom","Ildiz, poya va bargga bo''lingan tana",false],["tf","Makkajo''xori","Bug''doydoshlar oilasiga kiradi",true],["tf","Pristli tajribasi","O''simlik kislorod chiqarishini ko''rsatdi",true],["type","O''simlikda fotosintez natijasida hosil bo''ladigan shakar","glyukoza",["glyukoza"]],["type","Gul, meva va urug'' qaysi organlar? (generativ yoki ...)","generativ",["generativ"]],["type","Tur, turkum, oila, sinf, ... , dunyo. Qoldirilgan birlik?","bo''lim",["bo''lim","bolim"]],["type","Tuban o''simliklar tanasining nomi","tallom",["tallom","qattana"]]]');
