insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('94df16ec-cf8c-3ec4-4539-a45033735aaa','2cce0609-b3dd-c3f9-41b1-8e3af47dad4e',0,'8-§. O''simliklar dunyosi','O''simliklar fotosintezda nimani yutib, nimani ajratadi?','Karbonat angidridni yutib, kislorod ajratadi','["Kislorodni yutib, karbonat angidrid ajratadi","Azotni yutib, vodorod ajratadi","Glyukozani yutib, suv ajratadi"]','Fotosintezda o''simlik karbonat angidridni yutadi va kislorod chiqaradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('6a4c94ef-55c3-423c-208f-eb73cb6b3f92','2cce0609-b3dd-c3f9-41b1-8e3af47dad4e',1,'8-§. O''simliklar dunyosi','O''simlikning vegetativ organlari qaysilar?','Ildiz, poya, barg','["Gul, meva, urug''","Faqat gul","Meva va urug''"]','Vegetativ organlar oziqlanish va o''sishni ta''minlaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('54769fcb-e469-56b6-d027-beec60ad08a6','2cce0609-b3dd-c3f9-41b1-8e3af47dad4e',2,'8-§. O''simliklar dunyosi','Generativ organlarning vazifasi nima?','Ko''payish va tarqalish','["Suv tashish","Fotosintez","Oziq to''plash"]','Gul, meva va urug'' ko''payishga xizmat qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('aba471e6-e49b-9987-b7b2-69359cb79858','2cce0609-b3dd-c3f9-41b1-8e3af47dad4e',3,'8-§. O''simliklar dunyosi','Produtsent nima?','Organik modda hosil qiluvchi organizm','["Faqat hayvon","Chiritib tozalovchi bakteriya","Yirtqich hayvon"]','O''simliklar organik moddani sintez qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('75686f80-16a3-e074-b2d3-e82387ad5baa','2cce0609-b3dd-c3f9-41b1-8e3af47dad4e',4,'8-§. O''simliklar dunyosi','Quyidagilardan qaysi biri o''simlikning inson uchun ahamiyatiga kirmaydi?','Hamma o''simlik zaharsiz va yeyiladi','["Dori sifatida","Yem-xashak sifatida","Xomashyo sifatida"]','Ba''zi o''simliklar zaharli bo''ladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('cc18f7c3-f493-f725-7354-c69069989e60','2cce0609-b3dd-c3f9-41b1-8e3af47dad4e',5,'8-§. O''simliklar dunyosi','Sistematik birliklar to''g''ri tartibda (kichikdan kattaga) qaysi qatorda?','Tur – turkum – oila – sinf – bo''lim – dunyo','["Dunyo – bo''lim – sinf – oila – turkum – tur","Tur – oila – turkum – bo''lim – sinf – dunyo","Oila – tur – turkum – dunyo – sinf – bo''lim"]','Eng kichik birlik – tur.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9f128db7-3383-fe17-59ed-7cb4203c27fa','2cce0609-b3dd-c3f9-41b1-8e3af47dad4e',6,'8-§. O''simliklar dunyosi','Sistematikaga asos solgan olim kim?','Karl Linney','["Jozeff Pristli","Abu Rayhon Beruniy","Franchesko Redi"]','Karl Linney – shved olimi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a963ad14-9d8e-bcab-f808-8ba42f8a03a6','2cce0609-b3dd-c3f9-41b1-8e3af47dad4e',7,'8-§. O''simliklar dunyosi','Makkajo''xori qaysi oilaga kiradi?','Bug''doydoshlar','["Qoqio''tdoshlar","Ra''nodoshlar","Dukkakdoshlar"]','Makkajo''xori – jo''xori turkumining vakili.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('dc529e89-8314-48a5-e15c-8fbb590cbb79','2cce0609-b3dd-c3f9-41b1-8e3af47dad4e',8,'8-§. O''simliklar dunyosi','Tuban o''simliklarga qaysi bo''lim kiradi?','Suvo''tlar','["Yo''sinlar","Qirqquloqlar","Yopiq urug''lilar"]','Tuban o''simliklar tanasi bo''linmagan (tallom).');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('ec60d6ca-6197-5ff0-c0f7-28c7a24163e3','2cce0609-b3dd-c3f9-41b1-8e3af47dad4e',9,'8-§. O''simliklar dunyosi','Pristli tajribasidan nima xulosa kelib chiqadi?','O''simlik havoni kislorod bilan boyitadi','["Sichqon o''simlik yeydi","O''simlik karbonat angidrid ajratadi","Idish havo o''tkazmaydi, shuning uchun sichqon o''ldi"]','O''simlik joylashgan idishda sichqon tirik qoldi.');
