insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('0e50b234-0194-caee-defc-507d0189388a','91191d24-bd09-3ca1-5e05-f52e234521ed',0,'7–8-§ takrorlash','Zamburug'' ham, o''simlik ham eukariot. O''simlikni zamburug''dan oziqlanish usuliga ko''ra qanday ajratamiz?','O''simlik avtotrof, zamburug'' geterotrof','["Ikkalasi avtotrof","O''simlik geterotrof","Farqi yo''q"]','O''simlik fotosintez qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('cc3c4b9a-bdb1-8521-8614-f1ff0a73a07b','91191d24-bd09-3ca1-5e05-f52e234521ed',1,'7–8-§ takrorlash','Achitqi zamburug''i va makkajo''xori. Qaysi biri produtsent?','Makkajo''xori','["Achitqi","Ikkalasi","Hech biri"]','Produtsent – organik modda hosil qiluvchi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b605bea1-eb71-d5f3-afad-5f096185d476','91191d24-bd09-3ca1-5e05-f52e234521ed',2,'7–8-§ takrorlash','7-mavzuda zamburug''lar gifalar bilan tuproqqa birikishini bildik. O''simlik tuproqqa nima bilan birikadi?','Ildiz','["Gifa","Qubba","Spora"]','Ildiz – vegetativ organ.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('0742b9da-d198-38c7-18a4-83847fb96b3a','91191d24-bd09-3ca1-5e05-f52e234521ed',3,'7–8-§ takrorlash','Mog''or zamburug''i nonga qanday tarqaladi, o''simlik esa ko''payish uchun qaysi organlardan foydalanadi?','Sporalar bilan; gul, meva, urug''','["Gifalar bilan; ildiz","Fotosintez bilan; barg","Kurtak bilan; faqat poya"]','Zamburug''da spora, urug''li o''simlikda generativ organ.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('5b7e1d9f-cc5b-04aa-f8b6-568a00c900d3','91191d24-bd09-3ca1-5e05-f52e234521ed',4,'7–8-§ takrorlash','Qaysi tirik guruh sistematikasini ham tur, oila, bo''lim kabi birliklar bilan ifodalash mumkin?','Hamma tirik guruhlar (o''simlik, hayvon, zamburug'')','["Faqat o''simlik","Faqat hayvon","Faqat bakteriya"]','Sistematika barcha organizmlarni guruhlaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a56c0e1f-f5d4-64e1-dc92-e4519866b9e7','91191d24-bd09-3ca1-5e05-f52e234521ed',5,'7–8-§ takrorlash','O''simliklar kislorod chiqarishi sabab bo''ladi: qaysi tirik guruh uni ko''proq iste''mol qiladi?','Hayvonlar, odam va boshqa aerob organizmlar','["Faqat zamburug''","Faqat virus","Hech kim"]','Kislorod bilan nafas oluvchilarning hammasi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('37f78950-e094-1209-2ab8-4ea904647989','91191d24-bd09-3ca1-5e05-f52e234521ed',6,'7–8-§ takrorlash','Qorakuya zamburug''i makkajo''xori yoki bug''doy kabi o''simliklarga zarar yetkazadi. Bu o''simliklar qaysi oilaga kiradi?','Bug''doydoshlar','["Qoqio''tdoshlar","Ra''nodoshlar","Dukkakdoshlar"]','Boshoqdosh = bug''doydoshlar.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('2c4cf330-f608-024b-ffc5-a0a371b52b9c','91191d24-bd09-3ca1-5e05-f52e234521ed',7,'7–8-§ takrorlash','Hayotning hujayrasiz shakli bo''lgan virus o''simlikka ham ta''sir qilishi mumkin. Misol keltiring.','Tamaki mozaikasi virusi','["Bakteriofag","Quturish virusi","Gripp virusi"]','Tamaki mozaikasi – o''simlik virusi.');
