insert into public.lesson_bodies(lesson_id, body) values ('6cf700d2-0762-5264-6668-9984678434dc','[{"h":"Suvdagi yashil dunyo","ic":"🌊","p":["Suvo''tlar – eng sodda o''simliklar.","Tanasi ildiz, poya, bargga bo''linmagan: **tallom**.","Ularning hammasida pigmentli **xromatofor** bor."],"q":"Nima uchun suvo''tlarni «tuban» o''simlik deyishadi?","a":"Tanasi oddiy – organlarga bo''linmagan."},{"h":"Uch rang – uch guruh","ic":"🎨","p":["Pigment turiga ko''ra: **yashil**, **qizil**, **qo''ng''ir**.","Chuqur dengizda yorug''lik kam, u yerda qizil suvo''tlar ko''proq."]},{"h":"Xlorella – mayda «yashil sharcha»","ic":"🟢","p":["Bir hujayrali, sharsimon.","Xromatoforida xlorofill – fotosintez qiladi.","Suvni kislorodga boyitadi, oqsilga boy, chorvaga oziq."],"q":"Xlorella akvariumga foydasi bormi?","a":"Ha, suvni kislorodga boyitadi, baliqlar uchun yaxshi."},{"h":"Xlamidomonada – suzuvchi quyosh izlovchi","ic":"✨","p":["Qizil ko''zchasi yorug''likni sezadi.","Xivchinlari bilan suzib, yorug''likka intiladi.","Ifloslangan suvni tozalaydi."],"q":"O''simlik bo''lsa ham, nima uchun u harakat qiladi?","a":"Yaxshi yoritilgan joyda fotosintez yaxshiroq ketadi, shuning uchun yorug''likka intiladi."},{"h":"Ulotriks – yashil ip","ic":"🧵","p":["Ko''p hujayrali ipsimon suvo''t.","Rizoidi bilan suv tubiga yopishadi.","Zoosporalar bilan jinssiz, izogametalar bilan jinsiy ko''payadi."],"q":"Zoospora nega xivchinli?","a":"Suzib, ona o''simlikdan uzoqroqqa borib o''rnashish uchun."},{"h":"Spirogira – baqa to''ni","ic":"🐸","p":["Chuchuk suvda yashil shilimshiq «ko''rpacha» hosil qiladi.","Xromatofori spiralsimon buralgan.","Bo''laklarga bo''linib ko''payadi."]},{"h":"Dengiz sabzavotlari","ic":"🥬","p":["**Porfira** (qizil) – «dengiz salati».","**Laminariya** (qo''ng''ir) – «dengiz karami», yodga boy.","Yod buqoqdan saqlaydi (1-mavzuni eslang)."],"q":"Dengiz karami nega foydali?","a":"Tarkibida yod ko''p, yod esa qalqonsimon bez uchun kerak."},{"h":"Suvo''tlarning ahamiyati","ic":"♻️","p":["Suvni kislorodga boyitadi.","Suv jonivorlari uchun oziq.","Yod va brom manbai.","Xlorella va xlamidomonada ifloslangan suvni tozalaydi."]}]');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('8e325d0d-c16a-8d9d-1c1c-fe63d63188de','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','75645918-abc9-3dc4-4bb3-0a7dfa2070ca','{"uz":"Kartochkalar: Tuban o''simliklar","ru":"Kartochkalar: Tuban o''simliklar","en":"Kartochkalar: Tuban o''simliklar"}','cards',null,'',15,42);
insert into public.lesson_bodies(lesson_id, body) values ('8e325d0d-c16a-8d9d-1c1c-fe63d63188de','[["tf","Tallom","Ildiz, poya, bargga bo''linmagan tana",true],["tf","Xromatofor","Suvo''tlardagi pigment saqlovchi qism",true],["tf","Xlorella","Ko''p hujayrali qo''ng''ir suvo''t",false],["tf","Xlamidomonada","Qizil ko''zchasi yorug''likni sezuvchi bir hujayrali suvo''t",true],["tf","Laminariya","Yod ko''p, qo''ng''ir suvo''t (dengiz karami)",true],["tf","Porfira","Chuchuk suvdagi yashil ipsimon suvo''t",false],["tf","Spirogira","Spiralsimon xromatoforli yashil suvo''t",true],["tf","Zoospora","Xivchinli, suzuvchi spora",true],["type","Pigment saqlovchi suvo''t qismi","xromatofor",["xromatofor"]],["type","Ulotriksning ildizga o''xshash o''simtasi","rizoid",["rizoid"]],["type","Porfira ikkinchi nomi: dengiz ... (bir so''z)","salati",["salati"]],["type","Laminariya tarkibida ko''p bo''ladigan modda","yod",["yod"]]]');
