insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('d138f50a-fb19-788a-20a7-e421cb2265ee','a42a242d-10f8-41cf-3b28-5ae637aea753',1,'9-§. Tuban o''simliklar','Pigment turiga ko''ra suvo''tlar qanday guruhlarga bo''linadi?','Qizil, yashil va qo''ng''ir','["Yirik va mayda","Sho''r va chuchuk","Ipsimon va sharsimon"]','Xromatoforda joylashgan pigmentga qarab.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('12f8c755-99a0-72cd-10fc-6e99c7a400d3','a42a242d-10f8-41cf-3b28-5ae637aea753',2,'9-§. Tuban o''simliklar','Bir hujayrali suvo''tga qaysi misol to''g''ri?','Xlorella','["Spirogira","Laminariya","Porfira"]','Xlorella va xlamidomonada bir hujayrali.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a25e9ede-f449-a4d8-4e9f-a4fd91c230eb','a42a242d-10f8-41cf-3b28-5ae637aea753',3,'9-§. Tuban o''simliklar','Xlamidomonada qizil ko''zchasi nima uchun kerak?','Yorug''likni sezish uchun','["Ovqat hazm qilish uchun","Ko''payish uchun","Suvni tozalash uchun"]','U yorug''lik tomon yo''nalishni aniqlaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('279306e3-8d3a-7d7a-0fed-82297487ea40','a42a242d-10f8-41cf-3b28-5ae637aea753',4,'9-§. Tuban o''simliklar','Ulotriks suv tubiga nima bilan birikadi?','Rizoid','["Ildiz","Xivchin","Spora"]','Rizoid ildiz tukchalariga o''xshaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('2a7a365c-e572-cf71-2136-1154f6026c1c','a42a242d-10f8-41cf-3b28-5ae637aea753',5,'9-§. Tuban o''simliklar','Spirogiraning xromatofori qanday?','Spiralsimon buralgan','["Kosachasimon","Belbog''li","Tasmasimon"]','Shu belgi bilan boshqa suvo''tlardan farqlanadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('3483ff09-c50a-24bb-2a6d-34e59a393e6f','a42a242d-10f8-41cf-3b28-5ae637aea753',6,'9-§. Tuban o''simliklar','«Dengiz karami» deb qaysi suvo''t ataladi?','Laminariya','["Porfira","Xlorella","Ulotriks"]','U yodga boy.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('ffd018ac-4106-b1c2-3bfa-67aeb3448cf8','a42a242d-10f8-41cf-3b28-5ae637aea753',7,'9-§. Tuban o''simliklar','«Dengiz salati» deb ataladigan qizil suvo''t qaysi?','Porfira','["Laminariya","Spirogira","Xlamidomonada"]','Porfira bir qavatli, keng tallomli.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('78f4d48c-0784-efd4-2719-95ff129126b4','a42a242d-10f8-41cf-3b28-5ae637aea753',8,'9-§. Tuban o''simliklar','Ifloslangan suv havzalarini tozalashda qaysi suvo''tlar ishlatiladi?','Xlorella va xlamidomonada','["Laminariya va porfira","Faqat spirogira","Hech qaysi"]','Ular suvni kislorodga boyitib, tozalaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('40686efc-92cf-0f5e-59cd-8748ed749fee','a42a242d-10f8-41cf-3b28-5ae637aea753',9,'9-§. Tuban o''simliklar','Ulotriks noqulay sharoitda qanday ko''payadi?','Jinsiy yo''l bilan (izogametalar)','["Jinssiz, zoospora bilan","Kurtaklanib","Gifalar bilan"]','Izogametalar qo''shilib zigota hosil bo''ladi.');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('389f0ff4-cc7b-4e79-97bf-172f9a6d7c50','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','75645918-abc9-3dc4-4bb3-0a7dfa2070ca','{"uz":"Mavzu testi: Tuban o''simliklar","ru":"Mavzu testi: Tuban o''simliklar","en":"Mavzu testi: Tuban o''simliklar"}','test','a42a242d-10f8-41cf-3b28-5ae637aea753','',25,43);
insert into public.items(id, folder_id, kind, title, visible, source, created_by) values ('407894bd-0d50-e1f4-46fe-68e7bab6fb39', null, 'test', '{"uz":"8-§ + 9-§ takrorlash testi","ru":"8-§ + 9-§ takrorlash testi","en":"8-§ + 9-§ takrorlash testi"}', false, null, (select author_id from public.courses where id='70bcc0ad-19f0-0387-8586-5bdf7bf4f43e'));
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('dad5288d-a856-758c-75c7-5ae7ad659108','407894bd-0d50-e1f4-46fe-68e7bab6fb39',0,'8–9-§ takrorlash','8-mavzuda yuksak va tuban o''simliklar haqida o''rgandik. Tuban o''simlik – bu...','Suvo''tlar','["Yo''sinlar","Qirqquloqlar","Ochiq urug''lilar"]','Tuban o''simliklar bo''limi – suvo''tlar.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('702d8b9e-2d46-8869-3f2e-a9b334390e46','407894bd-0d50-e1f4-46fe-68e7bab6fb39',1,'8–9-§ takrorlash','Xlorella fotosintez qiladi. Bu o''simlikning qaysi xususiyatini ko''rsatadi va u produtsentmi?','Avtotrof; ha, produtsent','["Geterotrof; yo''q","Parazit; yo''q","Simbiont; yo''q"]','Organik modda hosil qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('cec4e976-d64d-79ed-fbf3-4ec80e14cf19','407894bd-0d50-e1f4-46fe-68e7bab6fb39',2,'8–9-§ takrorlash','Ulotriks rizoid bilan birikadi, yuksak o''simlikda esa bu vazifani qaysi organ bajaradi?','Ildiz','["Barg","Gul","Meva"]','Rizoid ildizga o''xshash.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('316d4141-e765-2e3b-6c84-071c2bf75ac0','407894bd-0d50-e1f4-46fe-68e7bab6fb39',3,'8–9-§ takrorlash','Suvo''tlar tallomi ildiz-poya-bargga bo''linmagan. Qaysi sistematik guruh tanasi ildiz, poya, bargdan iborat?','Yuksak o''simliklar','["Tuban o''simliklar","Tallomlilar","Hech qaysi"]','Yuksak o''simliklarda organlar bor.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('51d711a3-f3fa-8e40-626f-aeb98009fbd2','407894bd-0d50-e1f4-46fe-68e7bab6fb39',4,'8–9-§ takrorlash','Laminariya tarkibidagi yod nimaga yordam beradi (1-mavzuni eslang)?','Buqoq kasalligining oldini olishga','["Fotosintezga","Hujayra shirasini nordon qilishga","Suvni isitishga"]','Yod qalqonsimon bez uchun kerak.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('c0f5382e-9659-1184-bb91-53120c57bd09','407894bd-0d50-e1f4-46fe-68e7bab6fb39',5,'8–9-§ takrorlash','Xlamidomonada qizil ko''zchasi bilan yorug''likni sezadi. Bu tirik organizmning qaysi xususiyati?','Ta''sirlanish','["Ayirish","Ko''payish","Passiv harakat"]','Ta''sirga javob.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a0f8e39c-1836-f96e-866d-b730ab88e921','407894bd-0d50-e1f4-46fe-68e7bab6fb39',6,'8–9-§ takrorlash','Pristli tajribasi 8-mavzuda. Suvo''tlar ham kislorod chiqaradi. Suvo''tlar bu jihatdan nimaga o''xshaydi?','Yuksak o''simliklarga (fotosintez qiladi)','["Hayvonlarga","Zamburug''larga","Viruslarga"]','Fotosintez qiluvchi hamma o''simliklar kislorod chiqaradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('02937004-1223-8563-fc53-23df378a779b','407894bd-0d50-e1f4-46fe-68e7bab6fb39',7,'8–9-§ takrorlash','Zoospora va bakteriya sporasi o''xshashmi?','Ikkalasi ham spora, ammo zoospora xivchinli va ko''payish uchun','["Zoospora spora emas","Bakteriya sporasi xivchinli","Farqi yo''q"]','Bakteriya sporasi chidamli shakl, zoospora esa faol suzuvchi ko''payish hujayrasi.');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('bb13fdc1-38a5-9bc5-9162-72fc2e299258','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','75645918-abc9-3dc4-4bb3-0a7dfa2070ca','{"uz":"Takrorlash testi: 8-§ va 9-§","ru":"Takrorlash testi: 8-§ va 9-§","en":"Takrorlash testi: 8-§ va 9-§"}','test','407894bd-0d50-e1f4-46fe-68e7bab6fb39','',25,44);
