insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('81536b11-d338-7a84-d546-3e8be0bbf009','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','f5c1cd52-5ef3-4b05-644a-add408748c6d','{"uz":"Slayd: Yuksak o''simliklar","ru":"Slayd: Yuksak o''simliklar","en":"Slayd: Yuksak o''simliklar"}','slides',null,'',10,46);
insert into public.lesson_bodies(lesson_id, body) values ('81536b11-d338-7a84-d546-3e8be0bbf009','[{"h":"Yuksak o''simliklar – to''liq tanali","ic":"🌲","p":["Ildiz + poya + barg.","Ikki katta guruh: **sporali** va **urug''li**.","Spora – qulay sharoitda unib chiqadigan mayda ko''payish hujayrasi."],"q":"Suvo''tdan farqi nimada?","a":"Suvo''tda organlar ajralmagan (tallom), yuksak o''simliklarda ildiz, poya, barg bor."},{"h":"Yo''sin","ic":"🟩","p":["Zax joyda yashil «chim» hosil qiladi.","Ildizi yo''q, rizoidlari bilan birikadi.","Sporalari ko''sakchada yetiladi."],"q":"Yo''sin ko''proq nam joylarda nega uchraydi?","a":"Uning ildizi yo''q va suvni butun tanasi bilan so''radi; nam joyda yaxshi yashaydi."},{"h":"Qirqbo''g''im – ikki xil poya","ic":"🌱","p":["Bahorda: qo''ng''ir, mevali poya – boshoqda spora yetiladi.","Yozda: yashil, mevasiz poya – fotosintez qiladi, ildizpoyada oziq to''playdi.","Damlamasi siydik haydovchi dori."],"q":"Nega bitta o''simlik ikki xil poya hosil qiladi?","a":"Vazifa taqsimoti: biri ko''payadi, ikkinchisi oziq yaratadi."},{"h":"Qirqquloq va toshko''mir","ic":"🍃","p":["Barg ostidagi qo''ng''ir bo''rtma – **sorus**, sporalar shu yerda.","Qadimda daraxtsimon qirqquloqlar 20–25 m bo''lgan.","Ular nobud bo''lib toshko''mir qatlamlarini hosil qilgan."],"q":"Bugungi ko''mirda qadimgi o''simlik izi borligi nimani ko''rsatadi?","a":"Ko''mir qadimgi o''simlik qoldig''idan hosil bo''lgan, ya''ni tarixiy usul bilan o''rganiladi."},{"h":"Ochiq urug''lilar","ic":"🌲","p":["Archa, qarag''ay, sarv.","Urug'' **qubbada ochiq** yetiladi.","Chang shamolda tarqaladi, suv shart emas.","Smola ajratib o''zini himoya qiladi (kahrabo!).","Fitonsid ajratib havoni tozalaydi."],"q":"Nima uchun kasalxonalar yonida archa ekiladi?","a":"Fitonsid ajratib havodagi bakteriyalarni kamaytiradi."},{"h":"Archa va qarag''ay","ic":"🎄","p":["**Archa:** sekin o''sadi, 1000 yil yashaydi, tangachasimon barg, mum qoplama – suvni kam bug''latadi.","**Qarag''ay:** ninasimon barg, tez o''sadi, yog''ochi qurilishga.","Archa tog''ni yemirilishdan asraydi."],"q":"Archaning mum qoplami unga qanday foyda beradi?","a":"Suv bug''lanishini kamaytiradi – tog''dagi quruq sharoitda yashashga yordam beradi."},{"h":"Yopiq urug''lilar – eng yosh va keng tarqalgan","ic":"🌸","p":["Urug'' **meva ichida**, yopiq.","Gul hosil qiladi.","Daraxt (o''rik, terak), buta (anor, limon), o''t (qoqi, bug''doy).","Meva urug''ni himoya qiladi va tarqalishga yordam beradi."],"q":"Meva o''simlikka qanday foyda beradi?","a":"Urug''ni himoya qiladi va hayvonlar yeb, urug''ni uzoqqa tarqatadi."},{"h":"O''rik va terak","ic":"🍑","p":["**O''rik:** erta gullaydi, mevasi vitaminga boy, danagining mag''zi B vitaminlarga boy.","**Terak:** tez o''sadi, yog''ochbop, chang va shovqinni yutadi; momig''i allergiya chaqiradi."],"q":"Terak shaharga nima uchun ekiladi?","a":"Chang va shovqinni yutadi, tez o''sadi. Lekin uchma mevalari allergiyaga sabab bo''lishi mumkin."}]');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('f39f6ae3-5f02-d504-5e58-56fe529904af','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','f5c1cd52-5ef3-4b05-644a-add408748c6d','{"uz":"Kartochkalar: Yuksak o''simliklar","ru":"Kartochkalar: Yuksak o''simliklar","en":"Kartochkalar: Yuksak o''simliklar"}','cards',null,'',15,47);
insert into public.lesson_bodies(lesson_id, body) values ('f39f6ae3-5f02-d504-5e58-56fe529904af','[["tf","Yo''sin","Ildizi bo''lmagan, rizoidi bor yuksak sporali o''simlik",true],["tf","Sorus","Qirqquloq bargi ostidagi sporali bo''rtma",true],["tf","Qirqbo''g''im","Bitta turdagi poya hosil qiladi",false],["tf","Ochiq urug''lilar","Urug''i meva ichida yetiladi",false],["tf","Yopiq urug''lilar","Gulli o''simliklar, urug''i meva ichida yetiladi",true],["tf","Smola","Ochiq urug''lilar ajratadigan modda, kahrabo hosil qiladi",true],["tf","Qarag''ay","Tangachasimon bargli, 1000 yil yashovchi daraxt",false],["tf","Terak","Uchma mevasi allergiya chaqirishi mumkin",true],["type","Archa va qarag''ay qaysi bo''limga kiradi? (ochiq yoki yopiq urug''lilar: ... urug''lilar)","ochiq",["ochiq","ochiq urug''lilar"]],["type","Qadimgi qirqquloqlar nobud bo''lib nimaga aylangan?","toshko''mir",["toshko''mir","tosh ko''mir","ko''mir"]],["type","Ochiq urug''lilarda urug'' joylashgan bo''rtma","qubba",["qubba"]],["type","Bakteriyalarni o''ldiruvchi o''simlik moddasi","fitonsid",["fitonsid"]]]');
