insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a8de6e84-63e0-1920-93a5-9b4393f29071','406c6a66-336a-52fe-6523-f13ce8ebaa10',0,'10-§. Yuksak o''simliklar','Quyidagilardan qaysi biri yuksak sporali o''simlik?','Qirqquloq','["Archa","Olma","Spirogira"]','Yo''sin, qirqbo''g''im, qirqquloq sporali.');
