insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9f3c24a8-4fdf-c155-f9db-17678ae54259','406c6a66-336a-52fe-6523-f13ce8ebaa10',2,'10-§. Yuksak o''simliklar','Dala qirqbo''g''imining mevali poyasi qachon rivojlanadi?','Erta bahorda','["Yozda","Kuzda","Qishda"]','Mevasiz yashil poya esa yozda.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('d42f4fa2-a6db-60e8-b9ee-83669869c993','406c6a66-336a-52fe-6523-f13ce8ebaa10',3,'10-§. Yuksak o''simliklar','Sorus qaysi o''simlikda hosil bo''ladi?','Qirqquloq','["Yo''sin","Qirqbo''g''im","Archa"]','Sorusda sporalar yetiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b4890556-0b92-5a7c-a994-9672762e8c39','406c6a66-336a-52fe-6523-f13ce8ebaa10',4,'10-§. Yuksak o''simliklar','Ochiq urug''lilarning urug''i qayerda yetiladi?','Qubbada, ochiq holda','["Meva ichida","Ildizda","Bargda"]','Shu sababli ular ochiq urug''lilar deyiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9e28ed32-05f1-4c65-373c-ed608a3181e6','406c6a66-336a-52fe-6523-f13ce8ebaa10',5,'10-§. Yuksak o''simliklar','Ochiq urug''lilar urug''lanishi uchun suv shart emas, chunki...','Chang donachasini shamol tarqatadi','["Ular suvda yashaydi","Ularda urug'' bo''lmaydi","Ular faqat sporadan ko''payadi"]','Bu ularni suv kam joyga moslashtirgan.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b677cbc0-c7ac-f51a-3998-cd61a94aa64f','406c6a66-336a-52fe-6523-f13ce8ebaa10',6,'10-§. Yuksak o''simliklar','Kahrabo toshi nimadan hosil bo''ladi?','Qotib qolgan smoladan','["Dengiz suvo''tidan","Toshko''mirdan","Terak yog''ochidan"]','Smola yillar davomida qotadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('7a1f9392-9022-a3ad-a37d-c5e8720dc824','406c6a66-336a-52fe-6523-f13ce8ebaa10',7,'10-§. Yuksak o''simliklar','Yopiq urug''li o''simliklar yana qanday ataladi?','Gulli o''simliklar','["Ninabargli o''simliklar","Sporali o''simliklar","Tallomli o''simliklar"]','Ular gul hosil qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e710adc2-1cc0-e85c-17e2-c8ed16f63d59','406c6a66-336a-52fe-6523-f13ce8ebaa10',8,'10-§. Yuksak o''simliklar','Qaysi o''simlik yopiq urug''lilarga kiradi?','O''rik','["Qarag''ay","Archa","Sarv"]','O''rik gulli o''simlik.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('59be6bcd-4883-fec2-7968-1cb1669f5e51','406c6a66-336a-52fe-6523-f13ce8ebaa10',9,'10-§. Yuksak o''simliklar','Nima uchun yopiq urug''lilar hozirgi kunda eng keng tarqalgan?','Urug''i meva bilan himoyalangan va yaxshi tarqaladi','["Ular faqat suvda yashaydi","Ular sporadan ko''payadi","Ularning ildizi yo''q"]','Meva urug''ni himoya qiladi.');
