insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('dc7b2a6b-1d32-2f5e-9d4c-4afb688173bc','e44b41ed-4b20-f569-b500-f4372b1df82b',0,'9–10-§ takrorlash','Suvo''tlar (9-mavzu) tuban o''simlik. Yo''sin va suvo''tning o''xshashligi nima?','Ikkalasi ham sporalar bilan ko''payishi mumkin','["Ikkalasi ham ildizga ega","Ikkalasi ham urug''li","Ikkalasi ham gulli"]','Suvo''tlarda zoosporalar, yo''sinda sporalar bor.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9ce17f50-c16a-e819-31e2-1a30f172ff98','e44b41ed-4b20-f569-b500-f4372b1df82b',1,'9–10-§ takrorlash','Ulotriks rizoidi va yo''sin rizoidi: ularning vazifasi qanday?','Ikkalasi ham organizmni tayanchga biriktiradi','["Ikkalasi ham fotosintez qiladi","Ikkalasi ham gul hosil qiladi","Ikkalasi urug'' chiqaradi"]','Rizoid – ildizga o''xshash.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('29ecaae9-5aad-df29-ea6f-094a34d5de05','e44b41ed-4b20-f569-b500-f4372b1df82b',2,'9–10-§ takrorlash','Yuksak o''simliklar tanasi bilan suvo''tlarning tallomidan farq qiladi. Bu farq nimada?','Yuksaklarda ildiz, poya, barg ajralgan','["Yuksaklarda xromatofor bor","Yuksaklar suvda yashaydi","Suvo''tlar urug''li"]','Tallom – bo''linmagan tana.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('39a2dd93-f2f3-4c52-cc18-e49601844993','e44b41ed-4b20-f569-b500-f4372b1df82b',3,'9–10-§ takrorlash','Archa va xlorella: ikkalasi ham fotosintez qiladi. Ularning farqi?','Archa yuksak (urug''li), xlorella tuban (bir hujayrali)','["Ikkalasi tuban","Archa suvo''t","Xlorella urug''li"]','Archa ochiq urug''li yuksak o''simlik.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('26cf53b1-6fae-7cac-26ea-63135c32bb15','e44b41ed-4b20-f569-b500-f4372b1df82b',4,'9–10-§ takrorlash','Laminariya yodga boy, archa fitonsid ajratadi. Ikkalasi odam salomatligiga qanday yordam beradi?','Yod – bez uchun, fitonsid – havoni tozalash uchun','["Ikkalasi suv ichish uchun","Ikkalasi ham dori sifatida zaharli","Foydasi yo''q"]','Ikkalasining foydasi bor, har biri o''ziga xos.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('08d3c271-8b89-3d02-90ac-1baa7cce524f','e44b41ed-4b20-f569-b500-f4372b1df82b',5,'9–10-§ takrorlash','Pristli tajribasi: o''simlik kislorod chiqaradi. Daraxtsimon qirqquloqlar bu jihatdan qanday rol o''ynagan?','Qadimgi atmosferani kislorodga boyitgan va toshko''mir hosil qilgan','["Atmosferani zaharlagan","Hech rol o''ynamagan","Faqat tuproqni quritgan"]','Qadimgi o''rmonlar muhim rol o''ynagan.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('2b3d15fb-b28d-acdc-b40b-f366c0ac2a14','e44b41ed-4b20-f569-b500-f4372b1df82b',6,'9–10-§ takrorlash','Sistematikada archa qaysi bo''limga kiradi?','Ochiq urug''lilar','["Yopiq urug''lilar","Suvo''tlar","Qirqquloqlar"]','Urug''i qubbada ochiq.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('14c611ef-0e60-e8e5-e611-34d64429fca5','e44b41ed-4b20-f569-b500-f4372b1df82b',7,'9–10-§ takrorlash','Terak va makkajo''xori: ikkalasi yopiq urug''li. Ularning farqi?','Terak – daraxt, makkajo''xori – bir urug''pallali o''t','["Terak sporali","Makkajo''xori ochiq urug''li","Farqi yo''q"]','Ikkalasi ham yopiq urug''li, lekin turlicha shaklda.');
