insert into public.lesson_bodies(lesson_id, body) values ('21eac193-085d-a62d-65aa-740f60566c5d','[{"h":"Tabiat dorixonasi","ic":"🌿","p":["O''zbekistonda 4500 dan ortiq yuksak o''simlik o''sadi.","Ularning ko''pi dorivor – tibbiyotda va xalq tabobatida ishlatiladi.","Lekin ular orasida zaharlilari ham bor!"],"q":"Dorivor o''simlik va zaharli o''simlikni ko''rinishiga qarab ajratib bo''ladimi?","a":"Yo''q. Zaharlilarning guli ko''pincha chiroyli va hidi yoqimli. Shuning uchun faqat mutaxassisning fikriga ishonish kerak."},{"h":"Yalpiz","ic":"🍃","p":["Hushbo''y – chunki tarkibida **mentol** va efir moylari bor.","Asabni tinchlantiradi, balg''am ko''chiradi.","Yozda chanqovbosdi ichimlikka qo''shiladi."],"q":"Yalpiz hidi nega sovuqdek tuyuladi?","a":"Mentol shu ta''sirni beradi – u sovuqlik hissini uyg''otadi."},{"h":"Na''matak – vitamin ombori","ic":"🌹","p":["Atirgulning yovvoyi turi.","Mevasi **C vitaminiga** boy.","Immunitetni oshiradi, bahorda charchoqqa yordam beradi.","Termosda damlanganda vitamin ko''proq saqlanadi."],"q":"Nega qaynatganda C vitamini kamayadi?","a":"C vitamini yuqori haroratda tez buziladi, shuning uchun damlash yaxshiroq."},{"h":"Isiriq va shirinmiya","ic":"🌾","p":["**Isiriq:** asabni tinchlantiradi, tutuni xona havosini dezinfeksiya qiladi.","**Shirinmiya:** ildizpoyasi yo''tal va tomoqqa yordam beradi, dorixonada sirop shaklida."]},{"h":"Aloe – uydagi shifokor","ic":"🪴","p":["Barglari seret va sersuv.","Uzilgan bargni 10 kun salqin joyda saqlab, keyin ishlatiladi.","Asal bilan shamollash va oshqozon-ichakda foydali."],"q":"Aloeni nega faqat mutaxassis maslahati bilan ishlatish kerak?","a":"Dozasi noto''g''ri bo''lsa yoki allergiya bo''lsa, zarar qilishi mumkin."},{"h":"Zaharli o''simliklar – chiroyli, lekin xavfli","ic":"☠️","p":["**Bangidevona** – oq voronkasimon gul, tikanli ko''sak.","**Mingdevona** – oqish sariq gul, tikanli meva.","**Kanakunjut** – urug''i zaharli.","**Zaharli ayiqtovon** – bargidagi suyuqlik ko''zni yoshlantiradi."],"q":"Bangidevona hididan ham zaharlanish mumkinligi nimani anglatadi?","a":"Zaharli modda havo orqali ham tanaga kirishi mumkin, shuning uchun bunday o''simlikka yaqinlashmaslik kerak."},{"h":"Zaharlanish bo''lsa nima qilamiz?","ic":"🚑","p":["1. Bezovta bo''lmang, darhol kattalarga ayting.","2. **103** ga qo''ng''iroq qilib, tez yordam chaqiring.","3. O''simlikning nomi yoki qanday ko''rinishini eslang – shifokorga foydali.","4. O''zingiz dori bermang."],"q":"Nega bunday paytda vaqtni boy bermaslik kerak?","a":"Mingdevona kabi zaharlanishda 10–20 daqiqada belgi paydo bo''ladi, holat tez og''irlashishi mumkin."},{"h":"Oltin qoida","ic":"⚖️","p":["Zahar ham, dori ham **miqdorga** bog''liq.","Tabiatga chiqsangiz hech qanday o''simlikni tatib ko''rmang.","Dorivor o''simlikni faqat mutaxassis tavsiyasi bilan ishlating."],"q":"Kanakunjut zaharli, lekin undan soch moyi ham olinadi. Bu qoidani qanday tushuntiradi?","a":"Zaharli o''simlikning ba''zi qismlari (moy) tozalangan va to''g''ri ishlatilganda foydali bo''lishi mumkin. Hammasi qaysi qism va qanday ishlatilishiga bog''liq."}]');
