insert into public.lesson_bodies(lesson_id, body) values ('da630649-c80f-b435-1b8e-0fbabfad19e6','[["tf","Yalpiz","Mentol va efir moylari bor, asabni tinchlantiradi",true],["tf","Na''matak","Mevasi C vitaminiga boy",true],["tf","Isiriq","Zaharli o''simlik, hech qachon dori sifatida ishlatilmaydi",false],["tf","Shirinmiya","Quruq yo''tal va tomoq og''rig''ida ishlatiladi",true],["tf","Aloe","Xona o''simligi, seret sersuv barglari bor",true],["tf","Bangidevona","Faqat urug''i zaharli, boshqa qismlari xavfsiz",false],["tf","Mingdevona","Zaharlanish belgilari 10–20 daqiqada boshlanadi",true],["tf","Zaharli o''simliklar","Doim xunuk va yoqimsiz hidli bo''ladi",false],["type","Yalpizda mavjud bo''lgan sovuqlik beruvchi modda","mentol",["mentol"]],["type","Na''matakda ko''p bo''ladigan vitamin harfi","c",["c","c vitamini"]],["type","Zaharlanishda tez yordam raqami (raqam)","103",["103"]],["type","Kanakunjut urug''idan olinadigan modda","moy",["moy"]]]');
