insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('75e32982-5472-9b91-70b7-246ae15f2a76','31e9769d-2015-3096-2ce0-55170bf82212',1,'11-§. O''zbekistonda keng tarqalgan dorivor va zaharli o''simliklar','Na''matak mevasi organizm uchun nimasi bilan foydali?','C vitaminiga boyligi bilan','["Yod borligi bilan","Mentol borligi bilan","Smola borligi bilan"]','C vitamini immunitetni oshiradi.');
