insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('52422ff6-c9f4-2659-a540-3f5bfd023640','31e9769d-2015-3096-2ce0-55170bf82212',3,'11-§. O''zbekistonda keng tarqalgan dorivor va zaharli o''simliklar','Isiriq tutuni qanday foyda beradi?','Xona havosini dezinfeksiya qiladi','["Mevani pishiradi","Suvni tozalaydi","Tuproqni boyitadi"]','Isiriq tutuni kasallik tarqalishining oldini oladi.');
