insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('d80f9e40-be2f-a8ab-98cb-09e4ddbac217','31e9769d-2015-3096-2ce0-55170bf82212',8,'11-§. O''zbekistonda keng tarqalgan dorivor va zaharli o''simliklar','Nima uchun noma''lum o''simlikni tatib ko''rish mumkin emas?','Zaharli o''simlikning guli chiroyli, hidi yoqimli bo''lishi mumkin','["Hamma o''simlik zaharli","Ular achchiq bo''ladi","Ular suvda eriydi"]','Tashqi ko''rinishi aldamchi bo''lishi mumkin.');
