insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('cd8b5438-a7ac-8192-8e05-2bcd8b582315','9e3cbfd9-acfb-f290-5847-b9d4c34c1000',0,'10–11-§ takrorlash','Dorivor o''simliklar yuksak o''simliklar orasida. 10-mavzudan: na''matak atirgul bilan qarindosh. U yopiq yoki ochiq urug''lilardan qaysiga kiradi?','Yopiq urug''lilar (mevali, gulli)','["Ochiq urug''lilar","Sporali o''simliklar","Suvo''tlar"]','Na''matak gulli va mevali.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('60286d96-26d0-3f83-7ffb-9080530b3e37','9e3cbfd9-acfb-f290-5847-b9d4c34c1000',1,'10–11-§ takrorlash','Qarag''ay ninabargidagi fitonsid va yalpizdagi mentol: ikkalasi ham...','O''simlik ishlab chiqaradigan, odamga foyda beradigan moddalar','["Hayvon zaharlari","Bakteriya sporasi","Mineral o''g''it"]','Fitonsid – bakteriyalarni o''ldiradi, mentol – asabni tinchlantiradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b5ddb940-7d63-75a1-729d-f3bae9f7ec05','9e3cbfd9-acfb-f290-5847-b9d4c34c1000',2,'10–11-§ takrorlash','Qirqbo''g''im damlamasi siydik haydovchi dori. Bu ham yalpiz, na''matak kabi qaysi guruh?','Dorivor o''simliklar','["Zaharli o''simliklar","Suvo''tlar","Zamburug''lar"]','Qirqbo''g''im ham xalq tabobatida ishlatiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b1d5a605-a386-5c0b-18ce-5338c238803c','9e3cbfd9-acfb-f290-5847-b9d4c34c1000',3,'10–11-§ takrorlash','Bangidevona va mingdevona qaysi guruhga kiradi: sporali yoki urug''li va gul bormi?','Urug''li, gulli (yopiq urug''li)','["Sporali, gulsiz","Ochiq urug''li","Suvo''t"]','Ikkalasi ham guli va mevasi bor.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('8255a5cf-09a1-637e-47f0-f59f4ad3cc77','9e3cbfd9-acfb-f290-5847-b9d4c34c1000',4,'10–11-§ takrorlash','Aloe xona o''simligi. 2-mavzudagi qaysi xususiyat uni «tirik» qiladi?','U oziqlanadi, nafas oladi, o''sadi va ko''payadi','["U faqat quyoshda turadi","U harakat qiladi","U hujayrasiz"]','Tirik organizmning belgilari.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('57e17bf5-36da-7852-8429-52043d294fa1','9e3cbfd9-acfb-f290-5847-b9d4c34c1000',5,'10–11-§ takrorlash','Terak uchma mevalari allergiya chaqirishi mumkin. Zaharli o''simlik bilan umumiy xavf nima?','Odam salomatligiga zarar yetkazishi mumkin','["Ikkalasi ham oziq","Ikkalasi dori","Ikkalasi sporali"]','Bunday o''simliklardan ehtiyot bo''lish kerak.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('98701940-5674-c305-ae31-eb66121f9c56','9e3cbfd9-acfb-f290-5847-b9d4c34c1000',6,'10–11-§ takrorlash','Na''matak va olma ikkalasi atirgulning qarindoshlari. Ularda urug'' qayerda yetiladi?','Meva ichida','["Qubbada","Sorusda","Ildizda"]','Yopiq urug''lilarda urug'' meva ichida.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('45b3d6c4-d8a6-14cd-36a9-b0db2b85d46c','9e3cbfd9-acfb-f290-5847-b9d4c34c1000',7,'10–11-§ takrorlash','Isiriq tutuni, archa fitonsidi, aloe: ularning umumiy foydasi?','Salomatlikka yordam','["Oziq-ovqat","Qurilish","Yoqilg''i"]','Dorivor yoki tozalovchi xususiyatga ega.');
