insert into public.lesson_bodies(lesson_id, body) values ('c0230706-8e88-ddf1-f546-f131201a1294','[{"h":"Hayvon kim?","ic":"🐾","p":["**Erkin harakatlanadi.**","**Geterotrof** – tayyor oziq bilan oziqlanadi.","Ko''pchiligida **asab tizimi** bor.","Shu uch belgi uni o''simlikdan ajratadi."],"q":"Nega hayvonlarga asab tizimi kerak?","a":"Atrofdagi xavf va oziq haqida tez ma''lumot olish va harakatni boshqarish uchun."},{"h":"Tanadagi darajalar","ic":"🧱","p":["Hujayra → to''qima → organ → organlar sistemasi → organizm.","4 to''qima: qoplovchi, biriktiruvchi, nerv, muskul.","Misol: yurak – organ, qon aylanish – sistema."],"q":"Teri qaysi to''qimaga kiradi?","a":"Qoplovchi to''qimaga (tananing yuzasini qoplaydi)."},{"h":"Tabiat uchun hayvonlar","ic":"🐝","p":["Ozuqa zanjirida ishtirok etadi.","**Sanitarlar:** yomg''ir chuvalchangi, go''ng qo''ng''izi.","**Biofiltr:** ikki pallali mollyuska suvni tozalaydi.","**Changlatuvchi:** asalari, kapalak. **Tarqatuvchi:** olmaxon, qushlar."],"q":"Asalari yo''qolsa, qaysi ekinlarga zarar bo''ladi?","a":"Changlanishga muhtoj bo''lgan ko''pgina meva va sabzavotlarga hosil kamayadi."},{"h":"Odam uchun hayvonlar","ic":"🐑","p":["Oziq: go''sht, tuxum. Xomashyo: jun, pat.","Transport: ot, eshak. Qo''riqchi: it.","Dori: ilon zahri, bo''rsiq yog''i.","Lekin ba''zilari kasallik tarqatadi: pashsha, chivin."],"q":"Hayvon foydali yoki zararli bo''lishi qanday aniqlanadi?","a":"Bir hayvon bir holatda foydali, boshqasida zararli bo''lishi mumkin. Hammasi vaziyatga bog''liq."},{"h":"Ikki katta guruh","ic":"🦴","p":["**Umurtqali:** ichida umurtqa pog''onasi bor. Faqat bitta tip – xordalilar.","**Umurtqasiz:** umurtqasi yo''q. 7 ta tip."],"q":"Umurtqa nima vazifa bajaradi?","a":"Ichki organlarga tayanch bo''ladi."},{"h":"Xordalilar sinflari","ic":"🐟","p":["Baliqlar.","Suvda va quruqlikda yashovchilar.","Sudralib yuruvchilar.","Qushlar.","Sut emizuvchilar."]},{"h":"Umurtqasizlar tiplari","ic":"🐌","p":["1) Sodda hayvonlar, 2) Bo''shliqichlilar, 3) Yassi chuvalchanglar, 4) To''garak chuvalchanglar, 5) Halqali chuvalchanglar, 6) Mollyuskalar, 7) Bo''g''imoyoqlilar.","Keyingi mavzuda ularni birma-bir ko''ramiz."],"q":"Hasharot qaysi tipga kiradi?","a":"Bo''g''imoyoqlilar tipiga."},{"h":"Sistematik «pasport»","ic":"🐻","p":["Tur → urug'' → oila → turkum → sinf → tip → dunyo.","**Qo''ng''ir ayiq:** Ayiqlar oilasi. **Qor barsi:** Mushuklar oilasi.","Ikkalasi ham: xordalilar, sut emizuvchilar, yirtqichlar."],"q":"Ayiq va bars qaysi birlikkacha birga, qaysi birlikda ajraladi?","a":"Turkumgacha (yirtqichlar) birga, oila darajasida ajraladi (ayiqlar va mushuklar)."}]');
