insert into public.lesson_bodies(lesson_id, body) values ('7bf4c03d-c302-2d23-b6a0-3b28a326c679','[["tf","Hayvonlar","Erkin harakatlana oladi va geterotrof oziqlanadi",true],["tf","Hayvon to''qimalari","Qoplovchi, biriktiruvchi, nerv, muskul",true],["tf","Umurtqali hayvonlar","Bir necha tipga bo''linadi",false],["tf","Xordalilar tipi","Umurtqali hayvonlarning yagona tipi",true],["tf","Ikki pallali mollyuskalar","Suvni organik qoldiqdan tozalovchi biofiltr",true],["tf","Qor barsi","Ayiqlar oilasiga kiradi",false],["tf","Asalari","O''simliklarni changlatadi",true],["tf","Umurtqasizlar","Tiplari soni: 3 ta",false],["type","Hayvonot dunyosining boshqa nomi","fauna",["fauna"]],["type","Umurtqali hayvonlar kiradigan yagona tip","xordalilar",["xordalilar","xordali"]],["type","Eng kichik sistematik birlik","tur",["tur"]],["type","Umurtqasiz hayvonlarning tiplari soni (raqam)","7",["7","yetti"]]]');
