insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('96af3c00-bd1f-8950-c741-0b610bfadc59','bed33840-6764-8f0d-b58b-a008bd280cb6',2,'12-§. Hayvonot dunyosi','Yomg''ir chuvalchangi va go''ng qo''ng''izi tabiatda qanday rol o''ynaydi?','Sanitar','["Changlatuvchi","Parazit","Zararkunanda"]','Ular qoldiqlarni parchalaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a030f4ba-91c2-d220-1bae-9d1ddded0645','bed33840-6764-8f0d-b58b-a008bd280cb6',3,'12-§. Hayvonot dunyosi','Suvni organik qoldiqlardan tozalovchi biofiltr organizmlar kimlar?','Ikki pallali mollyuskalar','["Yirtqich baliqlar","Qushlar","Hasharotlar"]','Ular suvni filtrlaydi.');
