insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('1c8f4b2a-3c3b-e53b-30e8-f50b32fcdb7f','bed33840-6764-8f0d-b58b-a008bd280cb6',5,'12-§. Hayvonot dunyosi','Quyidagilardan qaysi biri xordalilarning sinfi emas?','Hasharotlar','["Baliqlar","Qushlar","Sut emizuvchilar"]','Hasharotlar bo''g''imoyoqlilarga kiradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('614d4ff9-e826-14ce-d5da-e0aa615f8487','bed33840-6764-8f0d-b58b-a008bd280cb6',6,'12-§. Hayvonot dunyosi','Umurtqasiz hayvonlar nechta tipga bo''linadi?','Yettita','["Uchta","Beshta","Ikkita"]','Sodda hayvonlardan bo''g''imoyoqlilargacha.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('f06142bf-0d70-6372-e731-8668817f2888','bed33840-6764-8f0d-b58b-a008bd280cb6',7,'12-§. Hayvonot dunyosi','Hayvonlar sistematikasida birliklar to''g''ri tartibda qaysi qatorda?','Tur – urug'' – oila – turkum – sinf – tip – dunyo','["Dunyo – tip – sinf – turkum – oila – urug'' – tur","Tur – oila – urug'' – sinf – turkum – tip – dunyo","Tip – tur – urug'' – dunyo – oila – sinf – turkum"]','Eng kichik birlik – tur.');
