insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('f537e9b8-655b-3917-b978-565719f0378c','6619188a-d698-b3b8-376d-10be5c304ab3',1,'11–12-§ takrorlash','Tabiatda o''simlik va hayvonning umumiy roli nimada?','Ozuqa zanjirida ishtirok etadi','["Fotosintez qiladi","Sporalar tarqatadi","Hujayrasiz tuzilgan"]','Ikkalasi ham ozuqa zanjiri halqasi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4363d7a7-7c31-ea49-f326-084d6fdc36a0','6619188a-d698-b3b8-376d-10be5c304ab3',2,'11–12-§ takrorlash','Produtsent organik modda hosil qiladi. Hayvon esa nima qiladi?','Tayyor organik modda bilan oziqlanadi','["O''zi organik modda yaratadi","Faqat havodan oziqlanadi","Fotosintez qiladi"]','Hayvon geterotrof.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('d563a9f8-cd6c-e75a-528a-bc1dd6d2f165','6619188a-d698-b3b8-376d-10be5c304ab3',3,'11–12-§ takrorlash','Hayvon hujayrasi (4-mavzu) o''simlik hujayrasidan nimasi bilan farq qiladi?','Sellyuloza qobig''i va plastidasi yo''q','["Yadrosi yo''q","Xloroplasti bor","Membranasi yo''q"]','Faqat o''simlikda sellyuloza qobiq va plastidalar bor.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('35fcf838-4ff5-b387-d3c5-585635c90f5b','6619188a-d698-b3b8-376d-10be5c304ab3',4,'11–12-§ takrorlash','Asalari o''simlikni changlatadi, o''simlik esa asalariga nima beradi?','Gul changi va nektar','["Kislorodgina","Vitamin","Hech narsa"]','Ikkalasiga foyda.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a235e5d8-c1b4-0f35-bb5a-c750989d8863','6619188a-d698-b3b8-376d-10be5c304ab3',5,'11–12-§ takrorlash','Quyidagilardan qaysi biri odamda kasallik qo''zg''atishi mumkin bo''lgan sodda hayvon?','Leyshmaniya','["Asalari","Yomg''ir chuvalchangi","Baqachanoq"]','Ba''zi sodda hayvonlar kasallik keltiradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('90719837-5d24-b273-c33c-957f7db46433','6619188a-d698-b3b8-376d-10be5c304ab3',6,'11–12-§ takrorlash','Ilon zahri tibbiyotda ishlatiladi (1-mavzu). Bu hayvonlarning odam uchun qaysi ahamiyatiga misol?','Dorivor ahamiyatiga','["Transport","Qo''riqlash","Oziq"]','Zahar miqdori hisoblab dori sifatida beriladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4a8f2f39-72b1-ebdf-f032-cf4183b47b3a','6619188a-d698-b3b8-376d-10be5c304ab3',7,'11–12-§ takrorlash','O''simlik va hayvon to''qimalarining umumiy tamoyili nima?','Bir xil vazifali hujayralar to''qimani hosil qiladi','["Ularda to''qima bo''lmaydi","Faqat o''simlikda to''qima bor","Faqat hayvonda organ bor"]','To''qima – bir xil vazifali hujayralar yig''indisi.');
