insert into public.lesson_bodies(lesson_id, body) values ('4740524d-5ddc-e15c-d074-3fb30f1ab536','[{"h":"Umurtqasizlar olami","ic":"🪱","p":["Ichki skeleti yo''q, lekin ular Yerdagi hayvonlarning eng ko''pchilik qismini tashkil qiladi.","7 tip: sodda hayvonlar, bo''shliqichlilar, yassi, to''garak, halqali chuvalchanglar, mollyuskalar, bo''g''imoyoqlilar."],"q":"Umurtqasiz bo''lsa ham ular qanday himoyalanadi?","a":"Chig''anoq, xitinli qobiq, kutikula, zahar, ogohlantiruvchi rang kabi usullar bilan."},{"h":"Sodda hayvonlar: bir hujayra – butun organizm","ic":"🔬","p":["**Amyoba** – shakli o''zgarib turadi.","**Evglena** – yashil, fotosintez qiladi, xivchini bilan suzadi.","**Tufelka** – tufli tagcharmiga o''xshash.","Ikkiga bo''linib ko''payadi."],"q":"Evglena o''simlikmi yoki hayvonmi?","a":"Ikkalasining belgisi bor: fotosintez qiladi (o''simlik), xivchini bilan harakatlanadi (hayvon). Shuning uchun uni chegaradagi organizm deyiladi."},{"h":"Bo''shliqichlilar","ic":"🪼","p":["Gidra, aktiniya, meduza.","Tanasi ikki qavat: ektoderma (tashqi) va endoderma (ichki).","**Otiluvchi hujayra** bilan o''lja tutadi.","**Regeneratsiya:** yo''qolgan qismi qayta o''sadi."],"q":"Gidrani ikkiga bo''lsak nima bo''ladi?","a":"Har bir bo''lagi yetishmayotgan qismini tiklab, yangi gidraga aylanadi (regeneratsiya)."},{"h":"Yassi va to''garak chuvalchanglar","ic":"🪱","p":["**Yassi:** planariya (erkin), jigar qurti, tasmasimon chuvalchang (parazit).","**To''garak:** kesmasi yumaloq, kutikula qobig''i bor. Askarida, rishta, nematoda – parazit.","Parazit tayyor oziqni so''radi, shuning uchun hazm tizimi yo''qolib ketishi mumkin."],"q":"Nega qo''lni sovunlab yuvish va sabzavotni yuvib yeyish kerak?","a":"Parazit chuvalchang tuxumlari qo''l va sabzavotda bo''lishi mumkin."},{"h":"Halqali chuvalchanglar – tuproq quruvchilari","ic":"🌱","p":["Tanasi halqalarga bo''lingan.","Birinchi marta **qon aylanish sistemasi** paydo bo''lgan.","Yomg''ir chuvalchangi tuproq hosil qiladi va havo kirishiga yordam beradi.","Zuluk – tibbiyotda qonni suyultiradi."],"q":"Dehqonlar yomg''ir chuvalchangini nega yoqtiradi?","a":"U tuproqni yumshatadi va chirindi bilan boyitadi."},{"h":"Mollyuskalar","ic":"🐌","p":["3 qavatli chig''anoq: tashqi organik, o''rta ohakli, ichki kamalak.","**Shilliqqurt** – o''simlik zararkunandasi.","**Baqachanoq** – suvni tozalaydi.","**Sakkizoyoq** – so''rg''ichlar, siyoh bilan dushmanni chalg''itadi."],"q":"Sakkizoyoq siyohni nima uchun chiqaradi?","a":"Dushmanini chalg''itib qochish uchun."},{"h":"Bo''g''imoyoqlilar – eng ko''p tur","ic":"🕷️","p":["Tana va oyoqlari bo''g''imli, tashqi skelet – **xitin**.","**Qisqichbaqasimonlar:** daryo qisqichbaqasi.","**O''rgimchaksimonlar:** butli o''rgimchak (to''r).","**Hasharotlar:** xonqizi – yorqin rangi «menga tegma» degani."],"q":"Xonqizi nega yorqin qizil rangda?","a":"Bu ogohlantiruvchi rang: qushlarga «men yoqimsizman, yema» deydi."},{"h":"Rivojlanish turlari","ic":"🦋","p":["**Chala o''zgarish:** tuxum → lichinka → voyaga yetgan (suvarak, chigirtka).","**To''liq o''zgarish:** tuxum → lichinka → **g''umbak** → voyaga yetgan (asalari, kapalak)."],"q":"Kapalak qurti va kapalak nega bir-biriga umuman o''xshamaydi?","a":"To''liq o''zgarishda lichinka g''umbak davrida tanasini butunlay qayta quradi."}]');
