insert into public.lesson_bodies(lesson_id, body) values ('be0e2451-10e5-ee05-cb14-d3ec6a693525','[["tf","Regeneratsiya","Yo''qolgan qismni tiklash qobiliyati",true],["tf","Evglena","Hech qachon fotosintez qilmaydigan sodda hayvon",false],["tf","Bo''shliqichlilar","Otiluvchi hujayralari bilan o''lja tutadi",true],["tf","Halqali chuvalchanglar","Qon aylanish sistemasi birinchi paydo bo''lgan tip",true],["tf","Zuluk","Tibbiyotda qonni suyultirish uchun ishlatiladi",true],["tf","Sakkizoyoq","Bo''g''imoyoqlilar tipiga kiradi",false],["tf","Xitin","Bo''g''imoyoqlilarning tashqi skeletini hosil qiladi",true],["tf","To''liq o''zgarish","Tuxum → lichinka → voyaga yetgan hasharot",false],["type","Askarida qaysi tipga kiradi? (… chuvalchanglar)","to''garak",["to''garak","to''garak chuvalchanglar"]],["type","Tashqi skeleti nimadan iborat bo''g''imoyoqlilarda?","xitin",["xitin"]],["type","Yomg''ir chuvalchangi qaysi tipga kiradi? (… chuvalchanglar)","halqali",["halqali","halqali chuvalchanglar"]],["type","To''liq o''zgarishda tuxum, lichinka, ..., voyaga yetgan hasharot. Yetishmayotgan bosqich?","g''umbak",["g''umbak","gumbak"]]]');
