insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('1eff7432-e8d6-bd42-8e6f-e2708e927311','10fea354-116b-0c12-061e-8a127dcf9f28',3,'13-§. Umurtqasiz hayvonlar','Regeneratsiya nima?','Yo''qolgan qismni tiklash qobiliyati','["Ikkiga bo''linib ko''payish","Fotosintez qilish","Rangini o''zgartirish"]','Gidrada bu yaxshi rivojlangan.');
