insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('c2a4a787-4126-9856-13b6-eb9687ceb99a','97442595-a655-f71e-092f-601f574756dc',0,'12–13-§ takrorlash','12-mavzuda umurtqasiz hayvonlar 7 tipga bo''linishini bildik. Hasharotlar ular ichida qaysi tipning sinfi?','Bo''g''imoyoqlilar tipining sinfi','["Mollyuskalar tipining sinfi","Xordalilar sinfi","Yassi chuvalchanglar sinfi"]','Hasharotlar bo''g''imoyoqlilar sinfiga kiradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4d1fdce5-6cad-c750-d2be-1c079ab8d1bb','97442595-a655-f71e-092f-601f574756dc',1,'12–13-§ takrorlash','Hayvonlarda 4 xil to''qima bor. Gidraning otiluvchi hujayralari qaysi vazifani bajaradi?','O''lja tutish va himoya','["Fotosintez","Nafas olish","Irsiy axborot saqlash"]','Otiluvchi hujayralar o''lja tutish va himoya uchun.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('54b271ac-3040-d7fc-c7df-10498bab082e','97442595-a655-f71e-092f-601f574756dc',2,'12–13-§ takrorlash','Yomg''ir chuvalchangi tabiat sanitari. Uni boshqa qaysi tirik guruh bilan solishtirish mumkin?','Chirituvchi bakteriyalar','["Parazit zamburug''lar","Viruslar","Suvo''tlar"]','Ikkalasi ham qoldiqlarni parchalaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('bd45de11-c24c-8715-faff-421d9bab3f03','97442595-a655-f71e-092f-601f574756dc',3,'12–13-§ takrorlash','Baqachanoq biofiltr. Suvni tozalashda u qaysi suvo''tlar singari ish ko''radi?','Xlorella va xlamidomonada','["Laminariya","Porfira","Ulotriks"]','Ular ham suv havzalarini tozalaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4dd560f3-26a3-045b-ba35-c6d00d13b67b','97442595-a655-f71e-092f-601f574756dc',4,'12–13-§ takrorlash','Evglena fotosintez qiladi. Bu qaysi tirik organizmlar bilan umumiy belgi?','Yashil o''simliklar bilan','["Zamburug''lar bilan","Bakteriyalar bilan","Viruslar bilan"]','Evglena xloroplast kabi tuzilmaga ega.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e82fabb8-cf86-0475-c23d-89543cf04cb6','97442595-a655-f71e-092f-601f574756dc',5,'12–13-§ takrorlash','Sodda hayvon amyoba (13-mavzu) bilan achitqi zamburug''i (7-mavzu) umumiy belgisi nima?','Ikkalasi bir hujayrali eukariot','["Ikkalasi prokariot","Ikkalasi fotosintez qiladi","Ikkalasi virus"]','Ikkalasi ham yadroli bir hujayrali.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('625a4261-383a-00d3-5e89-a9fa27bb674e','97442595-a655-f71e-092f-601f574756dc',6,'12–13-§ takrorlash','Parazit chuvalchang va parazit zamburug'' (qorakuya)ning o''xshashligi nima?','Xo''jayin organizm hisobiga yashaydi','["Ikkalasi fotosintez qiladi","Ikkalasi suvda yashaydi","Ikkalasi o''simlik"]','Parazit – boshqa tirik organizm hisobiga yashovchi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('8c0f7849-89a6-53a2-3378-05a6d61e2f08','97442595-a655-f71e-092f-601f574756dc',7,'12–13-§ takrorlash','To''liq o''zgarish bilan rivojlanuvchi asalari o''simliklarni changlatadi. Bu qaysi tirik xususiyatga yordam beradi?','O''simliklarning ko''payishiga','["Nafas olishga","Ayirishga","Fotosintezga"]','Changlanish urug'' va meva hosil bo''lishini ta''minlaydi.');
