insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('4b3f935b-8780-37d3-fb64-040ef0f62c6e','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','4917ba70-0842-da3d-d3fc-2ceeea597d7c','{"uz":"Slayd: Umurtqali hayvonlar","ru":"Slayd: Umurtqali hayvonlar","en":"Slayd: Umurtqali hayvonlar"}','slides',null,'',10,66);
insert into public.lesson_bodies(lesson_id, body) values ('4b3f935b-8780-37d3-fb64-040ef0f62c6e','[{"h":"Besh sinf – besh moslashuv","ic":"🦎","p":["Baliqlar, suvda va quruqlikda yashovchilar, sudralib yuruvchilar, qushlar, sut emizuvchilar.","Har biri o''z muhitiga moslashgan.","Asosiy farq – yurak, nafas, tana harorati va ko''payish."],"q":"Qaysi sinflar suvga eng bog''liq?","a":"Baliqlar (butunlay) va suvda-quruqlikda yashovchilar (tuxumini suvga qo''yadi)."},{"h":"Baliqlar","ic":"🐟","p":["Suyri tana, shilimshiq qoplama.","Jabra bilan nafas oladi.","Yurak 2 kamerali, qon aylanishi bitta doira.","Sovuqqonli: muhit isisa harakati tezlashadi."],"q":"Muz tagida baliq nega sekin harakat qiladi?","a":"Sovuqqonli: tana harorati suv harorati bilan bir xil, ya''ni past, harakat sustlashadi."},{"h":"Suvda va quruqlikda yashovchilar","ic":"🐸","p":["Teri va o''pka bilan nafas oladi.","Yurak 3 kamerali, ikki qon aylanish doirasi.","Tuxumini suvga qo''yadi – suvdan uzoqqa keta olmaydi.","Misol: baqa, salamandra, triton."],"q":"Baqa teri bilan ham nafas olgani uchun terisi qanday bo''lishi kerak?","a":"Doim nam bo''lishi kerak, quruq teri orqali gaz almashinuvi bo''lmaydi."},{"h":"Sudralib yuruvchilar – quruqlik fathchilari","ic":"🐍","p":["Muguz tangacha qoplagan tana.","Tuxumi qattiq po''choqli, sariqlikka boy.","Tuxumni quruqlikka qo''yadi – suvga bog''liq emas.","Cho''llarda keng tarqalgan."],"q":"Tuxumdagi qattiq po''choq nima uchun muhim?","a":"Tuxumni qurib qolishdan va shikastdan saqlaydi – quruqlikda rivojlanish uchun zarur."},{"h":"Qushlar – havo ustalari","ic":"🦅","p":["Pat bilan qoplangan tana, old oyoqlar qanotga aylangan.","Yurak 4 kamerali, issiqqonli.","Havo xaltachalari tufayli bir marta olgan havosidan 2 marta nafas oladi.","Tuxumini bosib yotadi."],"q":"Uchish uchun qush nega ko''p kislorod kerak?","a":"Uchish juda ko''p energiya sarflaydi; ikki marta nafas olish kislorodni to''liq o''zlashtirishga imkon beradi."},{"h":"Sut emizuvchilar","ic":"🐅","p":["Tanasi jun bilan qoplangan.","Bolasini sut bilan boqadi.","Yurak 4 kamerali, issiqqonli.","Hasharotxo''rlardan primatlargacha – juda xilma-xil sinf."],"q":"Odam qaysi sinfga kiradi?","a":"Sut emizuvchilar sinfiga."},{"h":"Sovuqqonli va issiqqonli","ic":"🌡️","p":["**Sovuqqonli:** tana harorati muhitga bog''liq (baliq, baqa, ilon).","**Issiqqonli:** tana harorati doimiy (qush, sut emizuvchi).","Issiqqonlilar qishda ham faol bo''la oladi, lekin ko''p oziq kerak."],"q":"Nega kaltakesak ertalab quyoshda isinadi?","a":"Sovuqqonli, shuning uchun harakat qilish uchun tashqi issiqlikdan foydalanadi."},{"h":"Baqaning hayot yo''li","ic":"🥚","p":["Tuxum (qora – quyoshni yaxshi yutadi) → itbaliq (suzgichli) → orqa oyoq → oldingi oyoq → dumi tushadi → yosh baqa.","Voyaga yetishi 3 yil.","Embrion tuxumdagi sariqlik bilan oziqlanadi."],"q":"Itbaliq nimasi bilan baliqqa o''xshaydi, voyaga yetgan baqa bilan esa nimasi farq qiladi?","a":"Suzgichi va suvda yashashi baliqqa o''xshash; baqada esa oyoq bor va quruqlikda yashaydi."}]');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('c6174435-47a2-8a57-30f9-5d3f850954b7','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','4917ba70-0842-da3d-d3fc-2ceeea597d7c','{"uz":"Kartochkalar: Umurtqali hayvonlar","ru":"Kartochkalar: Umurtqali hayvonlar","en":"Kartochkalar: Umurtqali hayvonlar"}','cards',null,'',15,67);
insert into public.lesson_bodies(lesson_id, body) values ('c6174435-47a2-8a57-30f9-5d3f850954b7','[["tf","Baliqlar","Yuragi 2 kamerali, jabra bilan nafas oladi",true],["tf","Suvda va quruqlikda yashovchilar","Yuragi 4 kamerali",false],["tf","Sudralib yuruvchilar","Tanasi muguz tangacha bilan qoplangan",true],["tf","Qushlar","Sovuqqonli hayvonlar",false],["tf","Sut emizuvchilar","Bolasini sut bilan boqadi, issiqqonli",true],["tf","Issiqqonli hayvon","Tana harorati tashqi muhitga bog''liq",false],["tf","Itbaliq","Baqaning suzgichli lichinkasi",true],["tf","Baqa tuxumi","Quruqlikda rivojlanadi",false],["type","Baliqlar nafas oladigan organ","jabra",["jabra"]],["type","Qushlarning yuragi necha kamerali (raqam)","4",["4","to''rt"]],["type","Tana harorati tashqi muhitga bog''liq hayvonlar (... qonli)","sovuq",["sovuq","sovuqqonli"]],["type","Baqa lichinkasi nomi","itbaliq",["itbaliq"]]]');
insert into public.items(id, folder_id, kind, title, visible, source, created_by) values ('02a22214-78e1-ac96-b08d-aeb180ef2ee4', null, 'test', '{"uz":"14-§ Umurtqali hayvonlar – mavzu testi","ru":"14-§ Umurtqali hayvonlar – mavzu testi","en":"14-§ Umurtqali hayvonlar – mavzu testi"}', false, null, (select author_id from public.courses where id='70bcc0ad-19f0-0387-8586-5bdf7bf4f43e'));
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('214a713d-4917-f1a9-cf2c-f14ec34467c5','02a22214-78e1-ac96-b08d-aeb180ef2ee4',0,'14-§. Umurtqali hayvonlar','Baliqlar qanday nafas oladi?','Jabra yordamida','["O''pka yordamida","Teri orqali","Havo xaltachalari bilan"]','Baliqlar suvda erigan kislorodni jabra bilan oladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a81dd276-1da2-6891-a405-fe49b4b2e61c','02a22214-78e1-ac96-b08d-aeb180ef2ee4',1,'14-§. Umurtqali hayvonlar','Baliqlar yuragi nechta kamerali?','Ikki','["Uch","To''rt","Bir"]','Yuragida venoz qon oqadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('66307744-7e65-57f1-9fa4-c4514a215bd2','02a22214-78e1-ac96-b08d-aeb180ef2ee4',2,'14-§. Umurtqali hayvonlar','Suvda va quruqlikda yashovchilar nega suvdan uzoqqa keta olmaydi?','Tuxumini suvga qo''yadi','["Nafas olishi uchun suv shart emas","O''pkasi yo''q","Yuragi bir kamerali"]','Tuxum va itbaliq suvda rivojlanadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b959e1ae-3371-710f-8ab4-0624e134ebc5','02a22214-78e1-ac96-b08d-aeb180ef2ee4',3,'14-§. Umurtqali hayvonlar','Sudralib yuruvchilar tanasi nima bilan qoplangan?','Muguz tangacha','["Pat","Jun","Shilimshiq"]','Bu quruqlikda qurib qolishdan saqlaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('41432de7-bc6e-09f0-1b81-99668057e125','02a22214-78e1-ac96-b08d-aeb180ef2ee4',4,'14-§. Umurtqali hayvonlar','Quyidagilardan qaysi biri sudralib yuruvchi?','Timsoh','["Qurbaqa","Triton","Burgut"]','Timsoh, ilon, kaltakesak – sudralib yuruvchilar.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('f74d7278-54e4-457a-6b00-818a63dc733e','02a22214-78e1-ac96-b08d-aeb180ef2ee4',5,'14-§. Umurtqali hayvonlar','Qushlar bir marta olgan havosidan necha marta nafas oladi?','Ikki marta','["Bir marta","Uch marta","Nafas olmaydi"]','Havo xaltachalari tufayli.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('fa285b09-b7e2-8392-6a72-c2f53a113d10','02a22214-78e1-ac96-b08d-aeb180ef2ee4',6,'14-§. Umurtqali hayvonlar','Qaysi sinf vakillari issiqqonli?','Qushlar va sut emizuvchilar','["Baliqlar va baqalar","Ilonlar va timsohlar","Faqat baliqlar"]','Tana harorati doimiy.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e622df8d-ac88-90b9-74a3-039090fe88c8','02a22214-78e1-ac96-b08d-aeb180ef2ee4',7,'14-§. Umurtqali hayvonlar','Sut emizuvchilarning asosiy belgisi qaysi?','Bolasini sut bilan boqadi','["Tuxumini bosib yotadi","Jabra bilan nafas oladi","Muguz tangacha"]','Shuning uchun ular sut emizuvchi deyiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('26ea7359-859f-f702-a58e-b50c5568dd27','02a22214-78e1-ac96-b08d-aeb180ef2ee4',8,'14-§. Umurtqali hayvonlar','Yuragi uch kamerali sinflar qaysilar?','Suvda-quruqlikda yashovchilar va sudralib yuruvchilar','["Baliqlar va qushlar","Qushlar va sut emizuvchilar","Faqat baliqlar"]','Qushlar va sut emizuvchilarniki 4 kamerali.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('dd247f65-f74f-6892-4feb-4e95488e0bbc','02a22214-78e1-ac96-b08d-aeb180ef2ee4',9,'14-§. Umurtqali hayvonlar','Itbaliq baqaga aylanishida dastlab qaysi oyoq paydo bo''ladi?','Orqa oyoq','["Oldingi oyoq","Ikkalasi bir vaqtda","Hech biri"]','Keyin oldingi oyoq rivojlanadi va dum tushadi.');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('1bff5182-b35e-4775-1ff6-11719430f164','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','4917ba70-0842-da3d-d3fc-2ceeea597d7c','{"uz":"Mavzu testi: Umurtqali hayvonlar","ru":"Mavzu testi: Umurtqali hayvonlar","en":"Mavzu testi: Umurtqali hayvonlar"}','test','02a22214-78e1-ac96-b08d-aeb180ef2ee4','',25,68);
insert into public.items(id, folder_id, kind, title, visible, source, created_by) values ('e7744387-d43f-7499-d3f1-216c58095661', null, 'test', '{"uz":"13-§ + 14-§ takrorlash testi","ru":"13-§ + 14-§ takrorlash testi","en":"13-§ + 14-§ takrorlash testi"}', false, null, (select author_id from public.courses where id='70bcc0ad-19f0-0387-8586-5bdf7bf4f43e'));
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('accc0aec-d972-3a3c-fc3f-657a215b0af4','e7744387-d43f-7499-d3f1-216c58095661',0,'13–14-§ takrorlash','13-mavzuda umurtqasizlarni o''rgandik. Umurtqali hayvonlar bilan asosiy farqi nimada?','Umurtqali hayvonlarda umurtqa pog''onasi bor','["Umurtqasizlar sovuqqonli","Umurtqasizlar hujayrasiz","Umurtqalilar geterotrof emas"]','Umurtqa tayanch vazifasini bajaradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('2d3ff6e4-90ef-dccd-1601-5d0bd5b72406','e7744387-d43f-7499-d3f1-216c58095661',1,'13–14-§ takrorlash','Asalari to''liq o''zgarish bilan, baqa esa qanday rivojlanishga ega (itbaliq bosqichi)?','Baqada ham lichinka (itbaliq) bosqichi bor','["Baqada lichinka bosqichi yo''q","Baqada faqat tuxum bor","Baqa to''liq o''zgarishsiz"]','Ikkalasida ham lichinka bosqichi bor, ikkalasi o''zgarib rivojlanadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('29b76e16-5373-5bae-87ee-6178443a918f','e7744387-d43f-7499-d3f1-216c58095661',2,'13–14-§ takrorlash','Xitin bo''g''imoyoqlilarda tashqi skelet. Sudralib yuruvchilarda tashqi qoplama nima?','Muguz tangacha','["Pat","Jun","Xitin"]','Muguz tangacha.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('832c07dc-26e7-b59f-ea69-24efa12d3a18','e7744387-d43f-7499-d3f1-216c58095661',3,'13–14-§ takrorlash','Halqali chuvalchanglarda qon aylanish sistemasi paydo bo''lgan. Baliqda qon aylanishi qanday?','Yopiq, bitta doira','["Ochiq","Ikki doira","Yo''q"]','Baliqda bitta doira.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('2286c2bc-0f5d-70c6-4f01-af09cc4a65fb','e7744387-d43f-7499-d3f1-216c58095661',4,'13–14-§ takrorlash','Sodda hayvon evglena va baliq: ikkalasi ham...','Suvda yashaydi','["Sovuqqonli emas","Issiqqonli","Quruqlikda yashaydi"]','Ikkalasi ham suv muhitida.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('12d8bce9-234b-24fe-5bd8-66b5aab36a8e','e7744387-d43f-7499-d3f1-216c58095661',5,'13–14-§ takrorlash','Hayvon hujayrasida qisqaruvchi vakuola bor (4-mavzu). Baqa va baliqda suv muvozanatini kim boshqaradi?','Ayirish sistemasi (buyrak)','["Faqat sellyuloza","Faqat spora","Xlorofill"]','Umurtqalilarda ayirish organlari.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('919ff365-838c-272c-fe69-777492b8692e','e7744387-d43f-7499-d3f1-216c58095661',6,'13–14-§ takrorlash','Parazit chuvalchang va qush: ikkalasi geterotrof. Bu qanday ma''noni anglatadi?','Ikkalasi ham tayyor oziq bilan oziqlanadi','["Ikkalasi fotosintez qiladi","Ikkalasi avtotrof","Ikkalasi o''simlik"]','Geterotrof – tayyor oziq.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9cb54444-517f-929f-2d30-a963a0c45dd8','e7744387-d43f-7499-d3f1-216c58095661',7,'13–14-§ takrorlash','Hayvon sistematikasida baliq, qush, sut emizuvchi qaysi birlik darajasida ajraladi?','Sinf darajasida','["Tur darajasida","Oila darajasida","Tip darajasida"]','Xordalilar tipi bir necha sinfga bo''linadi.');
