insert into public.lesson_bodies(lesson_id, body) values ('e53bcb69-ae44-95e9-4978-a6e872f1653a','[{"h":"Jamoa bo''lib ishlaydigan tana","ic":"🧍","p":["Hujayra → to''qima → organ → organlar sistemasi → organizm.","7 asosiy sistema.","Birortasi ishdan chiqsa, qolganlariga ham ta''sir qiladi."],"q":"Bir sistema buzilsa, nima uchun boshqalari ham zarar ko''radi?","a":"Sistemalar bir-biriga bog''liq: masalan, yurak ishlamasa, qon bilan kislorod boshqa organlarga yetmaydi."},{"h":"Tayanch-harakat","ic":"💪","p":["Skelet + muskullar.","Miya qutisi – miya himoyasi, ko''krak qafasi – o''pka va yurak himoyasi.","Qo''lni bukkanda ikki boshli qisqaradi, uch boshli bo''shashadi."],"q":"Qo''lni yozganda qaysi muskul qisqaradi?","a":"Uch boshli muskul qisqaradi, ikki boshli bo''shashadi."},{"h":"Qon aylanish","ic":"❤️","p":["4 kamerali yurak – nasos.","**Arteriya** – yurakdan chiqadi. **Vena** – yurakka kiradi. **Kapillyar** – mayda, to''qimalar orasida.","Yopiq sistema, 2 doira: katta va kichik."],"q":"Kapillyar nima uchun juda yupqa?","a":"Qon va to''qimalar orasida moddalar (kislorod, oziq) almashinuvi oson bo''lishi uchun."},{"h":"Hazm qilish","ic":"🍽️","p":["Og''iz → halqum → qizilo''ngach → oshqozon → ichak.","Og''izda tish va til ovqatni maydalaydi, so''lak bezlari ishlaydi."],"q":"Ovqatni yaxshilab chaynash nega foydali?","a":"Maydalangan ovqat tez va to''liq hazm bo''ladi, oshqozon yengillashadi."},{"h":"Nerv sistemasi","ic":"🧠","p":["Markaziy: bosh miya (miya qutisida) va orqa miya (umurtqa kanalida).","Periferik: nervlar va nerv tugunlari.","Butun organizmni boshqaradi."],"q":"Issiq narsaga tegib qo''lni tez tortib olish – bu nima bilan bog''liq?","a":"Nerv sistemasi signalni tez o''tkazib, himoya refleksini ishga soladi."},{"h":"Nafas olish","ic":"🫁","p":["Burun → halqum → traxeya → bronx → alveola → o''pka.","Alveola bilan kapillyar orasida gazlar almashadi.","Yopiq xonada havo kam kislorodli bo''ladi, shuning uchun uni almashtirish kerak."],"q":"Sinfda deraza ochib havo almashtirish nega kerak?","a":"Ko''p odam nafas olsa kislorod kamayib, karbonat angidrid ko''payadi – bosh og''riydi, diqqat pasayadi."},{"h":"Limfa – himoya posti","ic":"🛡️","p":["Limfa tugunlari, tomirlari, suyuqlik, taloq.","Tugunlar filtr kabi bakteriya va virusni ushlaydi.","Taloqda limfotsitlar hosil bo''ladi."],"q":"Kasallik paytida bo''yindagi limfa tugunlari kattalashishi nimani bildiradi?","a":"Ular mikrobga qarshi faol ishlayapti (tutib, zararsizlantirmoqda)."},{"h":"Endokrin: gormonlar","ic":"⚗️","p":["Ichki sekretsiya bezlari: gipofiz, epifiz, qalqonsimon, ayrisimon, buyrak usti.","Gormonlar qonga chiqadi, juda oz miqdorda ham kuchli ta''sir qiladi.","Adrenalin – qo''rqqanda ajraladi."],"q":"Nega qo''rqqanda yurak tez urib, kuch oshadi?","a":"Adrenalin gormoni ajralib, organizmni himoyaga (qochish yoki kurashishga) tayyorlaydi."}]');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('6b487f21-ebe7-e108-4720-cf736864e2d7','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','8641055e-8527-8b26-0965-150e29480d59','{"uz":"Kartochkalar: Odam organlari sistemasi","ru":"Kartochkalar: Odam organlari sistemasi","en":"Kartochkalar: Odam organlari sistemasi"}','cards',null,'',15,72);
insert into public.lesson_bodies(lesson_id, body) values ('6b487f21-ebe7-e108-4720-cf736864e2d7','[["tf","Arteriya","Yurakdan chiquvchi qon tomir",true],["tf","Vena","Yurakdan chiquvchi qon tomir",false],["tf","Kapillyar","To''qimalar orasidagi mayda qon tomir",true],["tf","Odam yuragi","3 kamerali",false],["tf","Orqa miya","Umurtqa pog''onasi kanalida joylashgan",true],["tf","Alveola","O''pkadagi gaz almashinuvi bo''ladigan qism",true],["tf","Limfa sistemasi","Immunitetni ta''minlashda ishtirok etadi",true],["tf","Gormon","Hazm qilishda ishlatiladigan shira",false],["type","Qo''rqqanda buyrak usti bezi ajratadigan gormon","adrenalin",["adrenalin"]],["type","Limfotsitlar hosil bo''ladigan organ","taloq",["taloq"]],["type","Qon aylanish doirasi nechta? (raqam)","2",["2","ikki"]],["type","Yurakka kiruvchi qon tomir","vena",["vena"]]]');
