insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('54c8fc3b-b236-c74c-7000-99f4b375aef7','fa469c65-b3eb-1ec0-9b12-cdc41826326d',1,'15-§. Odam organlari sistemasi','Arteriya qanday qon tomir?','Yurakdan chiquvchi','["Yurakka kiruvchi","To''qimalar orasidagi mayda","Faqat venoz"]','Vena yurakka kiradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('01b0d87f-4d15-6b23-65c9-f3a703a3db5e','fa469c65-b3eb-1ec0-9b12-cdc41826326d',2,'15-§. Odam organlari sistemasi','Odamda nechta qon aylanish doirasi bor?','Ikkita: katta va kichik','["Bitta","Uchta","To''rtta"]','Qon aylanish yopiq.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('c21f2b09-abe0-b7da-f188-394767d7681c','fa469c65-b3eb-1ec0-9b12-cdc41826326d',3,'15-§. Odam organlari sistemasi','Orqa miya qayerda joylashgan?','Umurtqa pog''onasi kanalida','["Miya qutisida","Ko''krak qafasida","Qorin bo''shlig''ida"]','Bosh miya esa miya qutisida.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('318418fb-ab1a-7348-5ded-004e07c92740','fa469c65-b3eb-1ec0-9b12-cdc41826326d',4,'15-§. Odam organlari sistemasi','Hazm yo''li to''g''ri tartibda qaysi qatorda?','Og''iz – halqum – qizilo''ngach – oshqozon – ichak','["Og''iz – oshqozon – halqum – ichak – qizilo''ngach","Halqum – og''iz – ichak – oshqozon","Qizilo''ngach – og''iz – halqum – ichak"]','Ovqat shu yo''ldan o''tadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b593e4b9-4c00-4737-007b-a8765d79a13c','fa469c65-b3eb-1ec0-9b12-cdc41826326d',5,'15-§. Odam organlari sistemasi','Gaz almashinuvi o''pkaning qaysi qismida bo''ladi?','Alveola va kapillyar orasida','["Traxeyada","Bronxda","Halqumda"]','Kislorod qonga, karbonat angidrid chiqishga o''tadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('5db140ad-e978-e284-9fa8-54c6e71e36d0','fa469c65-b3eb-1ec0-9b12-cdc41826326d',6,'15-§. Odam organlari sistemasi','Limfa tugunlarining vazifasi nima?','Bakteriya va viruslarni ushlab zararsizlantirish','["Qonni haydash","Ovqat hazm qilish","Nafas olish"]','Ular filtr vazifasini bajaradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('586ca6cd-8b2a-e4c8-360f-3cdcde1e71be','fa469c65-b3eb-1ec0-9b12-cdc41826326d',7,'15-§. Odam organlari sistemasi','Limfotsitlar qayerda hosil bo''ladi?','Taloqda','["Yurakda","Qizilo''ngachda","O''pkada"]','Taloq – limfa sistemasi organi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('43c12dfc-be34-928c-854d-d19151a28b6b','fa469c65-b3eb-1ec0-9b12-cdc41826326d',8,'15-§. Odam organlari sistemasi','Gormon nima?','Ichki sekretsiya bezlari qonga chiqaradigan biologik faol modda','["Hazm shirasi","Qon hujayrasi","Suyak qismi"]','Juda oz miqdorda ham ta''sir qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('43bad456-3bf8-3440-da2f-1dc287cbffc3','fa469c65-b3eb-1ec0-9b12-cdc41826326d',9,'15-§. Odam organlari sistemasi','Adrenalin qaysi bezda ishlab chiqariladi va qachon ko''p ajraladi?','Buyrak usti bezida, qo''rqqanda','["Qalqonsimon bezda, ovqatdan keyin","Taloqda, uxlaganda","Gipofizda, qorong''ida"]','Himoya refleksini ishga tushiradi.');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('f2c68d0b-ad7c-bd81-e2cb-5560f6a6d049','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','8641055e-8527-8b26-0965-150e29480d59','{"uz":"Mavzu testi: Odam organlari sistemasi","ru":"Mavzu testi: Odam organlari sistemasi","en":"Mavzu testi: Odam organlari sistemasi"}','test','fa469c65-b3eb-1ec0-9b12-cdc41826326d','',25,73);
insert into public.items(id, folder_id, kind, title, visible, source, created_by) values ('a49c11fa-ff58-f76d-c9cd-8270b487953f', null, 'test', '{"uz":"14-§ + 15-§ takrorlash testi","ru":"14-§ + 15-§ takrorlash testi","en":"14-§ + 15-§ takrorlash testi"}', false, null, (select author_id from public.courses where id='70bcc0ad-19f0-0387-8586-5bdf7bf4f43e'));
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('11ed1fea-7592-af8d-1b15-4fc57388be25','a49c11fa-ff58-f76d-c9cd-8270b487953f',0,'14–15-§ takrorlash','14-mavzuda qushlar va sut emizuvchilarning yuragi 4 kamerali ekanini bilib oldik. Odamning yuragi qaysi sinfnikiga o''xshaydi?','Sut emizuvchilarniki','["Baliqlarniki","Baqalarniki","Ilonlarniki"]','Odam sut emizuvchilar sinfiga kiradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('faf02d03-c7ef-24e7-6f52-f7a2dbb3baa3','a49c11fa-ff58-f76d-c9cd-8270b487953f',1,'14–15-§ takrorlash','Qush ham, odam ham issiqqonli. Bu nimani bildiradi?','Tana harorati doimiy','["Tana harorati muhitga bog''liq","Ikkalasi ham jabra bilan nafas oladi","Ikkalasi tuxum qo''yadi"]','Issiqqonli – doimiy harorat.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9fc5d239-a237-8ee9-dd1b-395621115491','a49c11fa-ff58-f76d-c9cd-8270b487953f',2,'14–15-§ takrorlash','Baliq yuragi 2 kamerali, odamniki 4 kamerali. Bu farq nimani ko''rsatadi?','Odamda qon aylanishi mukammalroq','["Odam sovuqqonli","Baliq issiqqonli","Baliq quruqlikda yashaydi"]','Ko''proq kamera – qon aylanishi samaraliroq.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('ad32338d-d219-e392-ab81-b52e13c9f678','a49c11fa-ff58-f76d-c9cd-8270b487953f',3,'14–15-§ takrorlash','Hayvonlarda 4 xil to''qima bor (12-mavzu). Odam yuragi qaysi to''qimalardan tuzilgan?','Muskul, biriktiruvchi, epiteliy','["Faqat nerv","Faqat qoplovchi","Faqat suyak"]','Turli to''qimalar organni hosil qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('3838c09e-5001-2427-2aa2-b78d3df35640','a49c11fa-ff58-f76d-c9cd-8270b487953f',4,'14–15-§ takrorlash','Baqa teri va o''pka bilan, odam nafas yo''llari bilan nafas oladi. Ularning umumiy nafas organi nima?','O''pka','["Jabra","Teri","Havo xaltachalari"]','Ikkalasida ham o''pka bor.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('d50cc3a7-590c-383e-ec2a-831ac82888fd','a49c11fa-ff58-f76d-c9cd-8270b487953f',5,'14–15-§ takrorlash','Hazm qilish va nafas olish: ikkalasi ham tirik organizmning qaysi xususiyati bilan bog''liq?','Moddalar almashinuvi','["Ko''payish","Harakat","Spora hosil qilish"]','Oziqlanish va nafas – metabolizm qismi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9ece6a49-a683-350e-5b8a-cf9680824cec','a49c11fa-ff58-f76d-c9cd-8270b487953f',6,'14–15-§ takrorlash','Limfa tugunlari bakteriyalarni ushlab qoladi. 6-mavzudan: parazit bakteriyalar qaysi kasalliklarni keltiradi?','Sil, vabo, o''lat, ichburug'', qoqshol','["Gripp, quturish","Qorakuya, vilt","Zang, mog''or"]','Bakteriyalar keltirgan kasalliklar.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('cbbbc0fb-4a19-8148-53fc-e3deed279368','a49c11fa-ff58-f76d-c9cd-8270b487953f',7,'14–15-§ takrorlash','Nerv hujayrasi (4-mavzu) signal o''tkazadi. Nerv sistemasida bu nima hosil qiladi?','Boshqaruv va refleks','["Fotosintez","Spora","Gormon emas, faqat oziq"]','Nerv sistemasi organizmni boshqaradi.');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('6594d6b2-d5f5-1ef9-f806-4825af51f752','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','8641055e-8527-8b26-0965-150e29480d59','{"uz":"Takrorlash testi: 14-§ va 15-§","ru":"Takrorlash testi: 14-§ va 15-§","en":"Takrorlash testi: 14-§ va 15-§"}','test','a49c11fa-ff58-f76d-c9cd-8270b487953f','',25,74);
