insert into public.items(id, folder_id, kind, title, visible, source, created_by) values ('6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6', null, 'test', '{"uz":"2-bob. Tirik organizmlar dunyosi – yakuniy test","ru":"2-bob. Tirik organizmlar dunyosi – yakuniy test","en":"2-bob. Tirik organizmlar dunyosi – yakuniy test"}', false, null, (select author_id from public.courses where id='70bcc0ad-19f0-0387-8586-5bdf7bf4f43e'));
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('23c634e6-4149-6cab-8977-d9a8e7ae9583','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',0,'5-§ Tirik organizmlar haqida umumiy ma''lumot','Quyidagi to''rt dunyodan qaysi birida hujayra yadrosi shakllanmagan?','Bakteriyalar','["Zamburug''lar","O''simliklar","Hayvonlar"]','Prokariotlarga bakteriyalar kiradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('ee47126a-50dc-1633-18e2-c2818afc8f88','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',1,'5-§ Tirik organizmlar haqida umumiy ma''lumot','Viruslar nima uchun «jonsiz va jonli tabiat o''rtasida oraliq» deyiladi?','Faqat hujayra ichida tiriklik belgilarini ko''rsatadi','["Ular juda katta","Ular fotosintez qiladi","Ular har doim harakat qiladi"]','Hujayrasiz hayot shakli.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('fa7cb144-7646-e375-9ea1-c80a9aeea33b','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',2,'6-§ Bakteriyalar dunyosi','Qaysi bakteriyalar dukkakdosh o''simlik ildizida yashab, havo azotidan o''simlikni ta''minlaydi?','Tugunak bakteriyalar','["Achituvchi","Chirituvchi","Parazit"]','Ularning hamkorligi simbioz deyiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('c408bd28-2b7f-8cd2-d825-78b13cc63c67','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',3,'6-§ Bakteriyalar dunyosi','Tuzlama tayyorlashda sabzavot nima uchun chirimaydi?','Achituvchi bakteriyalar sut kislota hosil qiladi','["Tuz hammasini o''ldiradi","Havo kirmaydi","Suv zaharlanadi"]','Sho''r muhitda sut kislota ko''payadi va chirishni to''xtatadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('381e1b14-da5f-ed36-88e5-753f70f3f2ee','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',4,'6-§ Bakteriyalar dunyosi','Kasallik tarqalishining oldini olishda qaysi qoida eng muhim?','Gigiyena: ovqatdan oldin qo''lni sovunlab yuvish','["Ko''p yugurish","Sovuq suv ichish","Qo''lni artmaslik"]','Karantin va gigiyena bakteriyadan himoyalaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('c581d8fe-4ea9-7037-4d3a-af24237a15c8','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',5,'7-§ Zamburug''lar dunyosi','Non selofan paketda uzoq turib qolsa nima bo''ladi?','Mog''or rivojlanadi','["Achitqi ko''payadi va ko''tariladi","Bakteriya o''ladi","O''simlik unadi"]','Nam muhit mog''or uchun qulay.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b564b47b-75f5-d7b1-f79e-c3ec5bc1fb1e','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',6,'7-§ Zamburug''lar dunyosi','Iste''mol qilsa bo''ladigan qo''ziqorinni tayyorlashda nima qilish kerak?','5–7 daqiqa qaynatib, suvini to''kish','["Xom yeyish","Quruq qovurish","Sovuq suvga solib qo''yish"]','Zaharli moddalar suvga chiqib ketadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a0ba44b3-a34e-54c1-b167-9cb9df666b6e','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',7,'8-§ O''simliklar dunyosi','Qaysi tirik guruh fotosintez qilib atmosferaga kislorod chiqaradi?','O''simliklar va suvo''tlar','["Zamburug''lar","Viruslar","Hayvonlar"]','Xlorofill yordamida.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('9a2458aa-db9f-0ce1-0164-580ec9cc809a','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',8,'8-§ O''simliklar dunyosi','Quyidagilardan qaysi biri generativ organ?','Meva','["Ildiz","Poya","Barg"]','Gul, meva, urug'' – generativ.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('cae0d7a7-c50e-6afd-b93a-008670f69d44','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',9,'8-§ O''simliklar dunyosi','O''simliklar sistematikasida «turkum» qaysi birlikdan kattaroq?','Tur','["Oila","Sinf","Bo''lim"]','Tur → turkum → oila → sinf → bo''lim → dunyo.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('6c612ab2-59c3-ea6f-d0a8-9733966a8844','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',10,'9-§ Tuban o''simliklar','Xlamidomonadaning qizil ko''zchasi va xivchinlari unga nimaga yordam beradi?','Yorug''likni sezib, unga qarab suzishga','["Ko''payishga","Suvni hazm qilishga","Spora hosil qilishga"]','Yorug''lik fotosintez uchun kerak.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b1402a2f-90bd-1def-7479-3b5dd1ca3a20','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',11,'9-§ Tuban o''simliklar','Ulotriks qaysi suvo''tlar guruhiga kiradi?','Ko''p hujayrali yashil suvo''tlarga','["Bir hujayrali qizil","Ko''p hujayrali qo''ng''ir","Sporali yo''sinlarga"]','Ipsimon yashil suvo''t.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('f64fa0f3-6e70-ac1f-07c9-ad17748c7201','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',12,'10-§ Yuksak o''simliklar','Qaysi yuksak o''simlikda ikki xil poya bo''ladi?','Dala qirqbo''g''imida','["Funariya yo''sinida","Qarag''ayda","Terakda"]','Bahorda mevali, yozda mevasiz poya.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('fafe76b9-8e1e-0169-f0f2-693964677a99','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',13,'10-§ Yuksak o''simliklar','Ochiq urug''lilar suv kam sharoitga moslashganining sababi nima?','Chang donachasini shamol tarqatadi, urug''lanishda suv shart emas','["Ular suvda yashaydi","Urug''i meva ichida","Faqat sporadan ko''payadi"]','Bu ularning ustunligi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b6bcd7c2-dbd1-e667-b7e2-027c89a474eb','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',14,'10-§ Yuksak o''simliklar','Yopiq urug''li o''simliklarning eng ko''p tarqalishiga nima sabab?','Urug''i meva bilan himoyalangan','["Ildizi yo''q","Tanasi tallomdan iborat","Sporalari ko''p"]','Meva urug''ni himoya qiladi va tarqalishga yordam beradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e1335272-ee8c-db0e-155c-80329c52aeaf','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',15,'11-§ O''zbekistonda keng tarqalgan dorivor va zaharli o''simliklar','Na''matak vitaminlari yaxshiroq saqlanishi uchun uni qanday tayyorlash tavsiya etiladi?','Termosda damlash','["Uzoq qaynatish","Quritib qovurish","Yog''da pishirish"]','Qaynatishda vitaminlar kamayadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('faa0bade-089a-fe34-79f9-274c70f3ec0b','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',16,'11-§ O''zbekistonda keng tarqalgan dorivor va zaharli o''simliklar','Zaharli o''simliklarning xavfi nimada?','Chiroyli va xushbo''y bo''lishi mumkin, lekin zaharli','["Ular har doim xunuk","Ular hech qachon gullamaydi","Ular zaharsiz"]','Ularni tatib ko''rish mumkin emas.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('f769712c-8111-2bbd-cf87-c7e6db6e413e','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',17,'14-§ Umurtqali hayvonlar','Yurak 3 kamerali va tuxumini quruqlikka qo''yadigan hayvon qaysi sinfga kiradi?','Sudralib yuruvchilar','["Baliqlar","Qushlar","Sut emizuvchilar"]','Tuxumi qattiq po''choqli.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('f0fd1e45-2674-a3c0-d193-d328496842a6','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',18,'12-§ Hayvonot dunyosi','Hayvonot dunyosi umurtqasining mavjudligiga ko''ra qanday guruhlanadi?','Umurtqali va umurtqasiz','["Issiqqonli va sovuqqonli","Suvda va quruqlikda","O''txo''r va yirtqich"]','Umurtqali – faqat xordalilar.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('cb681543-9d47-83e4-a836-2af9799b70dc','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',19,'13-§ Umurtqasiz hayvonlar','Gidrada yo''qolgan qism tiklanishi qanday xususiyat?','Regeneratsiya','["Assimilyatsiya","Metamorfoz","Fotosintez"]','Bo''shliqichlilarda yaxshi rivojlangan.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('d35095be-3e02-1f66-aaa9-b5e7760daa03','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',20,'13-§ Umurtqasiz hayvonlar','Qaysi hayvonlar tashqi skeleti xitindan iborat?','Bo''g''imoyoqlilar','["Mollyuskalar","Halqali chuvalchanglar","Baliqlar"]','Qisqichbaqa, o''rgimchak, hasharot.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('060690d6-9876-0398-7165-dcc41de1bd43','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',21,'15-§ Odam organlari sistemasi','Odamda gaz almashinuvi o''pkaning qaysi qismida sodir bo''ladi?','Alveola va kapillyar orasida','["Traxeyada","Qizilo''ngachda","Halqumda"]','Kislorod qonga o''tadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('6e488c1d-1507-fcb3-bfe5-14bd44ef81a0','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',22,'15-§ Odam organlari sistemasi','Qon aylanish sistemasiga qaysi organlar kiradi?','Yurak, arteriya, vena va kapillyarlar','["Oshqozon, ichak","Miya, orqa miya","Taloq, limfa tuguni"]','Qonni butun tanaga haydaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4ae10e0c-9f0e-a4ed-7973-8d99589f9f23','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',23,'15-§ Odam organlari sistemasi','Ichki sekretsiya bezlari ishlab chiqaradigan modda qanday ataladi?','Gormon','["Vitamin","Mineral","Limfa"]','Qonga chiqadi va jarayonlarga ta''sir qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('7cdd7af8-d66d-1bf6-cf9d-80b25c86761e','6a06ad5d-5b04-3d23-82d6-5c3c7b36c7d6',24,'13-§ Umurtqasiz hayvonlar','Yassi chuvalchang jigar qurti qanday oziqlanadi?','Parazit: boshqa organizm hisobiga','["Fotosintez bilan","Yirtqich sifatida","Chiritib"]','Tayyor oziqni so''radi.');
