insert into public.lesson_bodies(lesson_id, body) values ('28692cc6-2bed-30b6-e431-233aea5fac74','[{"h":"Tashqi dunyo bizga qanday ta''sir qiladi?","ic":"🌦️","p":["Yorug''lik, issiqlik, nam, boshqa jonzotlar, inson – hammasi tirik organizmga ta''sir qiladi.","Bu ta''sirlar **ekologik omillar**.","Uch guruh: abiotik, biotik, antropogen."]},{"h":"Abiotik – jonsiz omillar","ic":"☀️","p":["Yorug''lik, namlik, harorat.","Misol: cho''lda issiq va quruq, o''rmonda salqin va nam.","Organizm shunga moslashadi."],"q":"Kaktusning qalin etli poyasi qaysi omilga moslashuv?","a":"Namlikning yetishmasligiga: suvni zaxira qiladi."},{"h":"Biotik – tirik omillar","ic":"🐝","p":["Tirik organizmlarning bir-biriga ta''siri.","Yirtqich va o''lja. Parazit va xo''jayin. Asalari va gul.","Bir tur boshqasining hayotini o''zgartiradi."],"q":"Asalari va gul orasidagi munosabat qaysi omilga kiradi?","a":"Biotik omilga: ikkalasiga foyda keltiradi."},{"h":"Antropogen – inson omili","ic":"🧑‍🌾","p":["Inson tabiatni o''zgartiradi.","Ijobiy: yangi nav va zotlar.","Salbiy: o''rmonni kesish, havoni ifloslantirish."],"q":"Bitta ijobiy va bitta salbiy antropogen omil ayting.","a":"Ijobiy: yangi nav yaratish. Salbiy: haddan ortiq daraxt kesish yoki ifloslantirish."},{"h":"Biotsenoz: «tirik jamoa»","ic":"🏞️","p":["Bir joyda yashovchi o''simlik, hayvon, mikroorganizmlar uyushmasi.","**Produtsent** – ishlab chiqaradi.","**Konsument** – iste''mol qiladi.","**Redutsent** – parchalaydi."],"q":"Bakteriya va zamburug'' nega redutsent?","a":"Ular o''lik qoldiqlarni parchalab, mineral moddalarga aylantiradi, o''simliklar yana ulardan foydalanadi."},{"h":"Ozuqa zanjiri","ic":"⛓️","p":["Bug''doy → chigirtka → baqa → ilon → burgut.","Birinchi halqa – o''simlik (produtsent).","Hammasi – konsument. Oxirida redutsentlar parchalaydi."],"q":"Bu zanjirda ilon yo''qolsa nima bo''ladi?","a":"Baqalar ko''payib ketadi (chigirtka kamayadi), burgut esa oziqsiz qoladi."},{"h":"Zanjir uzilsa","ic":"💥","p":["Yomg''ir kam → o''simlik kam → chigirtka kam → qush kam → yirtqich qush kam.","Tabiatda hamma narsa bir-biri bilan bog''langan."],"q":"Fermer bo''rilarni yo''q qildi: avval qo''ylar ko''paydi, keyin kasallikdan ko''p tuyoqlilar qirildi. Nega?","a":"Bo''rilar kasal va kuchsiz hayvonlarni yeb, populyatsiyani sog''lom saqlagan. Ularsiz kasallik tarqaldi."},{"h":"Quyon va tulki","ic":"🐇","p":["Quyon ko''paysa – tulki ko''payadi (oziq ko''p).","Tulki ko''paysa – quyon kamayadi.","Quyon kamaysa – tulki ham kamayadi.","Ular bir-biriga bog''liq, sonlari tebranib turadi."],"q":"Bu bog''lanishdan qanday xulosa qilamiz?","a":"Yirtqich va o''lja soni bir-biriga bog''liq va tabiiy muvozanatni ushlab turadi."}]');
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('546127d9-8b8a-8d51-271e-8fcd2a32e345','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','b3f768b9-4a2c-0066-3051-033c4e276b9c','{"uz":"Kartochkalar: Ekologik omillar","ru":"Kartochkalar: Ekologik omillar","en":"Kartochkalar: Ekologik omillar"}','cards',null,'',15,78);
insert into public.lesson_bodies(lesson_id, body) values ('546127d9-8b8a-8d51-271e-8fcd2a32e345','[["tf","Abiotik omil","Jonsiz tabiat omili: yorug''lik, namlik, harorat",true],["tf","Biotik omil","Inson faoliyatining tabiatga ta''siri",false],["tf","Antropogen omil","Inson faoliyatining tabiatga ta''siri",true],["tf","Produtsent","Organik moddani parchalovchi bakteriya",false],["tf","Konsument","Tayyor organik modda iste''mol qiluvchi organizm",true],["tf","Redutsent","Organik moddalarni mineral moddalarga aylantiruvchi",true],["tf","Ozuqa zanjirining birinchi halqasi","Yirtqich hayvon",false],["tf","Biotsenoz","Tabiiy jamoaning jonli qismi",true],["type","Jonsiz tabiat omillari (… omillar)","abiotik",["abiotik"]],["type","Organik modda hosil qiluvchilar","produtsent",["produtsent","produtsentlar"]],["type","Parchalovchilar","redutsent",["redutsent","redutsentlar"]],["type","Ozuqa zanjirining birinchi halqasidagi organizmlar (o''…)","o''simlik",["o''simlik","o''simliklar"]]]');
