insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e49a5ba3-67c7-7f79-f7ac-e038485164f6','afc0878d-2e06-f904-2b76-e6ed41841c55',3,'16-§. Ekologik omillar','Yangi nav va zotlar yaratilishi qaysi omilga misol?','Antropogen','["Abiotik","Biotik","Tabiiy"]','Inson faoliyati natijasi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('502b6048-e473-a2e7-efc5-3f925a3ed8f3','afc0878d-2e06-f904-2b76-e6ed41841c55',4,'16-§. Ekologik omillar','Sudralib yuruvchilar muguz tangachasi nimaga yordam beradi?','Cho''lda suv bug''lanishi va issiqdan saqlanishga','["Suzishga","Uchishga","Yorug''likni yutishga"]','Moslashuvga misol.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('7146c137-b879-ed59-ec03-b5fc7335590a','afc0878d-2e06-f904-2b76-e6ed41841c55',5,'16-§. Ekologik omillar','Biotsenozning produtsentlari kimlar?','Yashil o''simliklar','["O''txo''r hayvonlar","Yirtqichlar","Bakteriyalar"]','Organik modda hosil qiladilar.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4795acaa-c9b1-d415-dbd1-754dfb433411','afc0878d-2e06-f904-2b76-e6ed41841c55',6,'16-§. Ekologik omillar','Redutsentlarga kimlar kiradi?','Bakteriya va zamburug''lar','["O''txo''r hayvonlar","Yashil o''simliklar","Yirtqich qushlar"]','Ular mineral moddalargacha parchalaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('7cc00375-5fd3-1241-954c-830d041c8b1e','afc0878d-2e06-f904-2b76-e6ed41841c55',7,'16-§. Ekologik omillar','Ozuqa zanjirida chigirtka, baqa, ilon va burgut nima hisoblanadi?','Konsumentlar','["Produtsentlar","Redutsentlar","Parazitlar"]','Ular tayyor organik modda iste''mol qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('0a052c71-c7d1-5967-7cc0-dfee2dbb549f','afc0878d-2e06-f904-2b76-e6ed41841c55',8,'16-§. Ekologik omillar','Ozuqa zanjirida baqa bilan ilon o''rtasida qanday bog''liqlik bor?','Ilon baqa bilan oziqlanadi','["Baqa ilonni yeydi","Ular o''zaro bog''liq emas","Ikkalasi ham produtsent"]','Ilon baqa bilan oziqlanib, burgutga ozuqa bo''ladi.');
