insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e61dc2f2-7e84-1264-03ce-b13210f98661','fbbef260-a39e-af37-1ade-7f8e585eeb6f',0,'15–16-§ takrorlash','15-mavzuda odam organlar sistemalarini o''rgandik. Odam ozuqa zanjirida qaysi toifaga kiradi?','Konsument','["Produtsent","Redutsent","Abiotik omil"]','Odam tayyor organik modda bilan oziqlanadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('61da26fa-abf9-0c2f-2180-fb5db36848ea','fbbef260-a39e-af37-1ade-7f8e585eeb6f',1,'15–16-§ takrorlash','Odam nafas olganda kislorod yutadi. Bu kislorodning asosiy manbai nima?','Produtsent o''simliklarning fotosintezi','["Redutsentlar","Mikroblar faoliyati","Konsumentlar"]','Yashil o''simliklar kislorod ajratadi.');
