insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('793a4dc4-bbe8-95c5-23bd-d39e4600f1f5','fbbef260-a39e-af37-1ade-7f8e585eeb6f',3,'15–16-§ takrorlash','Limfa sistemasi bakteriyalarni ushlaydi. Bakteriyalar ekologik omillarning qaysi guruhiga kiradi?','Biotik','["Abiotik","Antropogen","Hech biri"]','Mikroorganizmlar – tirik omil.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('ac1043a0-1d92-a3c6-93ce-b378e4b51ae7','fbbef260-a39e-af37-1ade-7f8e585eeb6f',4,'15–16-§ takrorlash','Asalari o''simlikni changlatadi, o''simlik unga nektar beradi. Ozuqa zanjirida o''simlik asalariga nima?','Produtsent (oziq beruvchi)','["Redutsent","Konsument","Parazit"]','O''simlik – oziq yaratuvchi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e0106fc2-1c44-852b-a13d-39199a146d7e','fbbef260-a39e-af37-1ade-7f8e585eeb6f',5,'15–16-§ takrorlash','Qon aylanish sistemasi va ozuqa zanjiri: ikkalasida umumiy tamoyil qaysi?','Hamma bo''g''in bir-biriga bog''liq: biri buzilsa, qolganlarga ta''sir qiladi','["Ular bir-biriga bog''liq emas","Faqat bir qismi muhim","Ularning hech biri uzilmaydi"]','Tizimli bog''liqlik.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('ef34a14f-5be6-51e4-a14e-f2667f68bee0','fbbef260-a39e-af37-1ade-7f8e585eeb6f',6,'15–16-§ takrorlash','Adrenalin gormoni ta''siridagi qochish – bu qaysi ekologik munosabatga misol (yirtqich bilan o''lja)?','Biotik omil','["Abiotik omil","Antropogen omil","Iqlimiy"]','Yirtqichdan qochish – tirik organizmlar orasida.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('27fa4e87-b0e5-f96d-be55-d9a147c57cc7','fbbef260-a39e-af37-1ade-7f8e585eeb6f',7,'15–16-§ takrorlash','Hayvonlar (12-mavzu) tabiatda sanitar rolini bajaradi. Ozuqa zanjirida sanitar sifatida kimlar ishlaydi?','Redutsentlar (bakteriya, zamburug'')','["Faqat yirtqichlar","Faqat o''simliklar","Faqat qushlar"]','Parchalovchilar tabiatni tozalaydi.');
