insert into public.lesson_bodies(lesson_id, body) values ('5d0f776e-fc24-e9cb-5863-afac1fec974d','## Inson tabiatga qanday ta''sir qilgan?
insert into public.lessons(id, course_id, section_id, title, kind, item_id, body, xp, position) values ('73adcaf5-a3ac-0fca-36e2-0378b8891c46','70bcc0ad-19f0-0387-8586-5bdf7bf4f43e','d7fd4f46-30dd-10f2-85c6-eefcdd67caf6','{"uz":"Slayd: Inson va tabiat","ru":"Slayd: Inson va tabiat","en":"Slayd: Inson va tabiat"}','slides',null,'',10,82);
insert into public.lesson_bodies(lesson_id, body) values ('73adcaf5-a3ac-0fca-36e2-0378b8891c46','[{"h":"Tabiatning eng kuchli o''zgartiruvchisi","ic":"🧑","p":["Odam ham tabiat bolasi: nafas oladi, oziqlanadi.","Lekin u boshqa jonzotlardan farqli, tabiatni **ongli o''zgartira oladi**.","Bu foyda ham, zarar ham keltiradi."],"q":"Inson boshqa hayvonlardan qanday farqlanadi?","a":"U qurol yasaydi, olovdan foydalanadi, ekin ekadi, tabiatni tubdan o''zgartira oladi."},{"h":"Qanday yashab kelgan?","ic":"🔥","p":["Qadimda: meva, urug'', ildizmeva, xom go''sht.","Keyin: qurollar, olov, ov.","Dehqonchilik va chorvachilik – doimiy yashash joyi."],"q":"Dehqonchilik odam hayotini qanday o''zgartirdi?","a":"Odam bir joyda o''troq yasha boshladi, oziq barqaror bo''ldi, aholi ko''paydi."},{"h":"Ijobiy ta''sir","ic":"🌾","p":["Yangi o''simlik navlari.","Yangi hayvon zotlari: go''shtdor, sersut.","Oziq-ovqat mahsulotlarining ko''payishi."],"q":"Yangi nav yaratish nima uchun foydali?","a":"Hosildorlik, kasallikka chidamlilik va sifat oshadi."},{"h":"Salbiy ta''sir","ic":"🪓","p":["Ov – turlarning qirilishi.","O''rmonni ortiqcha kesish.","Havoning chiqindilardan ifloslanishi.","Cho''llarni o''zlashtirish – daryo va dengizlarning qurishi."],"q":"O''rmon kesilishining uzoq muddatli oqibatlari qanday?","a":"Kislorod kamayadi, tuproq yuvilib ketadi, hayvonlar uysiz qoladi, iqlim o''zgaradi."},{"h":"Orol dengizi","ic":"🌊","p":["Cho''llar o''zlashtirildi, g''o''za ko''p sug''orildi.","Daryolardan dengizga suv kam keldi.","Dengiz quriy boshladi – iqlim, baliqchilik va aholi salomatligiga ta''sir qildi."],"q":"Bu muammoni qanday kamaytirish mumkin?","a":"Suvni tejab sug''orish, kam suv talab qiladigan ekinlar va qurigan tubida o''simlik (saksovul) ekish."},{"h":"Isish va azon tuynugi","ic":"🌡️","p":["Transport va yoqilg''i → karbonat angidrid ko''payadi → havo isiydi → muzlik eriydi → toshqin.","Muzlatkich va konditsioner moddalari azon qatlamiga zarar beradi.","Zararli nur o''simlik, hayvon va odamga (teri o''smasi) xavfli."],"q":"Azon qatlami Yerni nimadan himoya qiladi?","a":"Quyoshning zararli nurlaridan."},{"h":"Ekologik muvozanat","ic":"⚖️","p":["Tabiat hammasi o''zaro bog''langan zanjir.","Bir narsani ortiqcha o''zgartirsak, boshqasi buziladi.","Biologiya bilimi zararni kamaytirishga yordam beradi."],"q":"Siz o''z hayotingizda tabiatga zararni kamaytirish uchun nima qila olasiz?","a":"Suv va elektrni tejash, chiqindini ajratish, daraxt ekish, plastikni kamaytirish."}]');
