insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('da1639ed-1012-a25d-ee32-9d0f49a7e231','b6f6dfa4-f1ff-940c-54fc-81cfa4fd228a',2,'17-§. Inson va tabiat','Orol dengizi nima sababdan quriy boshladi?','Cho''llar o''zlashtirilib, g''o''za ko''p sug''orilgani sababli','["Ko''p yomg''ir yoqqani sababli","Baliq ko''payganidan","Shamol kuchaygani sababli"]','Dengizga suv kam yetib keldi.');
