insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('7938506e-1d69-6411-222d-e54abf4df93b','b6f6dfa4-f1ff-940c-54fc-81cfa4fd228a',4,'17-§. Inson va tabiat','Azon qatlamining yupqalashishi nimaga sabab bo''ladi?','Zararli nurlarning yerga yetishiga','["Havoning sovishiga","Yomg''ir ko''payishiga","Dengiz sathi pasayishiga"]','Odamda teri o''smasi xavfi ortadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('dd793e76-e4d8-aa08-e7dd-68c0d243177a','b6f6dfa4-f1ff-940c-54fc-81cfa4fd228a',5,'17-§. Inson va tabiat','Muzliklar erishi qanday oqibatga olib keladi?','Ayrim joylarda suv toshqini','["Sahroning ko''payishi","Shamol to''xtashi","Suvning kamayishi"]','Dengiz va daryolarga qo''shimcha suv qo''shiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('0802d87f-aa7d-341b-4f88-b8eebfa700bc','b6f6dfa4-f1ff-940c-54fc-81cfa4fd228a',6,'17-§. Inson va tabiat','Ekologik muammolar nima sababdan ko''payadi?','Insonning tabiatga salbiy ta''siri ortgani sari','["Tabiat o''zgarmagani sababli","Hayvonlar ko''payishi sababli","O''simliklar soni oshgani sababli"]','Ekologik muvozanat buziladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('b483430a-2c24-1ac7-9839-640866dfb9f0','b6f6dfa4-f1ff-940c-54fc-81cfa4fd228a',7,'17-§. Inson va tabiat','Qadimgi odamlar olovdan nima uchun foydalanishgan?','Isinish va ovqat tayyorlash uchun','["Faqat yoritish uchun","Qurol yasash uchun","Faqat hayvonlardan qo''rqish uchun"]','Iqlim sovib borgani sababli.');
