insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('63368786-cdc6-0bf9-0514-1d6148b22876','633dc41b-f46a-70de-e9c0-d3f0827222fb',4,'16–17-§ takrorlash','Azon tuynugi zararli nur o''simlik va hayvonlarga ta''sir qiladi. Bu qaysi omil bilan bog''liq?','Antropogen omil','["Biotik omil","Tabiiy abiotik omil","Hech biri"]','Inson chiqargan moddalar sababchi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('db2719ae-6b33-f97f-2191-a463df128841','633dc41b-f46a-70de-e9c0-d3f0827222fb',5,'16–17-§ takrorlash','Nima uchun Orol dengizi qurishi nafaqat suv, balki butun biotsenozga ta''sir qiladi?','Suvga bog''liq o''simlik va hayvonlar yo''qoladi','["Faqat suv kamayadi","Hech narsa o''zgarmaydi","Qushlar ko''payadi"]','Biotsenoz muhitga bog''liq.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('6d7f8ce8-e7c5-38ef-eb50-ded7742bcf47','633dc41b-f46a-70de-e9c0-d3f0827222fb',6,'16–17-§ takrorlash','Yangi navlar yaratish (genetika) qaysi fanga bog''liq?','Genetika','["Anatomiya","Sitologiya","Mikologiya"]','Irsiyat va o''zgaruvchanlik fani.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('d8fa8c26-56b0-e60a-7a7d-a35bc1808d14','633dc41b-f46a-70de-e9c0-d3f0827222fb',7,'16–17-§ takrorlash','Redutsentlar organik chiqindini parchalaydi. Nima uchun chiqindini tabiatga tashlash baribir zararli?','Plastik kabi sun''iy chiqindilar tabiiy parchalanmaydi va muhitni ifloslantiradi','["Redutsentlar hamma chiqindini bir kunda parchalaydi","Chiqindi o''simlikka oziq bo''ladi","Chiqindi umuman zarar qilmaydi"]','Sun''iy materiallar tabiiy yo''l bilan parchalanmaydi.');
