insert into public.lesson_bodies(lesson_id, body) values ('216c3c9a-7669-51f9-c104-4799ef4a99c4','[{"h":"Nega muhofaza kerak?","ic":"🛡️","p":["Tabiat boyliklari cheksiz emas.","Ayrim turlar yo''qolish xavfi ostida.","Shuning uchun maxsus hududlar va qonunlar bor."],"q":"Bir tur yo''qolsa, uni qayta tiklab bo''ladimi?","a":"Odatda yo''q. Yo''qolgan tur butunlay yo''qoladi, shuning uchun oldini olish muhim."},{"h":"4 xil muhofaza hududi","ic":"🏞️","p":["**Qo''riqxona** – eng qattiq himoya.","**Buyurtmaxona** – cheklangan ov mumkin.","**Milliy bog''** – hordiq, lekin tabiatga zarar yo''q.","**Tabiat yodgorligi** – noyob joylar."]},{"h":"Qo''riqxona – «qulflangan» tabiat","ic":"🔒","p":["Xo''jalik faoliyati cheklangan.","Mol boqish, meva terish, ov qilish qat''iyan **taqiqlangan**.","Tabiat o''z holicha saqlanadi.","Chotqol, Nurota, Zomin, Zarafshon, Surxon, Hisor, Kitob, Qizilqum."],"q":"Nega qo''riqxonada hatto meva terish ham taqiqlangan?","a":"Meva hayvonlar uchun oziq va o''simlikning ko''payish yo''li; terib olsak, zanjir buziladi."},{"h":"Buyurtmaxona va milliy bog''","ic":"🌲","p":["**Buyurtmaxona:** ma''lum davrda ov ruxsat, ko''chatlar ko''paytirilib tarqatiladi (archa, qarag''ay, ondatra).","**Milliy bog'':** dam olish uchun; gulni uzish va iflos qilish mumkin emas."],"q":"Qo''riqxona va buyurtmaxonaning asosiy farqi nima?","a":"Qo''riqxonada ov va xo''jalik butunlay taqiqlanadi; buyurtmaxonada ma''lum davrda ov va ko''chat tarqatish mumkin."},{"h":"Tabiat yodgorliklari","ic":"🗿","p":["G''orlar, sharsharalar, buloqlar, ulkan daraxtlar, qoyatosh rasmlari.","400 dan ortiq.","Teshiktosh g''ori, Obirahmat g''ori, Xo''jakent qoyatosh rasmlari."],"q":"Teshiktosh va Obirahmat g''orlari nimasi bilan qimmatli?","a":"Qadimgi odamlar qoldiqlari va turmush izlari topilgan, ya''ni tarix va biologiya uchun muhim."},{"h":"«Qizil kitob» – ogohlantiruvchi signal","ic":"📕","p":["1979-yilda ta''sis etilgan. 1983: 1-jild, umurtqali hayvonlar, 63 tur. 1984: 2-jild, o''simliklar, 163 tur.","Unga yo''qolish xavfi ostidagi turlar kiritiladi.","Yozilgan: tuzilishi, tarqalishi, yashash tarzi, kamayish sababi."],"q":"Qizil kitob nima uchun «qizil»?","a":"Qizil rang xavf va ogohlantirish belgisi: bu turlar yo''qolish xavfi ostida."},{"h":"Qizil kitobdan misollar","ic":"🦌","p":["**Yovvoyi tok** – chorva va o''tin.","**Xolmon isirg''aguli** – gulini terish, piyozni yeyish.","**Safsan xurmosi** – yer o''zlashtirish va o''tin.","**Xongul** – to''qay kamayishi, brakonyerlik.","**Yo''rg''a tuvaloq** – ovlash taqiqlangan."],"q":"Kamayishning ko''p sababi kim? (antropogen omil)","a":"Inson: kesish, terish, ov va yer o''zlashtirish."},{"h":"Men nima qila olaman?","ic":"🌱","p":["Gullarni uzmaslik, daraxt kesmaslik, tabiatda chiqindi tashlamaslik.","Daraxt ekish, suv va elektr tejash.","Boshqalarni ham ogohlantirish."],"q":"Maktab hovlisida tabiatni asrash uchun qanday loyiha o''ylab topasiz?","a":"Masalan: daraxt ekish kuni, chiqindi ajratish qutilari, qushlar uchun uyacha qo''yish."}]');
