insert into public.lesson_bodies(lesson_id, body) values ('7c31a98a-adbe-f9f9-5dc0-fe17c6187282','[["tf","Qo''riqxona","Xo''jalik faoliyati cheklangan, ovlash qat''iyan taqiqlangan hudud",true],["tf","Buyurtmaxona","Hayvon ovlash hech qachon ruxsat etilmaydigan hudud",false],["tf","Milliy bog''","Madaniy hordiq va estetik zavq uchun hudud",true],["tf","Teshiktosh g''ori","Tabiat yodgorligi",true],["tf","«Qizil kitob»","Yo''qolish xavfi ostidagi turlar haqidagi kitob",true],["tf","Qizil kitobning 2-jildi","Umurtqali hayvonlar haqida",false],["tf","Xongul","Buxoro bug''usi, Qizil kitobga kiritilgan",true],["tf","Yovvoyi tok","Qizil kitobga kiritilmagan oddiy o''simlik",false],["type","Eng qattiq muhofaza qilinadigan hudud","qo''riqxona",["qo''riqxona","qoriqxona"]],["type","Qizil kitob qaysi yilda ta''sis etilgan (raqam)","1979",["1979"]],["type","Ma''lum davrlarda ovga ruxsat beriladigan hudud","buyurtmaxona",["buyurtmaxona"]],["type","Noyob g''or, sharshara, buloqlar qaysi hududga kiradi? (tabiat …)","yodgorligi",["yodgorligi","yodgorliklari","tabiat yodgorligi"]]]');
