insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('28c64829-580c-5034-e9fc-7a6a245e9972','74ee4545-5f2f-b86e-a747-5e938916a849',0,'18-§. Tabiatni muhofaza qilish','Muhofaza qilinadigan hududlarga qaysilar kiradi?','Qo''riqxona, buyurtmaxona, milliy bog'', tabiat yodgorliklari','["Faqat qo''riqxona","Dala va bog''lar","Shahar markazlari"]','Bu to''rt turdagi hudud.');
