insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('62690db1-3eb8-24e3-316b-a25d92fe649a','74ee4545-5f2f-b86e-a747-5e938916a849',2,'18-§. Tabiatni muhofaza qilish','Buyurtmaxonaning qo''riqxonadan farqi nima?','Ma''lum davrda ovlashga ruxsat beriladi','["Ov mutlaqo taqiqlangan","Faqat gulzor","Hech qanday farq yo''q"]','Masalan, mo''ynasi uchun ondatra ko''paytiriladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('eebf9625-6d33-8745-cca5-570699b04145','74ee4545-5f2f-b86e-a747-5e938916a849',3,'18-§. Tabiatni muhofaza qilish','Milliy bog''da nima mumkin emas?','Gullarni payhon qilish va ifloslantirish','["Dam olish","Ko''chat ekish","Manzarali gullarni parvarishlash"]','Milliy bog'' hordiq uchun, lekin tabiat zarar ko''rmasligi kerak.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('011baa77-9c7f-a9d1-bed8-bdb5292405f8','74ee4545-5f2f-b86e-a747-5e938916a849',4,'18-§. Tabiatni muhofaza qilish','Quyidagilardan qaysi biri tabiat yodgorligi?','Teshiktosh g''ori','["Chotqol qo''riqxonasi","Nurota qo''riqxonasi","Hisor qo''riqxonasi"]','G''orlar tabiat yodgorligiga kiradi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('f7efb401-372b-b7de-9774-4c1705bc86c6','74ee4545-5f2f-b86e-a747-5e938916a849',5,'18-§. Tabiatni muhofaza qilish','Qaysi qo''riqxona geologiyaga ixtisoslashgan?','Kitob davlat qo''riqxonasi','["Chotqol","Qizilqum","Zomin"]','Kitob – geologiya qo''riqxonasi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('8ff3f296-712a-9856-6495-a840baade7fb','74ee4545-5f2f-b86e-a747-5e938916a849',6,'18-§. Tabiatni muhofaza qilish','O''zbekiston «Qizil kitob»i qachon ta''sis etilgan?','1979-yilda','["1983-yilda","1984-yilda","1991-yilda"]','1983-yilda 1-jildi chiqqan.');
