insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('43b2fe86-bceb-6720-c7f5-f61f26e3b9aa','74ee4545-5f2f-b86e-a747-5e938916a849',9,'18-§. Tabiatni muhofaza qilish','Yo''rg''a tuvaloq haqida qaysi gap to''g''ri?','Cho''lda yashashga moslashgan, ovlash taqiqlangan','["Suvda yashaydi","Uchmaydi","Faqat tog''da"]','U yaxshi uchadi va suvsizlikka chidaydi.');
