insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('0ee1cabb-3afb-4964-7e0d-33139587596c','ac5c62ef-1839-60a3-3679-0c2ef49f0acd',0,'17–18-§ takrorlash','17-mavzuda antropogen salbiy ta''sirni bilgan edik. «Qizil kitob»ga kiritilgan turlarning kamayish asosiy sababi qaysi omil?','Antropogen omil','["Abiotik omil","Faqat biotik omil","Hech biri"]','Ov, kesish, o''zlashtirish – inson ta''siri.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4746ae36-7f3c-06f3-78c0-5c04003a2297','ac5c62ef-1839-60a3-3679-0c2ef49f0acd',1,'17–18-§ takrorlash','Qo''riqxona ekologik muammolarning qaysi birini kamaytirishga yordam beradi?','Turlarning qirilishini va yashash joylari yo''qolishini','["Muzliklar erishini","Faqat Orolni","Azon tuynugini"]','Hudud tabiiy holda saqlanadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('01291801-033b-15ba-2b6e-5c5e470234ae','ac5c62ef-1839-60a3-3679-0c2ef49f0acd',2,'17–18-§ takrorlash','Ozuqa zanjiri (16-mavzu) va «Qizil kitob»: bir turning yo''qolishi zanjirga qanday ta''sir qiladi?','Zanjirning boshqa halqalariga zarar yetadi','["Ta''sir qilmaydi","Zanjirni mustahkamlaydi","Faqat redutsentlarga"]','Halqa uzilsa, boshqalar ta''sirlanadi.');
