insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('e7de55e1-fedd-55fe-5cbb-cf53f5e6e74b','ac5c62ef-1839-60a3-3679-0c2ef49f0acd',5,'17–18-§ takrorlash','Yovvoyi tok va safsan xurmosi o''simlik. Ular qaysi bo''limga kiradi (yuksak, gulli)?','Yopiq urug''lilar','["Ochiq urug''lilar","Suvo''tlar","Yo''sinlar"]','Gul va meva hosil qiladi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('dea5353c-c9b4-370c-bab2-d9660baaf9a7','ac5c62ef-1839-60a3-3679-0c2ef49f0acd',6,'17–18-§ takrorlash','Olimlar turning kamayib borayotganini qaysi usul bilan aniqlaydi?','Uzoq muddat kuzatib, sonini hisoblash orqali','["Faqat taxmin qilib","Faqat mikroskopda","Hech qanday tekshirmasdan"]','Kuzatish – biologiyaning asosiy usuli.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4568a316-f204-9400-0c1d-22a9669eb413','ac5c62ef-1839-60a3-3679-0c2ef49f0acd',7,'17–18-§ takrorlash','Tabiatni asrash uchun odam qanday bilimlarga tayanishi kerak?','Biologiya va ekologiya','["Faqat matematika","Faqat tarix","Hech qanday"]','Bu fanlar tabiat qonunlarini o''rgatadi.');
