insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('4ce67ec6-07ff-c47e-5c16-b9ff95f1cadb','5434c9c5-a742-f1b8-f731-5a6c96db84b0',0,'16-§ Ekologik omillar','Cho''lda yashovchi kaltakesakning tangachasi qaysi omilga moslashuv?','Issiq va suv kamligi','["Sovuqqa","Yorug''lik yo''qligiga","Shamolga"]','Muguz tangacha suvni saqlaydi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('a8d7bd42-68cd-9885-2a70-2b60a44fe3de','5434c9c5-a742-f1b8-f731-5a6c96db84b0',1,'16-§ Ekologik omillar','Qaysi omil abiotik hisoblanadi?','Namlik','["Yirtqich hayvon","Parazit zamburug''","Daraxt kesilishi"]','Jonsiz tabiat omili.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('1b241770-51a0-2f01-a7e2-42a948812df6','5434c9c5-a742-f1b8-f731-5a6c96db84b0',2,'16-§ Ekologik omillar','Biotsenozda bakteriya va zamburug''lar qanday vazifa bajaradi?','Organik moddalarni mineral moddalarga parchalaydi','["Quyoshdan organik modda hosil qiladi","Yirtqichlik qiladi","Faqat havoni tozalaydi"]','Ular redutsentlar.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('73882c18-4c5a-a12b-9efc-1676923ba944','5434c9c5-a742-f1b8-f731-5a6c96db84b0',3,'16-§ Ekologik omillar','Quyidagi qatordan to''g''ri ozuqa zanjirini toping.','Bug''doy – chigirtka – baqa – ilon','["Ilon – baqa – chigirtka – bug''doy","Baqa – bug''doy – ilon – chigirtka","Chigirtka – ilon – bug''doy – baqa"]','Zanjir produtsentdan boshlanadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('bd8228f2-29b0-27c7-6298-1807ed602da2','5434c9c5-a742-f1b8-f731-5a6c96db84b0',4,'16-§ Ekologik omillar','Ozuqa zanjirida organik moddalarni parchalovchilar kimlar?','Redutsentlar','["Produtsentlar","O''txo''rlar","Yirtqichlar"]','Bakteriya va zamburug''lar.');
