insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('437b375d-55bd-c1cc-8dbf-763e6b3b5fdb','5434c9c5-a742-f1b8-f731-5a6c96db84b0',6,'17-§ Inson va tabiat','Azon qatlamiga qaysi manba zarar yetkazadi?','Muzlatkich va konditsioner moddalari','["Daraxtlar","Yomg''ir","Suvo''tlar"]','Natijada zararli nur yerga yetadi.');
insert into public.questions(id, item_id, position, chapter, question, correct, wrong, explanation) values ('51138947-5b67-ecd6-a71c-386922d0bead','5434c9c5-a742-f1b8-f731-5a6c96db84b0',7,'17-§ Inson va tabiat','Transport vositalari ko''payishi nimaga olib kelishi mumkin?','Karbonat angidrid ko''payib, iqlim isishiga','["Kislorod ko''payishiga","Muzliklar ko''payishiga","Suv tozalanishiga"]','Muzliklar erishi toshqin keltiradi.');
